export default " await fetch_provider_resource_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            resource_keys=[\\\"rk-1\\\"],\\n            deployment_type=DeploymentType(\\\"agent\\\"),\\n        )\\n\\n        params = adapter.list.call_args.kwargs[\\\"params\\\"]\\n        assert params.deployment_types == [DeploymentType(\\\"agent\\\")]\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments_synced\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsSynced:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=2)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_keeps_provider_confirmed_rows(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"Rows whose resource_key is in the provider's known set are kept.\\\"\\\"\\\"\\n        owner_id = uuid4()\\n        row1 = _mock_deployment_row(\\\"rk-1\\\", user_id=owner_id)\\n        row2 = _mock_deployment_row(\\\"rk-2\\\", user_id=owner_id)\\n        fv_id = uuid4()\\n        mock_list.side_effect = [[(row1, 0, []), (row2, 1, [(fv_id, \\\"snap-1\\\")])], []]\\n        mock_fetch.return_value = (\\n            {\\\"rk-1\\\", \\\"rk-2\\\"},\\n            _mock_provider_view([SimpleNamespace(id=\\\"rk-1\\\"), SimpleNamespace(id=\\\"rk-2\\\")]),\\n        )\\n        mock_count_attachments.return_value = {row1.id: 0, row2.id: 1}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, total, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 2\\n        assert accepted[0][0] is row1\\n        assert accepted[1][0] is row2\\n        assert total == 2\\n        assert provider_data_by_resource_key == {}\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_shared_rows_use_provider_owner_namespace_for_sync(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        actor_id = uuid4()\\n        owner_id = uuid4()\\n        provider_id = uuid4()\\n        row = _mock_deployment_row(\\\"rk-shared\\\", user_id=owner_id)\\n        mock_list.return_value = [(row, 0, [])]\\n        mock_fetch.return_value = ({\\\"rk-shared\\\"}, _mock_provider_view([SimpleNamespace(id=\\\"rk-shared\\\")]))\\n        mock_count_attachments.return_value = {row.id: 0}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, total, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=actor_id,\\n            row_owner_id=owner_id,\\n            provider_id=provider_id,\\n            db=db,\\n            page=1,\\n            size=1,\\n            deployment_type=None,\\n        )\\n\\n        assert accepted[0][0] is row\\n        assert total == 1\\n        assert mock_list.await_args.kwargs[\\\"user_id\\\"] == actor_id\\n        assert mock_list.await_args.kwargs[\\\"row_owner_id\\\"] == owner_id\\n        assert mock_fetch.await_args.kwargs[\\\"user_id\\\"] == owner_id\\n        assert mock_delete_unbound.await_args.kwargs[\\\"user_id\\\"] == owner_id\\n        assert mock_count_attachments.await_args.kwargs[\\\"user_id\\\"] == owner_id\\n        assert mock_count.await_args.kwargs[\\\"user_id\\\"] == actor_id\\n        assert mock_count.await_args.kwargs[\\\"row_owner_id\\\"] == owner_id\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_deletes_stale_rows(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"Rows not recognised by the provider are deleted.\\\"\\\"\\\"\\n        uid = uuid4()\\n        stale_row = _mock_deployment_row(\\\"rk-stale\\\", user_id=uid)\\n        good_row = _mock_deployment_row(\\\"rk-good\\\", user_id=uid)\\n        db = _mock_async_db()\\n\\n        # First call returns stale + good; second call returns empty (all consumed)\\n        mock_list.side_effect = [\\n            [(stale_row, 0, []), (good_row, 1, [])],\\n            [],\\n        ]\\n        mock_fetch.return_value = (\\n            {\\\"rk-good\\\"},\\n            _mock_provider_view([SimpleNamespace(id=\\\"rk-good\\\")]),\\n        )  # only rk-good is known\\n        mock_count_attachments.return_value = {good_row.id: 1}\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=uid,\\n            row_owner_id=uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 1\\n        assert accepted[0][0] is good_row\\n        assert provider_data_by_resource_key == {}\\n        mock_delete.assert_awaited_once_with(\\n            db,\\n            user_id=uid,\\n            deployment_id=stale_row.id,\\n        )\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=2)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_merges_list_item_provider_data_across_refill_rounds(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"Per-item provider_data is collected from each provider sync round.\\\"\\\"\\\"\\n\\n        class _ProviderDataMapper(_NoSnapshotBindingMapper):\\n            def extract_list_item_provider_data(self, provider_view) -> dict[str, dict[str, Any]]:\\n                return {str(item.id): item.provider_data for item in provider_view.deployments}\\n\\n        owner_id = uuid4()\\n        stale_row = _mock_deployment_row(\\\"rk-stale\\\", user_id=owner_id)\\n        row1 = _mock_deployment_row(\\\"rk-1\\\", user_id=owner_id)\\n        row2 = _mock_deployment_row(\\\"rk-2\\\", user_id=owner_id)\\n        mock_list.side_effect = [\\n            [(stale_row, 0, []), (row1, 0, [])],\\n            [(row2, 0, [])],\\n        ]\\n        mock_fetch.side_effect = [\\n            (\\n                {\\\"rk-1\\\"},\\n                _mock_provider_view([SimpleNamespace(id=\\\"rk-1\\\", provider_data={\\\"environments\\\": [\\\"draft\\\"]})]),\\n            ),\\n            (\\n                {\\\"rk-2\\\"},\\n                _mock_provider_view([SimpleNamespace(id=\\\"rk-2\\\", provider_data={\\\"environments\\\": [\\\"live\\\"]})]),\\n            ),\\n        ]\\n        mock_count_attachments.return_value = {row1.id: 0, row2.id: 0}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, total, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_ProviderDataMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=2,\\n            deployment_type=None,\\n        )\\n\\n        assert [row.resource_key for row, _, _ in accepted] == [\\\"rk-1\\\", \\\"rk-2\\\"]\\n        assert total == 2\\n        assert provider_data_by_resource_key == {\\n            \\\"rk-1\\\": {\\\"environments\\\": [\\\"draft\\\"]},\\n            \\\"rk-2\\\": {\\\"environments\\\": [\\\"live\\\"]},\\n        }\\n        mock_delete.assert_awaited_once()\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.update_deployment_metadata_batch\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_passes_provider_description_before_batch_metadata_sync(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_update_metadata_batch,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"Provider descriptions are passed through before local metadata batch sync.\\\"\\\"\\\"\\n        long_description = \\\"x\\\" * 501\\n\\n        class _MetadataMapper(_NoSnapshotBindingMapper):\\n            def extract_metadata_for_list(self, provider_view) -> dict[str, dict[str, Any]]:\\n                _ = provider_view\\n                return {\\n                    \\\"rk-1\\\": {\\n                        \\\"display_name\\\": \\\"Provider Name\\\",\\n                        \\\"description\\\": long_description,\\n                    }\\n                }\\n\\n        row = _mock_deployment_row(\\\"rk-1\\\")\\n        mock_list.return_value = [(row, 0, [])]\\n        mock_fetch.return_value = ({\\\"rk-1\\\"}, _mock_provider_view([SimpleNamespace(id=\\\"rk-1\\\")]))\\n        mock_count_attachments.return_value = {row.id: 0}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, total, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_MetadataMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=1,\\n            deployment_type=None,\\n        )\\n\\n        assert [row.resource_key for row, _, _ in accepted] == [\\\"rk-1\\\"]\\n        assert total == 1\\n        mock_update_metadata_batch.assert_awaited_once()\\n        updates = mock_update_metadata_batch.call_args.kwargs[\\\"deployment_updates\\\"]\\n        assert updates[0].display_name == \\\"Provider Name\\\"\\n        assert updates[0].description == long_description\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_empty_batch_stops_loop(self, mock_list, mock_fetch, mock_count):\\n        \\\"\\\"\\\"An empty batch from the DB ends the loop.\\\"\\\"\\\"\\n        mock_list.return_value = []\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, total, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=BaseDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert accepted == []\\n        assert total == 0\\n        assert provider_data_by_resource_key == {}\\n        mock_fetch.assert_not_awaited()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=2)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_mismatched_type_not_in_known_skips_without_deleting(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"Row not in known but with a different local type is skipped, not deleted.\\n\\n        The provider was filtered by type, so absence only means the type didn't\\n        match \u2014 the resource may still exist on the provider.\\n        \\\"\\\"\\\"\\n        row_match = _mock_deployment_row(\\\"rk-1\\\", deployment_type=\\\"agent\\\")\\n        row_other = _mock_deployment_row(\\\"rk-2\\\", deployment_type=\\\"other\\\")\\n        mock_list.side_effect = [\\n            [(row_match, 0, []), (row_other, 0, [])],\\n            [],\\n        ]\\n        # Provider filtered by \\\"agent\\\" \u2014 only rk-1 returned\\n        mock_fetch.return_value = ({\\\"rk-1\\\"}, _mock_provider_view([SimpleNamespace(id=\\\"rk-1\\\")]))\\n        mock_count_attachments.return_value = {row_match.id: 0}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import DeploymentType, list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=DeploymentType(\\\"agent\\\"),\\n        )\\n\\n        assert len(accepted) == 1\\n        assert accepted[0][0] is row_match\\n        # rk-2 was NOT deleted \u2014 just skipped\\n        mock_delete.assert_not_awaited()\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_cursor_does_not_advance_on_delete(\\n        self,\\n        mock_list,\\n        mock_fetch,\\n        mock_delete,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,\\n    ):\\n        \\\"\\\"\\\"When a stale row is deleted the cursor stays put (offset doesn't increment).\\\"\\\"\\\"\\n        stale = _mock_deployment_row(\\\"rk-stale\\\")\\n        good = _mock_deployment_row(\\\"rk-good\\\")\\n\\n        # First batch: stale row only. Cursor should stay at 0 for next fetch.\\n        # Second batch: good row at the same offset (because deletion shifted it).\\n        mock_list.side_effect = [\\n            [(stale, 0, [])],\\n            [(good, 0, [])],\\n            [],\\n        ]\\n        mock_fetch.side_effect = [\\n            (set(), None),  # stale not known\\n            ({\\\"rk-good\\\"}, _mock_provider_view([SimpleNamespace(id=\\\"rk-good\\\")])),  # good is known\\n        ]\\n        mock_count_attachments.return_value = {good.id: 0}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        # Both list_deployments_page calls should use offset=0\\n        offsets = [call.kwargs[\\\"offset\\\"] for call in mock_list.call_args_list[:2]]\\n        assert offsets == [0, 0], f\\\"Expected cursor to stay at 0 after deletion, got offsets={offsets}\\\"\\n        assert len(accepted) == 1\\n        assert accepted[0][0] is good\\n        mock_delete.assert_awaited_once()\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=5)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_page_offset_calculation(self, mock_list, mock_fetch, mock_count):\\n        \\\"\\\"\\\"Page 2 with size 5 should start at offset 5.\\\"\\\"\\\"\\n        mock_list.return_value = []\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=BaseDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            page=2,\\n            size=5,\\n            deployment_type=None,\\n        )\\n\\n        assert mock_list.call_args.kwargs[\\\"offset\\\"] == 5\\n        mock_fetch.assert_not_awaited()\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.delete_deployment_by_id\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_stops_after_one_refill(self, mock_list, mock_fetch, mock_delete, mock_count):\\n        \\\"\\\"\\\"Only two sync rounds run: initial fetch + one refill.\\\"\\\"\\\"\\n        stale = _mock_deployment_row(\\\"rk-stale\\\")\\n        # Always return a stale row \u2014 the function should still stop after 2 rounds.\\n        mock_list.return_value = [(stale, 0, [])]\\n        mock_fetch.return_value = (set(), None)  # never known\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=_NoSnapshotBindingMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            page=1,\\n            size=2,\\n            deployment_type=None,\\n        )\\n\\n        assert accepted == []\\n        assert mock_list.call_count == 2\\n        assert mock_delete.await_count == 2\\n        mock_count.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=3)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_passes_flow_version_ids_through(self, mock_list, mock_fetch, mock_count):\\n        \\\"\\\"\\\"flow_version_ids are forwarded to list_deployments_page and count.\\\"\\\"\\\"\\n        mock_list.return_value = []\\n        fv_ids = [uuid4(), uuid4()]\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=BaseDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n            flow_version_ids=fv_ids,\\n        )\\n\\n        assert mock_list.call_args.kwargs[\\\"flow_version_ids\\\"] == fv_ids\\n        assert mock_count.call_args.kwargs[\\\"flow_version_ids\\\"] == fv_ids\\n        mock_fetch.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_passes_project_id_through(self, mock_list, mock_fetch, mock_count):\\n        \\\"\\\"\\\"project_id is forwarded to list_deployments_page and count.\\\"\\\"\\\"\\n        mock_list.return_value = []\\n        project_id = uuid4()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=BaseDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n            project_id=project_id,\\n        )\\n\\n        assert mock_list.call_args.kwargs[\\\"project_id\\\"] == project_id\\n        assert mock_count.call_args.kwargs[\\\"project_id\\\"] == project_id\\n        mock_fetch.assert_not_awaited()\\n\\n\\nclass _FakeMapper(BaseDeploymentMapper):\\n    def util_create_snapshot_bindings(self, *, result) -> CreateSnapshotBindings:  # type: ignore[override]\\n        provider_result = result.provider_result\\n        if not isinstance(provider_result, dict):\\n            return CreateSnapshotBindings()\\n        snapshot_bindings = provider_result.get(\\\"snapshot_bindings\\\")\\n        if not isinstance(snapshot_bindings, list):\\n            return CreateSnapshotBindings()\\n        resolved: list[CreateSnapshotBinding] = []\\n        for binding in snapshot_bindings:\\n            if not isinstance(binding, dict):\\n                continue\\n            source_ref = str(binding.get(\\\"source_ref\\\") or \\\"\\\").strip()\\n            snapshot_id = str(binding.get(\\\"snapshot_id\\\") or \\\"\\\").strip()\\n            if source_ref and snapshot_id:\\n                resolved.append(\\n                    CreateSnapshotBinding(\\n                        source_ref=source_ref,\\n                        snapshot_id=snapshot_id,\\n                    )\\n                )\\n        return CreateSnapshotBindings(snapshot_bindings=resolved)\\n\\n    def util_update_snapshot_bindings(self, *, result) -> UpdateSnapshotBindings:  # type: ignore[override]\\n        provider_result = result.provider_result\\n        if not isinstance(provider_result, dict):\\n            return UpdateSnapshotBindings()\\n        snapshot_bindings = provider_result.get(\\\"added_snapshot_bindings\\\")\\n        if not isinstance(snapshot_bindings, list):\\n            return UpdateSnapshotBindings()\\n        resolved: list[UpdateSnapshotBinding] = []\\n        for binding in snapshot_bindings:\\n            if not isinstance(binding, dict):\\n                continue\\n            source_ref = str(binding.get(\\\"source_ref\\\") or \\\"\\\").strip()\\n            snapshot_id = str(binding.get(\\\"snapshot_id\\\") or \\\"\\\").strip()\\n            if source_ref and snapshot_id:\\n                resolved.append(\\n                    UpdateSnapshotBinding(\\n                        source_ref=source_ref,\\n                        snapshot_id=snapshot_id,\\n                    )\\n                )\\n        return UpdateSnapshotBindings(snapshot_bindings=resolved)\\n\\n\\nclass TestCreateSnapshotMapping:\\n    def test_resolve_snapshot_map_for_create_maps_source_ref_to_flow_version_ids(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_snapshot_map_for_create\\n\\n        flow_version_ids = [uuid4(), uuid4()]\\n        resolved = resolve_snapshot_map_for_create(\\n            deployment_mapper=_FakeMapper(),\\n            result=DeploymentCreateResult(\\n                id=\\\"provider-id\\\",\\n                type=DeploymentType.AGENT,\\n                provider_result={\\n                    \\\"snapshot_bindings\\\": [\\n                        {\\\"source_ref\\\": str(flow_version_ids[0]), \\\"snapshot_id\\\": \\\"snap-1\\\"},\\n                        {\\\"source_ref\\\": str(flow_version_ids[1]), \\\"snapshot_id\\\": \\\"snap-2\\\"},\\n                    ]\\n                },\\n            ),\\n            flow_version_ids=flow_version_ids,\\n        )\\n\\n        assert resolved == {\\n            flow_version_ids[0]: \\\"snap-1\\\",\\n            flow_version_ids[1]: \\\"snap-2\\\",\\n        }\\n\\n    def test_resolve_snapshot_map_for_create_rejects_missing_bindings(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_snapshot_map_for_create\\n\\n        with pytest.raises(HTTPException, match=\\\"missing required snapshot bindings\\\"):\\n            resolve_snapshot_map_for_create(\\n                deployment_mapper=_FakeMapper(),\\n                result=DeploymentCreateResult(id=\\\"provider-id\\\", type=DeploymentType.AGENT),\\n                flow_version_ids=[uuid4()],\\n            )\\n\\n\\nclass TestUpdateSnapshotMapping:\\n    def test_resolve_added_snapshot_bindings_for_update_maps_source_ref(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_added_snapshot_bindings_for_update\\n\\n        flow_version_ids = [uuid4(), uuid4()]\\n        resolved = resolve_added_snapshot_bindings_for_update(\\n            deployment_mapper=_FakeMapper(),\\n            added_flow_version_ids=flow_version_ids,\\n            result=DeploymentUpdateResult(\\n                id=\\\"provider-id\\\",\\n                provider_result={\\n                    \\\"name\\\": \\\"agent_api_name\\\",\\n                    \\\"added_snapshot_bindings\\\": [\\n                        {\\\"source_ref\\\": str(flow_version_ids[0]), \\\"snapshot_id\\\": \\\"snap-1\\\"},\\n                        {\\\"source_ref\\\": str(flow_version_ids[1]), \\\"snapshot_id\\\": \\\"snap-2\\\"},\\n                    ],\\n                },\\n            ),\\n        )\\n\\n        assert resolved == [\\n            (flow_version_ids[0], \\\"snap-1\\\"),\\n            (flow_version_ids[1], \\\"snap-2\\\"),\\n        ]\\n\\n    def test_resolve_added_snapshot_bindings_for_update_rejects_unexpected_source_ref(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_added_snapshot_bindings_for_update\\n\\n        with pytest.raises(HTTPException, match=\\\"Unexpected source_ref in update snapshot bindings\\\"):\\n            resolve_added_snapshot_bindings_for_update(\\n                deployment_mapper=_FakeMapper(),\\n                added_flow_version_ids=[uuid4()],\\n                result=DeploymentUpdateResult(\\n                    id=\\\"provider-id\\\",\\n                    provider_result={\\n                        \\\"name\\\": \\\"agent_api_name\\\",\\n                        \\\"added_snapshot_bindings\\\": [\\n                            {\\\"source_ref\\\": \\\"other\\\", \\\"snapshot_id\\\": \\\"snap-extra\\\"},\\n                        ],\\n                    },\\n                ),\\n            )\\n\\n    def test_resolve_added_snapshot_bindings_for_update_rejects_missing_expected_source_ref(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_added_snapshot_bindings_for_update\\n\\n        with pytest.raises(HTTPException, match=\\\"Missing snapshot bindings for added flow versions\\\"):\\n            resolve_added_snapshot_bindings_for_update(\\n                deployment_mapper=_FakeMapper(),\\n                added_flow_version_ids=[uuid4()],\\n                result=DeploymentUpdateResult(\\n                    id=\\\"provider-id\\\",\\n                    provider_result={\\n                        \\\"name\\\": \\\"agent_api_name\\\",\\n                        \\\"added_snapshot_bindings\\\": [],\\n                    },\\n                ),\\n            )\\n\\n    def test_resolve_snapshot_map_for_create_rejects_unexpected_source_ref(self):\\n        from langflow.api.v1.mappers.deployments.helpers import resolve_snapshot_map_for_create\\n\\n        with pytest.raises(HTTPException, match=\\\"Unexpected source_ref\\\"):\\n            resolve_snapshot_map_for_create(\\n                deployment_mapper=_FakeMapper(),\\n                result=DeploymentCreateResult(\\n                    id=\\\"provider-id\\\",\\n                    type=DeploymentType.AGENT,\\n                    provider_result={\\\"snapshot_bindings\\\": [{\\\"source_ref\\\": \\\"other-ref\\\", \\\"snapshot_id\\\": \\\"snap-1\\\"}]},\\n                ),\\n                flow_version_ids=[uuid4()],\\n            )\\n\\n\\ndef test_watsonx_mapper_util_created_snapshot_ids_uses_adapter_slot():\\n    created = WatsonxOrchestrateDeploymentMapper().util_created_snapshot_ids(\\n        result=DeploymentUpdateResult(\\n            id=\\\"provider-id\\\",\\n            provider_result={\\n                \\\"name\\\": \\\"agent_api_name\\\",\\n                \\\"display_name\\\": \\\"Agent API Name\\\",\\n                \\\"created_snapshot_ids\\\": [\\\"snap-1\\\", \\\"snap-2\\\"],\\n            },\\n        ),\\n    )\\n\\n    assert created.ids == [\\\"snap-1\\\", \\\"snap-2\\\"]\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_from_provider_view():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    provider_view = _mock_provider_view(\\n        [\\n            SimpleNamespace(id=\\\"agent-1\\\", provider_data=_wxo_deployment_provider_data(tool_ids=[\\\"tool-1\\\", \\\"tool-2\\\"])),\\n            SimpleNamespace(id=\\\"agent-2\\\", provider_data=_wxo_deployment_provider_data(tool_ids=[\\\"tool-3\\\"])),\\n        ]\\n    )\\n\\n    bindings = mapper.extract_snapshot_bindings(provider_view)\\n    assert [(binding.resource_key, binding.snapshot_id) for binding in bindings] == [\\n        (\\\"agent-1\\\", \\\"tool-1\\\"),\\n        (\\\"agent-1\\\", \\\"tool-2\\\"),\\n        (\\\"agent-2\\\", \\\"tool-3\\\"),\\n    ]\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_requires_contract_fields():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    provider_view = _mock_provider_view(\\n        [\\n            SimpleNamespace(id=\\\"agent-1\\\", provider_data={}),\\n        ]\\n    )\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.extract_snapshot_bindings(provider_view)\\n    assert exc_info.value.status_code == 500\\n    assert \\\"Missing required field 'display_name'\\\" in str(exc_info.value.detail)\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_requires_provider_data_object():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    provider_view = _mock_provider_view(\\n        [\\n            SimpleNamespace(id=\\\"agent-1\\\", provider_data=\\\"bad-payload-type\\\"),\\n        ]\\n    )\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.extract_snapshot_bindings(provider_view)\\n    assert exc_info.value.status_code == 500\\n    assert \\\"Unexpected result while reading deployment list item metadata\\\" in str(exc_info.value.detail)\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_allows_empty_tool_ids():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    provider_view = _mock_provider_view(\\n        [\\n            SimpleNamespace(id=\\\"agent-1\\\", provider_data=_wxo_deployment_provider_data(tool_ids=[])),\\n        ]\\n    )\\n\\n    bindings = mapper.extract_snapshot_bindings(provider_view)\\n    assert bindings == []\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_for_get():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    get_result = DeploymentGetResult(\\n        id=\\\"agent-1\\\",\\n        name=\\\"agent-name\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\\"tool_ids\\\": [\\\"tool-1\\\", \\\"tool-2\\\"]},\\n    )\\n\\n    bindings = mapper.extract_snapshot_bindings_for_get(get_result, resource_key=\\\"agent-1\\\")\\n\\n    assert [(binding.resource_key, binding.snapshot_id) for binding in bindings] == [\\n        (\\\"agent-1\\\", \\\"tool-1\\\"),\\n        (\\\"agent-1\\\", \\\"tool-2\\\"),\\n    ]\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_for_get_requires_tool_ids():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    get_result = DeploymentGetResult(\\n        id=\\\"agent-1\\\",\\n        name=\\\"agent-name\\\",\\n        type=\\\"agent\\\",\\n        provider_data={},\\n    )\\n\\n    with pytest.raises(\\n        ValueError,\\n        match=r\\\"^An internal error occured\\\\. provider_data must contain 'tool_ids' from wxO adapter for get\\\\(\\\\)\\\\.$\\\",\\n    ):\\n        mapper.extract_snapshot_bindings_for_get(get_result, resource_key=\\\"agent-1\\\")\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_for_get_requires_provider_data():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    get_result = DeploymentGetResult(\\n        id=\\\"agent-1\\\",\\n        name=\\\"agent-name\\\",\\n        type=\\\"agent\\\",\\n        provider_data=None,\\n    )\\n\\n    with pytest.raises(\\n        ValueError,\\n        match=r\\\"^An internal error occured\\\\. provider_data is required from wxO adapter for get\\\\(\\\\)\\\\.$\\\",\\n    ):\\n        mapper.extract_snapshot_bindings_for_get(get_result, resource_key=\\\"agent-1\\\")\\n\\n\\ndef test_watsonx_mapper_extract_snapshot_bindings_for_get_requires_tool_ids_list_type():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n    get_result = DeploymentGetResult(\\n        id=\\\"agent-1\\\",\\n        name=\\\"agent-name\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\\"tool_ids\\\": \\\"tool-1\\\"},\\n    )\\n\\n    with pytest.raises(\\n        ValueError,\\n        match=(\\n            r\\\"^An internal error occured\\\\. provider_data\\\\['tool_ids'\\\\] must be a list \\\"\\n            r\\\"from wxO adapter for get\\\\(\\\\)\\\\.$\\\"\\n        ),\\n    ):\\n        mapper.extract_snapshot_bindings_for_get(get_result, resource_key=\\\"agent-1\\\")\\n\\n\\ndef test_watsonx_mapper_shape_deployment_get_data_hides_internal_sync_fields():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n\\n    shaped = mapper.shape_deployment_get_data(\\n        {\\n            \\\"llm\\\": \\\"my-llm\\\",\\n            \\\"display_name\\\": \\\"Agent Name\\\",\\n            \\\"description\\\": \\\"Provider description\\\",\\n            \\\"tool_ids\\\": [\\\"tool-1\\\", \\\"tool-2\\\"],\\n            \\\"environments\\\": [\\\"draft\\\"],\\n        },\\n        name=\\\"agent-name\\\",\\n    )\\n\\n    assert shaped == {\\n        \\\"llm\\\": \\\"my-llm\\\",\\n        \\\"name\\\": \\\"agent-name\\\",\\n        \\\"display_name\\\": \\\"Agent Name\\\",\\n        \\\"environments\\\": [\\\"draft\\\"],\\n    }\\n\\n\\ndef test_watsonx_mapper_shape_deployment_get_data_requires_provider_data():\\n    mapper = WatsonxOrchestrateDeploymentMapper()\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        mapper.shape_deployment_get_data(None)\\n    assert exc_info.value.status_code == 500\\n    assert \\\"Empty result while reading deployment metadata\\\" in str(exc_info.value.detail)\\n\\n\\ndef test_base_mapper_extract_snapshot_bindings_for_get_raises_not_implemented():\\n    \\\"\\\"\\\"Locks in the destructive-deletion safety contract for GET-sync.\\n\\n    The base implementation MUST raise ``NotImplementedError`` rather than\\n    return ``[]``. An empty list would flow into\\n    ``delete_unbound_attachments`` (which treats empty ``bindings`` plus\\n    non-empty ``deployment_ids`` as a wipe of every local attachment for\\n    the GETted deployment). Raising prevents that destructive\\n    interpretation for any provider that hasn't overridden the method \u2014\\n    the GET call site treats ``NotImplementedError`` as a mapper implementation\\n    error instead of wiping local attachment state.\\n    \\\"\\\"\\\"\\n    mapper = BaseDeploymentMapper()\\n    get_result = DeploymentGetResult(\\n        id=\\\"agent-1\\\",\\n        name=\\\"agent-name\\\",\\n        type=\\\"agent\\\",\\n        provider_data={\\\"tool_ids\\\": [\\\"tool-1\\\"]},\\n    )\\n\\n    with pytest.raises(NotImplementedError, match=\\\"not configured for syncing snapshots for a deployment\\\"):\\n        mapper.extract_snapshot_bindings_for_get(get_result, resource_key=\\\"agent-1\\\")\\n\\n\\ndef test_base_mapper_extract_snapshot_bindings_raises_not_implemented():\\n    \\\"\\\"\\\"Locks in the destructive-deletion safety contract for list-sync.\\n\\n    The base implementation MUST raise ``NotImplementedError`` rather than\\n    return ``[]``. An empty list would flow into\\n    ``delete_unbound_attachments`` (which treats empty ``bindings`` plus\\n    non-empty ``deployment_ids`` as a wipe of every local attachment for\\n    those deployments). Raising prevents that destructive interpretation\\n    for any provider that hasn't overridden the method.\\n    \\\"\\\"\\\"\\n    mapper = BaseDeploymentMapper()\\n    provider_view = _mock_provider_view(\\n        [\\n            SimpleNamespace(id=\\\"agent-1\\\", provider_data={\\\"tool_ids\\\": [\\\"tool-1\\\"]}),\\n        ]\\n    )\\n\\n    with pytest.raises(NotImplementedError, match=\\\"not configured for syncing snapshots for multiple deployments\\\"):\\n        mapper.extract_snapshot_bindings(provider_view)\\n\\n\\ndef test_resolve_flow_version_patch_for_update_watsonx_operations():\\n    from langflow.api.v1.mappers.deployments.helpers import resolve_flow_version_patch_for_update\\n\\n    add_id = uuid4()\\n    unbind_only_id = uuid4()\\n    remove_id = uuid4()\\n    add_ids, remove_ids = resolve_flow_version_patch_for_update(\\n        deployment_mapper=WatsonxOrchestrateDeploymentMapper(),\\n        payload=DeploymentUpdateRequest(\\n            provider_data={\\n                \\\"llm\\\": \\\"test-llm\\\",\\n                \\\"upsert_flows\\\": [\\n                    {\\n                        \\\"flow_version_id\\\": str(add_id),\\n                        \\\"add_app_ids\\\": [\\\"app-one\\\"],\\n                        \\\"remove_app_ids\\\": [],\\n                    },\\n                    {\\n                        \\\"flow_version_id\\\": str(unbind_only_id),\\n                        \\\"add_app_ids\\\": [],\\n                        \\\"remove_app_ids\\\": [\\\"app-one\\\"],\\n                    },\\n                ],\\n                \\\"remove_flows\\\": [str(remove_id)],\\n            }\\n        ),\\n    )\\n\\n    assert add_ids == [add_id]\\n    assert remove_ids == [remove_id]\\n\\n\\nclass _FakeCountExecResult:\\n    def __init__(self, count_value: int):\\n        self._count_value = count_value\\n\\n    def one(self):\\n        return self._count_value\\n\\n\\nclass _FakeCountDb:\\n    def __init__(self, count_value: int):\\n        self._count_value = count_value\\n\\n    async def exec(self, _statement):\\n        return _FakeCountExecResult(self._count_value)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_validate_project_scoped_flow_version_ids_accepts_all_ids():\\n    from langflow.api.v1.mappers.deployments.helpers import validate_project_scoped_flow_version_ids\\n\\n    flow_version_id = uuid4()\\n    await validate_project_scoped_flow_version_ids(\\n        flow_version_ids=[flow_version_id, flow_version_id],\\n        user_id=uuid4(),\\n        project_id=uuid4(),\\n        db=_FakeCountDb(count_value=1),  # type: ignore[arg-type]\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_validate_project_scoped_flow_version_ids_rejects_out_of_project_ids():\\n    from langflow.api.v1.mappers.deployments.helpers import validate_project_scoped_flow_version_ids\\n\\n    with pytest.raises(HTTPException, match=\\\"selected project\\\"):\\n        await validate_project_scoped_flow_version_ids(\\n            flow_version_ids=[uuid4(), uuid4()],\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            db=_FakeCountDb(count_value=1),  # type: ignore[arg-type]\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# fetch_provider_snapshot_keys\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _mock_snapshot_item(*, item_id: str, name: str = \\\"irrelevant\\\") -> SimpleNamespace:\\n    return SimpleNamespace(id=item_id, name=name)\\n\\n\\ndef _mock_snapshot_view(items: list) -> SimpleNamespace:\\n    return SimpleNamespace(snapshots=items)\\n\\n\\nclass TestFetchProviderSnapshotKeys:\\n    @pytest.mark.asyncio\\n    async def test_returns_recognized_snapshot_ids(self):\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = _mock_snapshot_view(\\n            [_mock_snapshot_item(item_id=\\\"snap-1\\\"), _mock_snapshot_item(item_id=\\\"snap-2\\\")]\\n        )\\n\\n        from langflow.api.v1.mappers.deployments.sync import fetch_provider_snapshot_keys\\n\\n        result = await fetch_provider_snapshot_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            snapshot_ids=[\\\"snap-1\\\", \\\"snap-2\\\", \\\"snap-3\\\"],\\n        )\\n\\n        assert result == {\\\"snap-1\\\", \\\"snap-2\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_snapshot_ids_returns_empty_set(self):\\n        adapter = AsyncMock()\\n\\n        from langflow.api.v1.mappers.deployments.sync import fetch_provider_snapshot_keys\\n\\n        result = await fetch_provider_snapshot_keys(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            db=AsyncMock(),\\n            snapshot_ids=[],\\n        )\\n\\n        assert result == set()\\n        adapter.list_snapshots.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_provider_error_raises_500(self):\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.side_effect = RuntimeError(\\\"provider down\\\")\\n\\n        from langflow.api.v1.mappers.deployments.sync import fetch_provider_snapshot_keys\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await fetch_provider_snapshot_keys(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                db=AsyncMock(),\\n                snapshot_ids=[\\\"snap-1\\\"],\\n            )\\n\\n        assert exc_info.value.status_code == 500\\n\\n    @pytest.mark.asyncio\\n    async def test_falsy_snapshot_id_from_provider_raises_value_error(self):\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = _mock_snapshot_view([_mock_snapshot_item(item_id=\\\"\\\")])\\n\\n        from langflow.api.v1.mappers.deployments.sync import fetch_provider_snapshot_keys\\n\\n        with pytest.raises(ValueError, match=\\\"snapshot with an empty id\\\"):\\n            await fetch_provider_snapshot_keys(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                db=AsyncMock(),\\n                snapshot_ids=[\\\"snap-1\\\"],\\n            )\\n\\n\\n# ---------------------------------------------------------------------------\\n# sync_attachment_snapshot_ids\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _mock_attachment(*, flow_version_id=None, provider_snapshot_id=None, deployment_id=None) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        flow_version_id=flow_version_id or uuid4(),\\n        provider_snapshot_id=provider_snapshot_id,\\n        deployment_id=deployment_id or uuid4(),\\n    )\\n\\n\\nclass TestSyncAttachmentSnapshotIds:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployment_attachments_by_keys\\\", new_callable=AsyncMock)\\n    async def test_deletes_stale_attachments(self, mock_delete_att):\\n        \\\"\\\"\\\"Attachments with snapshot IDs not in the known set are deleted.\\\"\\\"\\\"\\n        dep_id = uuid4()\\n        uid = uuid4()\\n        fv_good = uuid4()\\n        fv_stale_a = uuid4()\\n        fv_stale_b = uuid4()\\n        attachments = [\\n            _mock_attachment(flow_version_id=fv_good, provider_snapshot_id=\\\"snap-good\\\", deployment_id=dep_id),\\n            _mock_attachment(flow_version_id=fv_stale_a, provider_snapshot_id=\\\"snap-stale\\\", deployment_id=dep_id),\\n            _mock_attachment(flow_version_id=fv_stale_b, provider_snapshot_id=\\\"snap-stale\\\", deployment_id=dep_id),\\n        ]\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_attachment_snapshot_ids\\n\\n        counts = await sync_attachment_snapshot_ids(\\n            user_id=uid,\\n            attachments=attachments,\\n            known_snapshot_ids={\\\"snap-good\\\"},\\n            db=AsyncMock(),\\n        )\\n\\n        assert counts[dep_id] == 1\\n        mock_delete_att.assert_awaited_once()\\n        call_kwargs = mock_delete_att.call_args.kwargs\\n        assert call_kwargs[\\\"user_id\\\"] == uid\\n        key_batch = call_kwargs[\\\"attachment_key_batch\\\"]\\n        key_pairs = [(key.deployment_id, key.flow_version_id) for key in key_batch.keys]\\n        assert key_pairs == [\\n            (dep_id, fv_stale_a),\\n            (dep_id, fv_stale_b),\\n        ]\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployment_attachments_by_keys\\\", new_callable=AsyncMock)\\n    async def test_raises_on_falsy_snapshot_id(self, mock_delete_att):\\n        \\\"\\\"\\\"Attachments with empty provider_snapshot_id raise data-integrity errors.\\\"\\\"\\\"\\n        dep_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=None, deployment_id=dep_id),\\n            _mock_attachment(provider_snapshot_id=\\\"\\\", deployment_id=dep_id),\\n        ]\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_attachment_snapshot_ids\\n\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must be non-empty\\\"):\\n            await sync_attachment_snapshot_ids(\\n                user_id=uuid4(),\\n                attachments=attachments,\\n                known_snapshot_ids=set(),\\n                db=AsyncMock(),\\n            )\\n        mock_delete_att.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployment_attachments_by_keys\\\", new_callable=AsyncMock)\\n    async def test_falsy_snapshot_short_circuits_before_batch_delete(self, mock_delete_att):\\n        \\\"\\\"\\\"If any attachment has a falsy snapshot id, sync aborts before deleting stale keys.\\\"\\\"\\\"\\n        dep_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-known\\\", deployment_id=dep_id),\\n            _mock_attachment(provider_snapshot_id=\\\"snap-stale\\\", deployment_id=dep_id),\\n            _mock_attachment(provider_snapshot_id=\\\"   \\\", deployment_id=dep_id),\\n        ]\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_attachment_snapshot_ids\\n\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must be non-empty\\\"):\\n            await sync_attachment_snapshot_ids(\\n                user_id=uuid4(),\\n                attachments=attachments,\\n                known_snapshot_ids={\\\"snap-known\\\"},\\n                db=AsyncMock(),\\n            )\\n        mock_delete_att.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployment_attachments_by_keys\\\", new_callable=AsyncMock)\\n    async def test_all_snapshots_known_nothing_deleted(self, mock_delete_att):\\n        dep_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=dep_id),\\n            _mock_attachment(provider_snapshot_id=\\\"snap-2\\\", deployment_id=dep_id),\\n        ]\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_attachment_snapshot_ids\\n\\n        counts = await sync_attachment_snapshot_ids(\\n            user_id=uuid4(),\\n            attachments=attachments,\\n            known_snapshot_ids={\\\"snap-1\\\", \\\"snap-2\\\"},\\n            db=AsyncMock(),\\n        )\\n\\n        assert counts[dep_id] == 2\\n        mock_delete_att.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployment_attachments_by_keys\\\", new_callable=AsyncMock)\\n    async def test_extra_known_provider_snapshots_are_ignored(self, mock_delete_att):\\n        dep_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=dep_id),\\n            _mock_attachment(provider_snapshot_id=\\\"snap-2\\\", deployment_id=dep_id),\\n        ]\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_attachment_snapshot_ids\\n\\n        counts = await sync_attachment_snapshot_ids(\\n            user_id=uuid4(),\\n            attachments=attachments,\\n            known_snapshot_ids={\\\"snap-1\\\", \\\"snap-2\\\", \\\"snap-extra\\\"},\\n            db=AsyncMock(),\\n        )\\n\\n        assert counts[dep_id] == 2\\n        mock_delete_att.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# sync_flow_version_attachments\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSyncFlowVersionAttachments:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.get_deployment_adapter\\\")\\n    @patch(\\\"langflow.api.v1.mappers.deployments.registry.get_deployment_mapper\\\")\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_snapshot_cleanup_runs_inside_savepoint(\\n        self,\\n        mock_list_rows,\\n        mock_get_mapper,\\n        mock_get_adapter,\\n        mock_fetch_resource_keys,\\n        mock_delete_unbound,\\n    ):\\n        \\\"\\\"\\\"Binding cleanup is isolated so a failed best-effort sync cannot dirty the outer transaction.\\\"\\\"\\\"\\n        deployment = _mock_deployment_row(\\\"rk-1\\\")\\n        provider_view = _mock_provider_view([_mock_item(item_id=\\\"rk-1\\\")])\\n        mock_list_rows.return_value = [(deployment, \\\"watsonx-orchestrate\\\")]\\n        mapper = MagicMock()\\n        mapper.extract_snapshot_bindings.return_value = []\\n        mock_get_mapper.return_value = mapper\\n        mock_get_adapter.return_value = AsyncMock()\\n        mock_fetch_resource_keys.return_value = ({\\\"rk-1\\\"}, provider_view)\\n        mock_delete_unbound.side_effect = RuntimeError(\\\"delete failed\\\")\\n\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_version_attachments\\n\\n        await sync_flow_version_attachments(\\n            db=db,\\n            flow_id=uuid4(),\\n            user_id=uuid4(),\\n        )\\n\\n        db.begin_nested.assert_called_once()\\n        mock_delete_unbound.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# _sync_deployments_and_attachments_by_provider\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSyncDeploymentsAndAttachmentsByProvider:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployments_by_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.get_deployment_adapter\\\")\\n    @patch(\\\"langflow.api.v1.mappers.deployments.registry.get_deployment_mapper\\\")\\n    async def test_batches_stale_deletions_once_per_provider_group(\\n        self,\\n        mock_get_mapper,\\n        mock_get_adapter,\\n        mock_fetch_resource_keys,\\n        mock_delete_unbound,\\n        mock_delete_deployments,\\n    ):\\n        provider_account_id = uuid4()\\n        stale_a = SimpleNamespace(\\n            id=uuid4(),\\n            resource_key=\\\"rk-stale-a\\\",\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n        stale_b = SimpleNamespace(\\n            id=uuid4(),\\n            resource_key=\\\"rk-stale-b\\\",\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n        surviving = SimpleNamespace(\\n            id=uuid4(),\\n            resource_key=\\\"rk-live\\\",\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n        provider_view = _mock_provider_view([_mock_item(item_id=\\\"rk-live\\\")])\\n        mock_get_adapter.return_value = AsyncMock()\\n        mock_fetch_resource_keys.return_value = ({\\\"rk-live\\\"}, provider_view)\\n        mapper = MagicMock()\\n        mapper.extract_snapshot_bindings.return_value = [\\\"binding-1\\\"]\\n        mock_get_mapper.return_value = mapper\\n\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.sync import _sync_deployments_and_attachments_by_provider\\n\\n        await _sync_deployments_and_attachments_by_provider(\\n            db=db,\\n            user_id=uuid4(),\\n            deployments_with_provider=[\\n                (stale_a, \\\"watsonx-orchestrate\\\"),\\n                (stale_b, \\\"watsonx-orchestrate\\\"),\\n                (surviving, \\\"watsonx-orchestrate\\\"),\\n            ],\\n            stale_scope_label=\\\"flow\\\",\\n            failure_log_message=\\\"ignored\\\",\\n            failure_scope_value=uuid4(),\\n        )\\n\\n        mock_delete_deployments.assert_awaited_once()\\n        assert set(mock_delete_deployments.await_args.kwargs[\\\"deployment_ids\\\"]) == {stale_a.id, stale_b.id}\\n        mock_delete_unbound.assert_awaited_once()\\n        assert mock_delete_unbound.await_args.kwargs[\\\"deployment_ids\\\"] == [surviving.id]\\n        assert mock_delete_unbound.await_args.kwargs[\\\"bindings\\\"] == [\\\"binding-1\\\"]\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.logger.awarning\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.delete_deployments_by_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.get_deployment_adapter\\\")\\n    async def test_logs_unconfirmed_stale_deployment_batch_delete(\\n        self,\\n        mock_get_adapter,\\n        mock_fetch_resource_keys,\\n        mock_delete_deployments,\\n        mock_warning,\\n    ):\\n        \\\"\\\"\\\"An undetermined batch-delete rowcount is surfaced in sync logs.\\\"\\\"\\\"\\n        from langflow.api.v1.mappers.deployments.sync import _sync_deployments_and_attachments_by_provider\\n        from langflow.services.database.models.deployment.crud import UNCONFIRMED_DELETE_ROWCOUNT\\n\\n        provider_account_id = uuid4()\\n        stale = SimpleNamespace(\\n            id=uuid4(),\\n            resource_key=\\\"rk-stale\\\",\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n        mock_get_adapter.return_value = AsyncMock()\\n        mock_fetch_resource_keys.return_value = (set(), _mock_provider_view([]))\\n        mock_delete_deployments.return_value = UNCONFIRMED_DELETE_ROWCOUNT\\n\\n        await _sync_deployments_and_attachments_by_provider(\\n            db=_mock_async_db(),\\n            user_id=uuid4(),\\n            deployments_with_provider=[(stale, \\\"watsonx-orchestrate\\\")],\\n            stale_scope_label=\\\"flow\\\",\\n            failure_log_message=\\\"ignored\\\",\\n            failure_scope_value=uuid4(),\\n        )\\n\\n        mock_delete_deployments.assert_awaited_once()\\n        assert any(\\\"could not be confirmed\\\" in call.args[0] for call in mock_warning.await_args_list)\\n\\n\\n# ---------------------------------------------------------------------------\\n# provider-account scoped sync entry points\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestProviderAccountScopedSync:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_deployment_state_returns_early_when_flow_ids_empty(\\n        self,\\n        mock_list_deployments,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_deployment_state\\n\\n        await sync_flow_deployment_state(\\n            db=AsyncMock(),\\n            flow_ids=[],\\n            user_id=uuid4(),\\n        )\\n\\n        mock_delete_orphans.assert_not_awaited()\\n        mock_list_deployments.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_deployment_state_deduplicates_flow_ids(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_deployment_state\\n\\n        flow_id = uuid4()\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n\\n        await sync_flow_deployment_state(\\n            db=AsyncMock(),\\n            flow_ids=[flow_id, flow_id],\\n            user_id=uuid4(),\\n        )\\n\\n        assert mock_delete_orphans.await_args.kwargs[\\\"flow_ids\\\"] == [flow_id]\\n        assert mock_list_deployments.await_args.kwargs[\\\"flow_ids\\\"] == [flow_id]\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_project\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_project_deployments_with_provider_info\\\", new_callable=AsyncMock, return_value=[])\\n    async def test_sync_project_deployments_returns_when_no_deployments(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_project_deployments\\n\\n        project_id = uuid4()\\n        await sync_project_deployments(\\n            db=AsyncMock(),\\n            project_id=project_id,\\n            user_id=uuid4(),\\n        )\\n\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_list_deployments.assert_awaited_once()\\n        mock_sync_by_provider.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_deployment_state_passes_provider_account_filter(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_deployment_state\\n\\n        provider_account_id = uuid4()\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_flow_deployment_state(\\n            db=AsyncMock(),\\n            flow_ids=[uuid4()],\\n            user_id=uuid4(),\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n\\n        assert mock_list_deployments.call_args.kwargs[\\\"provider_account_id\\\"] == provider_account_id\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_version_attachments_passes_provider_account_filter(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_version_attachments\\n\\n        provider_account_id = uuid4()\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_flow_version_attachments(\\n            db=AsyncMock(),\\n            flow_id=uuid4(),\\n            user_id=uuid4(),\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n\\n        assert mock_list_deployments.call_args.kwargs[\\\"provider_account_id\\\"] == provider_account_id\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_project\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_project_deployments_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_project_deployments_passes_provider_account_filter(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_project_deployments\\n\\n        provider_account_id = uuid4()\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_project_deployments(\\n            db=AsyncMock(),\\n            project_id=uuid4(),\\n            user_id=uuid4(),\\n            deployment_provider_account_id=provider_account_id,\\n        )\\n\\n        assert mock_list_deployments.call_args.kwargs[\\\"provider_account_id\\\"] == provider_account_id\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock, side_effect=Exception(\\\"db\\\"))\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_deployment_state_continues_when_orphan_cleanup_fails(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_deployment_state\\n\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_flow_deployment_state(\\n            db=AsyncMock(),\\n            flow_ids=[uuid4()],\\n            user_id=uuid4(),\\n        )\\n\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_flow_ids\\\", new_callable=AsyncMock, side_effect=Exception(\\\"db\\\"))\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_deployments_for_flows_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_flow_version_attachments_continues_when_orphan_cleanup_fails(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_flow_version_attachments\\n\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_flow_version_attachments(\\n            db=AsyncMock(),\\n            flow_id=uuid4(),\\n            user_id=uuid4(),\\n        )\\n\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{SYNC_MODULE}.delete_orphan_attachments_for_project\\\", new_callable=AsyncMock, side_effect=Exception(\\\"db\\\"))\\n    @patch(f\\\"{SYNC_MODULE}._sync_deployments_and_attachments_by_provider\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{SYNC_MODULE}.list_project_deployments_with_provider_info\\\", new_callable=AsyncMock)\\n    async def test_sync_project_deployments_continues_when_orphan_cleanup_fails(\\n        self,\\n        mock_list_deployments,\\n        mock_sync_by_provider,\\n        mock_delete_orphans,\\n    ):\\n        from langflow.api.v1.mappers.deployments.sync import sync_project_deployments\\n\\n        mock_list_deployments.return_value = [(_mock_deployment_row(\\\"rk-1\\\"), \\\"watsonx-orchestrate\\\")]\\n        await sync_project_deployments(\\n            db=AsyncMock(),\\n            project_id=uuid4(),\\n            user_id=uuid4(),\\n        )\\n\\n        mock_delete_orphans.assert_awaited_once()\\n        mock_sync_by_provider.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# rollback_provider_create\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRollbackProviderCreate:\\n    @pytest.mark.asyncio\\n    async def test_calls_adapter_delete(self):\\n        \\\"\\\"\\\"Compensating delete is called with the provider resource ID.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_create\\n\\n        await rollback_provider_create(\\n            deployment_adapter=adapter,\\n            provider_id=uuid4(),\\n            resource_id=\\\"provider-resource-123\\\",\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.delete.assert_awaited_once()\\n        assert adapter.delete.call_args.kwargs[\\\"deployment_id\\\"] == \\\"provider-resource-123\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_uses_extended_provider_result_rollback_when_available(self):\\n        \\\"\\\"\\\"Adapters can clean up create-time side resources before falling back to delete.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_create\\n\\n        provider_result = {\\\"app_ids\\\": [\\\"app-1\\\"], \\\"tools_with_refs\\\": [{\\\"tool_id\\\": \\\"tool-1\\\", \\\"source_ref\\\": \\\"fv-1\\\"}]}\\n\\n        await rollback_provider_create(\\n            deployment_adapter=adapter,\\n            provider_id=uuid4(),\\n            resource_id=\\\"provider-resource-123\\\",\\n            provider_result=provider_result,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.rollback_create_result.assert_awaited_once()\\n        assert adapter.rollback_create_result.call_args.kwargs[\\\"provider_result\\\"] == provider_result\\n        adapter.delete.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_falls_back_to_delete_when_extended_rollback_fails(self):\\n        \\\"\\\"\\\"If the extended cleanup path fails, the helper still attempts the basic delete.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.rollback_create_result.side_effect = RuntimeError(\\\"rollback boom\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_create\\n\\n        await rollback_provider_create(\\n            deployment_adapter=adapter,\\n            provider_id=uuid4(),\\n            resource_id=\\\"provider-resource-123\\\",\\n            provider_result={\\\"app_ids\\\": [\\\"app-1\\\"]},\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.rollback_create_result.assert_awaited_once()\\n        adapter.delete.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_swallows_delete_failure(self):\\n        \\\"\\\"\\\"If the compensating delete fails, exception is swallowed (logged).\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.delete.side_effect = RuntimeError(\\\"provider unreachable\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_create\\n\\n        # Should not raise\\n        await rollback_provider_create(\\n            deployment_adapter=adapter,\\n            provider_id=uuid4(),\\n            resource_id=\\\"orphaned-resource\\\",\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_skips_delete_fallback_when_disabled_and_extended_rollback_fails(self):\\n        \\\"\\\"\\\"When delete fallback is disabled, extended rollback failures do not trigger delete.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.rollback_create_result.side_effect = RuntimeError(\\\"rollback boom\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_create\\n\\n        await rollback_provider_create(\\n            deployment_adapter=adapter,\\n            provider_id=uuid4(),\\n            resource_id=\\\"existing-resource-1\\\",\\n            provider_result={\\\"app_ids\\\": [\\\"app-1\\\"]},\\n            allow_delete_fallback=False,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.rollback_create_result.assert_awaited_once()\\n        adapter.delete.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# rollback_provider_update\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRollbackProviderUpdate:\\n    @pytest.mark.asyncio\\n    async def test_returns_early_when_mapper_returns_none(self):\\n        \\\"\\\"\\\"When the mapper cannot build a rollback payload, no adapter call is made.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        mapper = AsyncMock(spec=BaseDeploymentMapper)\\n        mapper.resolve_rollback_update = AsyncMock(return_value=None)\\n        dep_row = _mock_deployment_row(\\\"rk-1\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_update\\n\\n        await rollback_provider_update(\\n            deployment_adapter=adapter,\\n            deployment_mapper=mapper,\\n            deployment_db_id=dep_row.id,\\n            deployment_resource_key=dep_row.resource_key,\\n            deployment_provider_account_id=dep_row.deployment_provider_account_id,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.update.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    async def test_calls_adapter_update_with_rollback_payload(self):\\n        \\\"\\\"\\\"When mapper returns a payload, compensating update is issued.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        rollback_payload = MagicMock()\\n        mapper = AsyncMock(spec=BaseDeploymentMapper)\\n        mapper.resolve_rollback_update = AsyncMock(return_value=rollback_payload)\\n        dep_row = _mock_deployment_row(\\\"rk-1\\\")\\n        dep_row.deployment_provider_account_id = uuid4()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_update\\n\\n        await rollback_provider_update(\\n            deployment_adapter=adapter,\\n            deployment_mapper=mapper,\\n            deployment_db_id=dep_row.id,\\n            deployment_resource_key=dep_row.resource_key,\\n            deployment_provider_account_id=dep_row.deployment_provider_account_id,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.update.assert_awaited_once()\\n        assert adapter.update.call_args.kwargs[\\\"payload\\\"] is rollback_payload\\n\\n    @pytest.mark.asyncio\\n    async def test_swallows_adapter_update_failure(self):\\n        \\\"\\\"\\\"If the compensating update fails, exception is swallowed.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        adapter.update.side_effect = RuntimeError(\\\"provider error\\\")\\n        mapper = AsyncMock(spec=BaseDeploymentMapper)\\n        mapper.resolve_rollback_update = AsyncMock(return_value=MagicMock())\\n        dep_row = _mock_deployment_row(\\\"rk-1\\\")\\n        dep_row.deployment_provider_account_id = uuid4()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_update\\n\\n        # Should not raise\\n        await rollback_provider_update(\\n            deployment_adapter=adapter,\\n            deployment_mapper=mapper,\\n            deployment_db_id=dep_row.id,\\n            deployment_resource_key=dep_row.resource_key,\\n            deployment_provider_account_id=dep_row.deployment_provider_account_id,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_swallows_mapper_failure(self):\\n        \\\"\\\"\\\"If mapper.resolve_rollback_update raises, exception is swallowed.\\\"\\\"\\\"\\n        adapter = AsyncMock()\\n        mapper = AsyncMock(spec=BaseDeploymentMapper)\\n        mapper.resolve_rollback_update = AsyncMock(side_effect=RuntimeError(\\\"mapper error\\\"))\\n        dep_row = _mock_deployment_row(\\\"rk-1\\\")\\n\\n        from langflow.api.v1.mappers.deployments.helpers import rollback_provider_update\\n\\n        # Should not raise\\n        await rollback_provider_update(\\n            deployment_adapter=adapter,\\n            deployment_mapper=mapper,\\n            deployment_db_id=dep_row.id,\\n            deployment_resource_key=dep_row.resource_key,\\n            deployment_provider_account_id=dep_row.deployment_provider_account_id,\\n            user_id=uuid4(),\\n            db=AsyncMock(),\\n        )\\n\\n        adapter.update.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# WatsonxOrchestrateDeploymentMapper.resolve_rollback_update\\n# ---------------------------------------------------------------------------\\n\\n\\nDEP_CRUD_MODULE = \\\"langflow.services.database.models.deployment.crud\\\"\\nATT_CRUD_MODULE = \\\"langflow.services.database.models.flow_version_deployment_attachment.crud\\\"\\n\\n\\nclass TestWxoResolveRollbackUpdate:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ATT_CRUD_MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{DEP_CRUD_MODULE}.get_deployment\\\", new_callable=AsyncMock)\\n    async def test_returns_none_when_deployment_not_found(self, mock_get_dep, mock_list_att):\\n        \\\"\\\"\\\"If the deployment row no longer exists, returns None.\\\"\\\"\\\"\\n        mock_get_dep.return_value = None\\n        mapper = WatsonxOrchestrateDeploymentMapper()\\n\\n        result = await mapper.resolve_rollback_update(\\n            user_id=uuid4(),\\n            deployment_db_id=uuid4(),\\n            deployment_resource_key=\\\"rk-1\\\",\\n            db=AsyncMock(),\\n        )\\n\\n        assert result is None\\n        mock_list_att.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ATT_CRUD_MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{DEP_CRUD_MODULE}.get_deployment\\\", new_callable=AsyncMock)\\n    async def test_builds_put_tools_from_attachment_snapshot_ids(self, mock_get_dep, mock_list_att):\\n        \\\"\\\"\\\"Rollback payload contains put_tools with provider_snapshot_ids from DB attachments.\\n\\n        att3/att4 simulate legacy rows that may still have NULL/blank snapshot IDs\\n        in the DB from before the non-empty invariant was enforced at the app level.\\n        \\\"\\\"\\\"\\n        dep = MagicMock()\\n        dep.display_name = \\\"test-dep\\\"\\n        dep.description = \\\"desc\\\"\\n        mock_get_dep.return_value = dep\\n\\n        att1 = MagicMock()\\n        att1.provider_snapshot_id = \\\"tool-1\\\"\\n        att2 = MagicMock()\\n        att2.provider_snapshot_id = \\\"tool-2\\\"\\n        att3 = MagicMock()\\n        att3.provider_snapshot_id = None\\n        att4 = MagicMock()\\n        att4.provider_snapshot_id = \\\"  \\\"\\n        mock_list_att.return_value = [att1, att2, att3, att4]\\n\\n        mapper = WatsonxOrchestrateDeploymentMapper()\\n\\n        result = await mapper.resolve_rollback_update(\\n            user_id=uuid4(),\\n            deployment_db_id=uuid4(),\\n            deployment_resource_key=\\\"rk-1\\\",\\n            db=AsyncMock(),\\n        )\\n\\n        assert result is not None\\n        assert result.spec is not None\\n        assert \\\"name\\\" not in result.spec.model_fields_set\\n        assert result.spec.description == \\\"desc\\\"\\n        provider_data = result.provider_data\\n        assert provider_data[\\\"put_tools\\\"] == [\\\"tool-1\\\", \\\"tool-2\\\"]\\n        assert provider_data[\\\"display_name\\\"] == \\\"test-dep\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{ATT_CRUD_MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{DEP_CRUD_MODULE}.get_deployment\\\", new_callable=AsyncMock)\\n    async def test_empty_attachments_produces_empty_put_tools(self, mock_get_dep, mock_list_att):\\n        \\\"\\\"\\\"When no attachments exist, put_tools is an empty list (clears all tools).\\\"\\\"\\\"\\n        dep = MagicMock()\\n        dep.display_name = \\\"test-dep\\\"\\n        dep.description = \\\"   \\\"\\n        mock_get_dep.return_value = dep\\n        mock_list_att.return_value = []\\n\\n        mapper = WatsonxOrchestrateDeploymentMapper()\\n\\n        result = await mapper.resolve_rollback_update(\\n            user_id=uuid4(),\\n            deployment_db_id=uuid4(),\\n            deployment_resource_key=\\\"rk-1\\\",\\n            db=AsyncMock(),\\n        )\\n\\n        assert result is not None\\n        assert result.provider_data[\\\"put_tools\\\"] == []\\n        assert result.provider_data[\\\"display_name\\\"] == \\\"test-dep\\\"\\n        assert result.spec is not None\\n        assert result.spec.description is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployments_synced: phase-2 binding sync\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentsSyncedBindingPhase:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_binding_sync_corrects_attached_count(\\n        self,\\n        mock_list,\\n        mock_fetch_rk,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Phase 2 corrects attached_count using binding-level cleanup + recount.\\\"\\\"\\\"\\n        row = _mock_deployment_row(\\\"rk-1\\\")\\n        mock_list.side_effect = [[(row, 3, [])], []]\\n        mock_fetch_rk.return_value = (\\n            {\\\"rk-1\\\"},\\n            _mock_provider_view(\\n                [\\n                    SimpleNamespace(\\n                        id=\\\"rk-1\\\",\\n                        name=\\\"agent_api_name\\\",\\n                        provider_data={\\n                            \\\"display_name\\\": \\\"Agent One\\\",\\n                            \\\"description\\\": \\\"Provider description\\\",\\n                            \\\"tool_ids\\\": [\\\"snap-1\\\"],\\n                            \\\"llm\\\": \\\"meta-llm\\\",\\n                            \\\"environments\\\": [],\\n                        },\\n                    )\\n                ]\\n            ),\\n        )\\n        mock_count_attachments.return_value = {row.id: 2}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=WatsonxOrchestrateDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 1\\n        assert accepted[0][1] == 2\\n        assert provider_data_by_resource_key == {\\n            \\\"rk-1\\\": {\\n                \\\"name\\\": \\\"agent_api_name\\\",\\n                \\\"display_name\\\": \\\"Agent One\\\",\\n                \\\"environments\\\": [],\\n                \\\"llm\\\": \\\"meta-llm\\\",\\n            }\\n        }\\n        db.begin_nested.assert_called_once()\\n        mock_delete_unbound.assert_awaited_once()\\n        mock_count_attachments.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_binding_cleanup_runs_with_empty_bindings(\\n        self,\\n        mock_list,\\n        mock_fetch_rk,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Phase 2 still runs when mapper extracts no bindings.\\\"\\\"\\\"\\n        row = _mock_deployment_row(\\\"rk-1\\\")\\n        mock_list.side_effect = [[(row, 0, [])], []]\\n        mock_fetch_rk.return_value = (\\n            {\\\"rk-1\\\"},\\n            _mock_provider_view(\\n                [SimpleNamespace(id=\\\"rk-1\\\", name=\\\"Agent 1\\\", provider_data=_wxo_deployment_provider_data(tool_ids=[]))]\\n            ),\\n        )\\n        mock_count_attachments.return_value = {row.id: 0}\\n        db = _mock_async_db()\\n        provider_id = uuid4()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=WatsonxOrchestrateDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=provider_id,\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 1\\n        mock_delete_unbound.assert_awaited_once()\\n        assert mock_delete_unbound.await_args.kwargs[\\\"bindings\\\"] == []\\n        assert mock_delete_unbound.await_args.kwargs[\\\"provider_account_id\\\"] == provider_id\\n        mock_count_attachments.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_binding_sync_error_preserves_original_counts(\\n        self,\\n        mock_list,\\n        mock_fetch_rk,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"When Phase 2 raises, accepted rows keep their original attached_count.\\\"\\\"\\\"\\n        row = _mock_deployment_row(\\\"rk-1\\\")\\n        mock_list.side_effect = [[(row, 3, [])], []]\\n        mock_fetch_rk.return_value = (\\n            {\\\"rk-1\\\"},\\n            _mock_provider_view(\\n                [\\n                    SimpleNamespace(\\n                        id=\\\"rk-1\\\",\\n                        name=\\\"Agent 1\\\",\\n                        provider_data=_wxo_deployment_provider_data(tool_ids=[\\\"snap-1\\\"]),\\n                    )\\n                ]\\n            ),\\n        )\\n        mock_delete_unbound.side_effect = RuntimeError(\\\"cleanup failed\\\")\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=WatsonxOrchestrateDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 1\\n        assert accepted[0][1] == 3\\n        mock_count_attachments.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployments_by_provider\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.count_attachments_by_deployment_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.delete_unbound_attachments\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.fetch_provider_resource_keys\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployments_page\\\", new_callable=AsyncMock)\\n    async def test_binding_cleanup_runs_inside_savepoint(\\n        self,\\n        mock_list,\\n        mock_fetch_rk,\\n        mock_delete_unbound,\\n        mock_count_attachments,\\n        mock_count,  # noqa: ARG002\\n    ):\\n        \\\"\\\"\\\"Phase 2 cleanup uses a savepoint so failures don't leak partial writes.\\\"\\\"\\\"\\n        row = _mock_deployment_row(\\\"rk-1\\\")\\n        mock_list.side_effect = [[(row, 3, [])], []]\\n        mock_fetch_rk.return_value = (\\n            {\\\"rk-1\\\"},\\n            _mock_provider_view(\\n                [\\n                    SimpleNamespace(\\n                        id=\\\"rk-1\\\",\\n                        name=\\\"Agent 1\\\",\\n                        provider_data=_wxo_deployment_provider_data(tool_ids=[\\\"snap-1\\\"]),\\n                    )\\n                ]\\n            ),\\n        )\\n        mock_count_attachments.return_value = {row.id: 3}\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployments_synced\\n\\n        accepted, _, _ = await list_deployments_synced(\\n            deployment_adapter=AsyncMock(),\\n            deployment_mapper=WatsonxOrchestrateDeploymentMapper(),\\n            user_id=(_uid := uuid4()),\\n            row_owner_id=_uid,\\n            provider_id=uuid4(),\\n            db=db,\\n            page=1,\\n            size=10,\\n            deployment_type=None,\\n        )\\n\\n        assert len(accepted) == 1\\n        assert accepted[0][1] == 3\\n        db.begin_nested.assert_called_once()\\n        mock_delete_unbound.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_deployment_flow_versions_synced\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListDeploymentFlowVersionsSynced:\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=2)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.sync_attachment_snapshot_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    async def test_syncs_snapshots_with_snapshot_ids_and_returns_enrichment(\\n        self,\\n        mock_list_attachments,\\n        mock_sync_snapshot_ids,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=deployment_id),\\n            _mock_attachment(provider_snapshot_id=\\\"snap-stale\\\", deployment_id=deployment_id),\\n        ]\\n        mock_list_attachments.return_value = attachments\\n        rows = [(SimpleNamespace(provider_snapshot_id=\\\"snap-1\\\"), SimpleNamespace())]\\n        mock_list_with_versions.return_value = rows\\n\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = SnapshotListResult(\\n            snapshots=[\\n                SnapshotItem(\\n                    id=\\\"snap-1\\\",\\n                    name=\\\"tool-1\\\",\\n                    provider_data={\\\"connections\\\": {\\\"cfg-1\\\": \\\"conn-1\\\"}},\\n                )\\n            ]\\n        )\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        out_rows, total, snapshot_result = await list_deployment_flow_versions_synced(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            deployment_id=deployment_id,\\n            db=db,\\n            page=2,\\n            size=3,\\n        )\\n\\n        assert out_rows == rows\\n        assert total == 2\\n        assert isinstance(snapshot_result, SnapshotListResult)\\n        assert [snapshot.id for snapshot in snapshot_result.snapshots] == [\\\"snap-1\\\"]\\n        adapter.list_snapshots.assert_awaited_once()\\n        adapter_params = adapter.list_snapshots.call_args.kwargs[\\\"params\\\"]\\n        assert adapter_params.snapshot_ids == [\\\"snap-1\\\", \\\"snap-stale\\\"]\\n        mock_sync_snapshot_ids.assert_awaited_once()\\n        assert mock_sync_snapshot_ids.call_args.kwargs[\\\"known_snapshot_ids\\\"] == {\\\"snap-1\\\"}\\n        assert mock_list_with_versions.call_args.kwargs[\\\"offset\\\"] == 3\\n        assert mock_list_with_versions.call_args.kwargs[\\\"limit\\\"] == 3\\n        mock_count_attachments.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.sync_attachment_snapshot_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    async def test_fails_fast_when_attachment_snapshot_ids_are_falsy(\\n        self,\\n        mock_list_attachments,\\n        mock_sync_snapshot_ids,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        attachments = [\\n            _mock_attachment(provider_snapshot_id=None, deployment_id=deployment_id),\\n            _mock_attachment(provider_snapshot_id=\\\"\\\", deployment_id=deployment_id),\\n        ]\\n        mock_list_attachments.return_value = attachments\\n\\n        adapter = AsyncMock()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must be non-empty\\\"):\\n            await list_deployment_flow_versions_synced(\\n                deployment_adapter=adapter,\\n                user_id=uuid4(),\\n                provider_id=uuid4(),\\n                deployment_id=deployment_id,\\n                db=AsyncMock(),\\n                page=1,\\n                size=10,\\n            )\\n        adapter.list_snapshots.assert_not_awaited()\\n        mock_sync_snapshot_ids.assert_not_awaited()\\n        mock_count_attachments.assert_not_awaited()\\n        mock_list_with_versions.assert_not_awaited()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.sync_attachment_snapshot_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    async def test_snapshot_sync_savepoint_failure_clears_enrichment_payload(\\n        self,\\n        mock_list_attachments,\\n        mock_sync_snapshot_ids,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        mock_list_attachments.return_value = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=deployment_id)\\n        ]\\n        rows = [(SimpleNamespace(provider_snapshot_id=\\\"snap-1\\\"), SimpleNamespace())]\\n        mock_list_with_versions.return_value = rows\\n\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = SnapshotListResult(\\n            snapshots=[\\n                SnapshotItem(\\n                    id=\\\"snap-1\\\",\\n                    name=\\\"tool-1\\\",\\n                    provider_data={\\\"connections\\\": {\\\"cfg-1\\\": \\\"conn-1\\\"}},\\n                )\\n            ]\\n        )\\n        mock_sync_snapshot_ids.side_effect = RuntimeError(\\\"savepoint failed\\\")\\n        db = _mock_async_db()\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        out_rows, total, snapshot_result = await list_deployment_flow_versions_synced(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            deployment_id=deployment_id,\\n            db=db,\\n            page=1,\\n            size=20,\\n        )\\n\\n        assert out_rows == rows\\n        assert total == 1\\n        assert snapshot_result is None\\n        adapter.list_snapshots.assert_awaited_once()\\n        mock_sync_snapshot_ids.assert_awaited_once()\\n        mock_count_attachments.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.sync_attachment_snapshot_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    async def test_snapshot_sync_errors_fall_back_to_db_rows_without_enrichment(\\n        self,\\n        mock_list_attachments,\\n        mock_sync_snapshot_ids,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        mock_list_attachments.return_value = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=deployment_id)\\n        ]\\n        rows = [(SimpleNamespace(provider_snapshot_id=\\\"snap-1\\\"), SimpleNamespace())]\\n        mock_list_with_versions.return_value = rows\\n\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.side_effect = RuntimeError(\\\"provider down\\\")\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        out_rows, total, snapshot_result = await list_deployment_flow_versions_synced(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            deployment_id=deployment_id,\\n            db=AsyncMock(),\\n            page=1,\\n            size=20,\\n        )\\n\\n        assert out_rows == rows\\n        assert total == 1\\n        assert snapshot_result is None\\n        mock_sync_snapshot_ids.assert_not_awaited()\\n        mock_count_attachments.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=0)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock, return_value=[])\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock, return_value=[])\\n    async def test_forwards_flow_ids_filter_to_attachment_queries(\\n        self,\\n        mock_list_attachments,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        flow_id = uuid4()\\n        adapter = AsyncMock()\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        await list_deployment_flow_versions_synced(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            deployment_id=deployment_id,\\n            db=AsyncMock(),\\n            page=1,\\n            size=10,\\n            flow_ids=[flow_id],\\n        )\\n\\n        assert mock_list_attachments.call_args.kwargs[\\\"flow_ids\\\"] == [flow_id]\\n        assert mock_list_with_versions.call_args.kwargs[\\\"flow_ids\\\"] == [flow_id]\\n        assert mock_count_attachments.call_args.kwargs[\\\"flow_ids\\\"] == [flow_id]\\n\\n    @pytest.mark.asyncio\\n    @patch(f\\\"{MODULE}.count_deployment_attachments\\\", new_callable=AsyncMock, return_value=1)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments_with_versions\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.sync_attachment_snapshot_ids\\\", new_callable=AsyncMock)\\n    @patch(f\\\"{MODULE}.list_deployment_attachments\\\", new_callable=AsyncMock)\\n    async def test_provider_snapshot_result_with_falsy_id_falls_back_without_enrichment(\\n        self,\\n        mock_list_attachments,\\n        mock_sync_snapshot_ids,\\n        mock_list_with_versions,\\n        mock_count_attachments,\\n    ):\\n        deployment_id = uuid4()\\n        mock_list_attachments.return_value = [\\n            _mock_attachment(provider_snapshot_id=\\\"snap-1\\\", deployment_id=deployment_id)\\n        ]\\n        rows = [(SimpleNamespace(provider_snapshot_id=\\\"snap-1\\\"), SimpleNamespace())]\\n        mock_list_with_versions.return_value = rows\\n        adapter = AsyncMock()\\n        adapter.list_snapshots.return_value = _mock_snapshot_view([_mock_snapshot_item(item_id=\\\"\\\")])\\n\\n        from langflow.api.v1.mappers.deployments.helpers import list_deployment_flow_versions_synced\\n\\n        out_rows, total, snapshot_result = await list_deployment_flow_versions_synced(\\n            deployment_adapter=adapter,\\n            user_id=uuid4(),\\n            provider_id=uuid4(),\\n            deployment_id=deployment_id,\\n            db=AsyncMock(),\\n            page=1,\\n            size=20,\\n        )\\n\\n        assert out_rows == rows\\n        assert total == 1\\n        assert snapshot_result is None\\n        adapter.list_snapshots.assert_awaited_once()\\n        mock_sync_snapshot_ids.assert_not_awaited()\\n        mock_list_with_versions.assert_awaited_once()\\n        mock_count_attachments.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# flow_version_deployment_attachment CRUD helpers\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _FakeAllResult:\\n    def __init__(self, rows):\\n        self._rows = rows\\n\\n    def all(self):\\n        return self._rows\\n\\n\\nclass _FakeOneResult:\\n    def __init__(self, value):\\n        self._value = value\\n\\n    def one(self):\\n        return self._value\\n\\n\\nclass _CaptureDb:\\n    def __init__(self, result):\\n        self._result = result\\n        self.statements = []\\n\\n    async def exec(self, statement):\\n        self.statements.append(statement)\\n        return self._result\\n\\n\\nclass TestFlowVersionDeploymentAttachmentCrud:\\n    @pytest.mark.asyncio\\n    async def test_list_deployment_attachments_with_versions_orders_by_attachment_timestamps(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            list_deployment_attachments_with_versions,\\n        )\\n\\n        rows = [(SimpleNamespace(), SimpleNamespace())]\\n        db = _CaptureDb(_FakeAllResult(rows))\\n\\n        result = await list_deployment_attachments_with_versions(\\n            db,\\n            user_id=uuid4(),\\n            deployment_id=uuid4(),\\n            offset=5,\\n            limit=10,\\n        )\\n\\n        assert result == rows\\n        statement_text = str(db.statements[0]).lower()\\n        assert \\\"order by\\\" in statement_text\\n        assert \\\"created_at desc\\\" in statement_text\\n        assert \\\"updated_at desc\\\" in statement_text\\n\\n    @pytest.mark.asyncio\\n    async def test_list_deployment_attachments_with_versions_skips_query_when_limit_non_positive(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            list_deployment_attachments_with_versions,\\n        )\\n\\n        db = _CaptureDb(_FakeAllResult([]))\\n        result = await list_deployment_attachments_with_versions(\\n            db,\\n            user_id=uuid4(),\\n            deployment_id=uuid4(),\\n            offset=0,\\n            limit=0,\\n        )\\n\\n        assert result == []\\n        assert db.statements == []\\n\\n    @pytest.mark.asyncio\\n    async def test_count_deployment_attachments_returns_scalar_count(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            count_deployment_attachments,\\n        )\\n\\n        db = _CaptureDb(_FakeOneResult(4))\\n\\n        total = await count_deployment_attachments(\\n            db,\\n            user_id=uuid4(),\\n            deployment_id=uuid4(),\\n        )\\n\\n        assert total == 4\\n        assert len(db.statements) == 1\\n        # String-match on compiled SQL because these tests use captured\\n        # statement objects without a real database engine.\\n        statement_text = str(db.statements[0]).lower()\\n        assert \\\"join flow_version\\\" in statement_text\\n\\n    @pytest.mark.asyncio\\n    async def test_count_attachments_by_deployment_ids_joins_flow_version(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            count_attachments_by_deployment_ids,\\n        )\\n\\n        deployment_id = uuid4()\\n        db = _CaptureDb(_FakeAllResult([]))\\n        counts = await count_attachments_by_deployment_ids(\\n            db,\\n            user_id=uuid4(),\\n            deployment_ids=[deployment_id],\\n        )\\n\\n        assert counts == {deployment_id: 0}\\n        assert len(db.statements) == 1\\n        statement_text = str(db.statements[0]).lower()\\n        assert \\\"join flow_version\\\" in statement_text\\n\\n    @pytest.mark.asyncio\\n    async def test_delete_orphan_attachments_for_flow_ids_joins_flow_version_and_deployment(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            delete_orphan_attachments_for_flow_ids,\\n        )\\n\\n        db = _CaptureDb(SimpleNamespace(rowcount=2))\\n        deleted = await delete_orphan_attachments_for_flow_ids(\\n            db,\\n            user_id=uuid4(),\\n            flow_ids=[uuid4()],\\n        )\\n\\n        assert deleted == 2\\n        statement_text = str(db.statements[0]).lower()\\n        assert \\\"delete from flow_version_deployment_attachment\\\" in statement_text\\n        assert \\\"join flow_version\\\" in statement_text\\n        assert \\\"join deployment\\\" in statement_text\\n\\n    @pytest.mark.asyncio\\n    async def test_delete_orphan_attachments_for_project_joins_flow_scope_and_deployment(self):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            delete_orphan_attachments_for_project,\\n        )\\n\\n        db = _CaptureDb(SimpleNamespace(rowcount=1))\\n        deleted = await delete_orphan_attachments_for_project(\\n            db,\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n        )\\n\\n        assert deleted == 1\\n        statement_text = str(db.statements[0]).lower()\\n        assert \\\"delete from flow_version_deployment_attachment\\\" in statement_text\\n        assert \\\"join flow_version\\\" in statement_text\\n        assert \\\"join flow\\\" in statement_text\\n        assert \\\"join deployment\\\" in statement_text\\n\\n\\n# ---------------------------------------------------------------------------\\n# flow_ids_for_version_ids\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def _seed_flow_versions(\\n    async_session: AsyncSession, *, version_count: int\\n) -> tuple[User, Flow, list[FlowVersion]]:\\n    \\\"\\\"\\\"Persist one owner, one flow, and ``version_count`` versions.\\\"\\\"\\\"\\n    owner = User(username=f\\\"owner-{uuid4()}\\\", password=f\\\"hashed-{uuid4()}\\\", is_active=True)\\n    flow = Flow(name=f\\\"flow-{uuid4()}\\\", user_id=owner.id)\\n    versions = [\\n        FlowVersion(\\n            flow_id=flow.id,\\n            user_id=owner.id,\\n            version_number=index + 1,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        for index in range(version_count)\\n    ]\\n    async_session.add_all([owner, flow, *versions])\\n    await async_session.commit()\\n    return owner, flow, versions\\n\\n\\nclass TestFlowIdsForVersionIds:\\n    @pytest.mark.asyncio\\n    async def test_empty_input_returns_empty(self, async_session: AsyncSession):\\n        \\\"\\\"\\\"Empty input skips the query even with a real session.\\\"\\\"\\\"\\n        from langflow.api.v1.mappers.deployments.helpers import flow_ids_for_version_ids\\n\\n        assert (\\n            await flow_ids_for_version_ids(\\n                flow_version_ids=[],\\n                owner_id=uuid4(),\\n                db=async_session,\\n            )\\n            == []\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_partial_match_raises_404(self, async_session: AsyncSession):\\n        \\\"\\\"\\\"Missing versions must fail on matched count, not on an empty distinct set.\\\"\\\"\\\"\\n        from langflow.api.v1.mappers.deployments.helpers import flow_ids_for_version_ids\\n\\n        owner, _flow, versions = await _seed_flow_versions(async_session, version_count=1)\\n\\n        with pytest.raises(HTTPException) as exc_info:\\n            await flow_ids_for_version_ids(\\n                flow_version_ids=[versions[0].id, uuid4()],\\n                owner_id=owner.id,\\n                db=async_session,\\n            )\\n\\n        assert exc_info.value.status_code == 404\\n\\n    @pytest.mark.asyncio\\n    async def test_shared_flow_dedupes_returned_ids(self, async_session: AsyncSession):\\n        \\\"\\\"\\\"Two persisted versions of one flow resolve to one authorization target.\\\"\\\"\\\"\\n        from langflow.api.v1.mappers.deployments.helpers import flow_ids_for_version_ids\\n\\n        owner, flow, versions = await _seed_flow_versions(async_session, version_count=2)\\n\\n        flow_ids = await flow_ids_for_version_ids(\\n            flow_version_ids=[version.id for version in versions],\\n            owner_id=owner.id,\\n            db=async_session,\\n        )\\n\\n        assert flow_ids == [flow.id]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployments_response_mapping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a81624e2436393991be5f6ca7caae5c4e3c3831b93be633f6b99d703bde9ca0f\",\"content\":\"from datetime import datetime, timezone\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nfrom langflow.api.v1.mappers.deployments.base import BaseDeploymentMapper\\nfrom lfx.services.adapters.deployment.schema import (\\n    DeploymentCreateResult,\\n    DeploymentListResult,\\n    DeploymentType,\\n    DeploymentUpdateResult,\\n    ExecutionCreateResult,\\n    ItemResult,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_deployment_row(**overrides):\\n    defaults = {\\n        \\\"id\\\": uuid4(),\\n        \\\"deployment_provider_account_id\\\": uuid4(),\\n        \\\"display_name\\\": \\\"db-deployment-name\\\",\\n        \\\"description\\\": \\\"db-description\\\",\\n        \\\"deployment_type\\\": DeploymentType.AGENT,\\n        \\\"resource_key\\\": \\\"provider-deployment-id\\\",\\n        \\\"created_at\\\": datetime.now(timezone.utc),\\n        \\\"updated_at\\\": datetime.now(timezone.utc),\\n    }\\n    defaults.update(overrides)\\n    return SimpleNamespace(**defaults)\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_deployment_create_result\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_deployment_create_result_maps_db_identity_and_provider_result() -> None:\\n    mapper = BaseDeploymentMapper()\\n    provider_account_id = uuid4()\\n    now = datetime.now(timezone.utc)\\n    deployment_row = SimpleNamespace(\\n        id=uuid4(),\\n        deployment_provider_account_id=provider_account_id,\\n        display_name=\\\"db-deployment-name\\\",\\n        description=\\\"db-description\\\",\\n        deployment_type=DeploymentType.AGENT,\\n        resource_key=\\\"provider-deployment-id\\\",\\n        created_at=now,\\n        updated_at=now,\\n    )\\n    adapter_result = DeploymentCreateResult(\\n        id=\\\"provider-deployment-id\\\",\\n        type=DeploymentType.AGENT,\\n        provider_result={\\\"snapshot_bindings\\\": [{\\\"source_ref\\\": \\\"fv-1\\\", \\\"snapshot_id\\\": \\\"tool-1\\\"}]},\\n    )\\n\\n    response = mapper.shape_deployment_create_result(adapter_result, deployment_row, provider_key=\\\"test-provider\\\")\\n\\n    assert response.id == deployment_row.id\\n    assert response.provider_id == provider_account_id\\n    assert response.provider_key == \\\"test-provider\\\"\\n    assert response.description == \\\"db-description\\\"\\n    assert response.created_at == now\\n    assert response.updated_at == now\\n    assert response.type == DeploymentType.AGENT\\n    assert response.provider_data == {\\\"snapshot_bindings\\\": [{\\\"source_ref\\\": \\\"fv-1\\\", \\\"snapshot_id\\\": \\\"tool-1\\\"}]}\\n\\n\\ndef test_shape_deployment_create_result_with_none_provider_result() -> None:\\n    mapper = BaseDeploymentMapper()\\n    row = _make_deployment_row()\\n    result = DeploymentCreateResult(id=\\\"dep-1\\\", type=DeploymentType.AGENT, provider_result=None)\\n\\n    response = mapper.shape_deployment_create_result(result, row, provider_key=\\\"test-provider\\\")\\n\\n    assert response.provider_data is None\\n\\n\\ndef test_shape_deployment_create_result_with_empty_dict_provider_result() -> None:\\n    \\\"\\\"\\\"Empty dict provider_result is passed through as-is.\\\"\\\"\\\"\\n    mapper = BaseDeploymentMapper()\\n    row = _make_deployment_row()\\n    result = DeploymentCreateResult(id=\\\"dep-1\\\", type=DeploymentType.AGENT, provider_result={})\\n\\n    response = mapper.shape_deployment_create_result(result, row, provider_key=\\\"test-provider\\\")\\n\\n    assert response.provider_data == {}\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_deployment_update_result\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_deployment_update_result_maps_db_identity_and_provider_result() -> None:\\n    mapper = BaseDeploymentMapper()\\n    provider_account_id = uuid4()\\n    now = datetime.now(timezone.utc)\\n    row = _make_deployment_row(\\n        deployment_provider_account_id=provider_account_id,\\n        created_at=now,\\n        updated_at=now,\\n    )\\n    result = DeploymentUpdateResult(\\n        id=\\\"provider-dep-id\\\",\\n        provider_result={\\\"status\\\": \\\"updated\\\", \\\"version\\\": 2},\\n    )\\n\\n    response = mapper.shape_deployment_update_result(result, row, provider_key=\\\"my-provider\\\")\\n\\n    assert response.id == row.id\\n    assert response.provider_id == provider_account_id\\n    assert response.provider_key == \\\"my-provider\\\"\\n    assert response.description == row.description\\n    assert response.type == DeploymentType.AGENT\\n    assert response.created_at == now\\n    assert response.updated_at == now\\n    assert response.resource_key == row.resource_key\\n    assert response.provider_data == {\\\"status\\\": \\\"updated\\\", \\\"version\\\": 2}\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_deployment_list_result\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_deployment_list_result_with_entries() -> None:\\n    mapper = BaseDeploymentMapper()\\n    now = datetime.now(timezone.utc)\\n    items = [\\n        ItemResult(\\n            id=\\\"dep-1\\\",\\n            name=\\\"Deployment One\\\",\\n            type=DeploymentType.AGENT,\\n            provider_data={\\\"region\\\": \\\"us-east\\\"},\\n            created_at=now,\\n            updated_at=now,\\n        ),\\n        ItemResult(\\n            id=\\\"dep-2\\\",\\n            name=\\\"Deployment Two\\\",\\n            type=DeploymentType.AGENT,\\n            provider_data=None,\\n            created_at=now,\\n            updated_at=now,\\n        ),\\n    ]\\n    result = DeploymentListResult(deployments=items)\\n\\n    response = mapper.shape_deployment_list_result(result)\\n\\n    assert response.deployments == []\\n    assert response.provider_data is not None\\n    entries = response.provider_data[\\\"entries\\\"]\\n    assert len(entries) == 2\\n    assert entries[0][\\\"id\\\"] == \\\"dep-1\\\"\\n    assert entries[0][\\\"name\\\"] == \\\"Deployment One\\\"\\n    assert entries[0][\\\"region\\\"] == \\\"us-east\\\"\\n    assert entries[1][\\\"id\\\"] == \\\"dep-2\\\"\\n    assert response.page == 1\\n    assert response.size == 2\\n    assert response.total == 2\\n\\n\\ndef test_shape_deployment_list_result_null_provider_data_on_item() -> None:\\n    \\\"\\\"\\\"Items with None provider_data produce an empty dict for spread.\\\"\\\"\\\"\\n    mapper = BaseDeploymentMapper()\\n    items = [\\n        ItemResult(id=\\\"dep-1\\\", name=\\\"No PD\\\", type=DeploymentType.AGENT, provider_data=None),\\n    ]\\n    result = DeploymentListResult(deployments=items)\\n\\n    response = mapper.shape_deployment_list_result(result)\\n\\n    entries = response.provider_data[\\\"entries\\\"]\\n    assert len(entries) == 1\\n    assert entries[0][\\\"id\\\"] == \\\"dep-1\\\"\\n    assert entries[0][\\\"name\\\"] == \\\"No PD\\\"\\n\\n\\ndef test_shape_deployment_list_result_with_extra_provider_data_fields() -> None:\\n    \\\"\\\"\\\"Items with dict provider_data spread extra keys into the entry.\\\"\\\"\\\"\\n    mapper = BaseDeploymentMapper()\\n    items = [\\n        ItemResult(\\n            id=\\\"dep-1\\\",\\n            name=\\\"With PD\\\",\\n            type=DeploymentType.AGENT,\\n            provider_data={\\\"region\\\": \\\"us-east\\\", \\\"version\\\": 3},\\n        ),\\n    ]\\n    result = DeploymentListResult(deployments=items)\\n\\n    response = mapper.shape_deployment_list_result(result)\\n\\n    entries = response.provider_data[\\\"entries\\\"]\\n    assert len(entries) == 1\\n    assert entries[0][\\\"region\\\"] == \\\"us-east\\\"\\n    assert entries[0][\\\"version\\\"] == 3\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_execution_create_result\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_execution_create_result_with_provider_data() -> None:\\n    mapper = BaseDeploymentMapper()\\n    dep_id = uuid4()\\n    result = ExecutionCreateResult(\\n        deployment_id=\\\"provider-dep-id\\\",\\n        provider_result={\\\"execution_id\\\": \\\"exec-1\\\", \\\"status\\\": \\\"running\\\"},\\n    )\\n\\n    response = mapper.shape_execution_create_result(result, deployment_id=dep_id)\\n\\n    assert response.deployment_id == dep_id\\n    assert response.provider_data == {\\\"execution_id\\\": \\\"exec-1\\\", \\\"status\\\": \\\"running\\\"}\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_deployment_list_items (DB-backed list)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_deployment_list_items_basic() -> None:\\n    mapper = BaseDeploymentMapper()\\n    now = datetime.now(timezone.utc)\\n    dep_id = uuid4()\\n    prov_id = uuid4()\\n    row = SimpleNamespace(\\n        id=dep_id,\\n        deployment_provider_account_id=prov_id,\\n        deployment_type=DeploymentType.AGENT,\\n        display_name=\\\"My Dep\\\",\\n        description=\\\"desc\\\",\\n        resource_key=\\\"rk-1\\\",\\n        created_at=now,\\n        updated_at=now,\\n    )\\n\\n    items = mapper.shape_deployment_list_items(\\n        rows_with_counts=[(row, 3, [])],\\n        has_flow_filter=False,\\n        provider_key=\\\"test-provider\\\",\\n    )\\n\\n    assert len(items) == 1\\n    item = items[0]\\n    assert item.id == dep_id\\n    assert item.provider_id == prov_id\\n    assert item.provider_key == \\\"test-provider\\\"\\n    assert item.attached_count == 3\\n    assert item.flow_version_ids is None\\n    assert item.provider_data is None\\n\\n\\ndef test_shape_deployment_list_items_with_flow_filter() -> None:\\n    mapper = BaseDeploymentMapper()\\n    row = _make_deployment_row()\\n    fv_id = uuid4()\\n\\n    items = mapper.shape_deployment_list_items(\\n        rows_with_counts=[(row, 1, [(fv_id, \\\"tool-1\\\")])],\\n        has_flow_filter=True,\\n        provider_key=\\\"test-provider\\\",\\n    )\\n\\n    assert items[0].flow_version_ids == [fv_id]\\n    assert items[0].provider_data is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# shape_config_list_result pagination\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_shape_config_list_result_pagination() -> None:\\n    from lfx.services.adapters.deployment.schema import ConfigListItem, ConfigListResult\\n\\n    mapper = BaseDeploymentMapper()\\n    configs = [ConfigListItem(id=f\\\"cfg-{i}\\\", name=f\\\"Config {i}\\\") for i in range(5)]\\n    result = ConfigListResult(configs=configs, provider_result={\\\"extra\\\": \\\"meta\\\"})\\n\\n    response = mapper.shape_config_list_result(result, page=2, size=2)\\n\\n    assert response.page == 2\\n    assert response.size == 2\\n    assert response.total == 5\\n    assert response.provider_data is not None\\n    # page 2 with size 2 means offset 2, so items at index 2 and 3\\n    assert len(response.provider_data[\\\"configs\\\"]) == 2\\n    assert response.provider_data[\\\"configs\\\"][0][\\\"id\\\"] == \\\"cfg-2\\\"\\n    assert response.provider_data[\\\"configs\\\"][1][\\\"id\\\"] == \\\"cfg-3\\\"\\n    assert response.provider_data[\\\"extra\\\"] == \\\"meta\\\"\\n\\n\\ndef test_shape_config_list_result_empty() -> None:\\n    from lfx.services.adapters.deployment.schema import ConfigListResult\\n\\n    mapper = BaseDeploymentMapper()\\n    result = ConfigListResult(configs=[], provider_result=None)\\n\\n    response = mapper.shape_config_list_result(result, page=1, size=10)\\n\\n    assert response.total == 0\\n    assert response.provider_data == {\\\"configs\\\": []}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployments_routes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"adb3167f7950b65a7aa20794ee8af6d2c1c0cc03acf4de48065da99c38ac108d\",\"content\":\"\\\"\\\"\\\"Route matching tests for deployment endpoints.\\n\\nThese tests guard against route-order regressions where static routes could be\\ncaptured by the dynamic `/{deployment_id}` route.\\n\\\"\\\"\\\"\\n\\nfrom collections.abc import Iterator\\nfrom uuid import uuid4\\n\\nimport langflow.api.router as api_router_module\\nimport pytest\\nfrom fastapi import APIRouter\\nfrom fastapi.routing import APIRoute\\nfrom langflow.api.v1.deployments import router\\nfrom starlette.routing import Match\\n\\n\\ndef _flatten_api_routes(router: APIRouter) -> Iterator[APIRoute]:\\n    \\\"\\\"\\\"Yield every ``APIRoute`` reachable from ``router``.\\n\\n    FastAPI >=0.137 includes sub-routers lazily: ``include_router`` stores an\\n    internal ``_IncludedRouter`` wrapper instead of eagerly copying the child\\n    ``APIRoute`` objects into ``router.routes``. Descend through that wrapper via\\n    its public ``original_router`` reference so these tests work on both the\\n    eager (<=0.136) and lazy (>=0.137) inclusion behaviours.\\n    \\\"\\\"\\\"\\n    for route in router.routes:\\n        if isinstance(route, APIRoute):\\n            yield route\\n        else:\\n            original = getattr(route, \\\"original_router\\\", None)\\n            if original is not None:\\n                yield from _flatten_api_routes(original)\\n\\n\\n@pytest.fixture\\ndef deployment_routes() -> list[APIRoute]:\\n    return list(_flatten_api_routes(router))\\n\\n\\ndef _resolve_endpoint_name(routes: list[APIRoute], *, path: str, method: str = \\\"GET\\\") -> str:\\n    scope = {\\\"type\\\": \\\"http\\\", \\\"path\\\": path, \\\"method\\\": method}\\n    for route in routes:\\n        match, _ = route.matches(scope)\\n        if match == Match.FULL:\\n            return route.endpoint.__name__\\n    msg = f\\\"No matching route for {method} {path}\\\"\\n    raise AssertionError(msg)\\n\\n\\ndef _resolve_route(routes: list[APIRoute], *, path: str, method: str = \\\"GET\\\") -> APIRoute:\\n    scope = {\\\"type\\\": \\\"http\\\", \\\"path\\\": path, \\\"method\\\": method}\\n    for route in routes:\\n        match, _ = route.matches(scope)\\n        if match == Match.FULL:\\n            return route\\n    msg = f\\\"No matching route for {method} {path}\\\"\\n    raise AssertionError(msg)\\n\\n\\ndef test_configs_path_matches_configs_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    assert _resolve_endpoint_name(deployment_routes, path=\\\"/deployments/configs\\\") == \\\"list_deployment_configs\\\"\\n\\n\\ndef test_types_path_matches_types_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    assert _resolve_endpoint_name(deployment_routes, path=\\\"/deployments/types\\\") == \\\"list_deployment_types\\\"\\n\\n\\ndef test_llms_path_matches_llms_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    assert _resolve_endpoint_name(deployment_routes, path=\\\"/deployments/llms\\\") == \\\"list_deployment_llms\\\"\\n\\n\\ndef test_snapshots_path_matches_snapshots_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    assert _resolve_endpoint_name(deployment_routes, path=\\\"/deployments/snapshots\\\") == \\\"list_deployment_snapshots\\\"\\n\\n\\ndef test_configs_route_excludes_none_fields_in_response_model(deployment_routes: list[APIRoute]) -> None:\\n    route = _resolve_route(deployment_routes, path=\\\"/deployments/configs\\\")\\n    assert route.response_model_exclude_none is True\\n\\n\\ndef test_snapshots_route_excludes_none_fields_in_response_model(deployment_routes: list[APIRoute]) -> None:\\n    route = _resolve_route(deployment_routes, path=\\\"/deployments/snapshots\\\")\\n    assert route.response_model_exclude_none is True\\n\\n\\ndef test_snapshot_patch_path_matches_update_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    assert (\\n        _resolve_endpoint_name(\\n            deployment_routes,\\n            path=\\\"/deployments/snapshots/tool-123\\\",\\n            method=\\\"PATCH\\\",\\n        )\\n        == \\\"update_snapshot\\\"\\n    )\\n\\n\\ndef test_deployment_status_path_is_not_registered(deployment_routes: list[APIRoute]) -> None:\\n    deployment_id = uuid4()\\n    with pytest.raises(AssertionError, match=\\\"No matching route\\\"):\\n        _resolve_endpoint_name(\\n            deployment_routes,\\n            path=f\\\"/deployments/{deployment_id}/status\\\",\\n        )\\n\\n\\ndef test_deployment_flows_path_matches_flow_versions_endpoint(deployment_routes: list[APIRoute]) -> None:\\n    deployment_id = uuid4()\\n    assert (\\n        _resolve_endpoint_name(\\n            deployment_routes,\\n            path=f\\\"/deployments/{deployment_id}/flows\\\",\\n        )\\n        == \\\"list_deployment_flow_versions\\\"\\n    )\\n\\n\\ndef test_include_deployment_router_skips_routes_when_feature_disabled(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setattr(api_router_module.FEATURE_FLAGS, \\\"wxo_deployments\\\", False)\\n\\n    router_v1 = APIRouter(prefix=\\\"/v1\\\")\\n    api_router_module.include_deployment_router(router_v1)\\n\\n    assert all(\\\"/deployments\\\" not in route.path for route in _flatten_api_routes(router_v1))\\n\\n\\ndef test_include_deployment_router_adds_routes_when_feature_enabled(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setattr(api_router_module.FEATURE_FLAGS, \\\"wxo_deployments\\\", True)\\n\\n    router_v1 = APIRouter(prefix=\\\"/v1\\\")\\n    api_router_module.include_deployment_router(router_v1)\\n\\n    assert any(\\\"/deployments\\\" in route.path for route in _flatten_api_routes(router_v1))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deployments_telemetry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d1b862d90a15726d845c269625397f05bf0c8249a807d6c039a346774795e6e\",\"content\":\"# ruff: noqa: ARG001\\nfrom __future__ import annotations\\n\\nfrom contextlib import ExitStack\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import status\\nfrom lfx.services.settings.feature_flags import FEATURE_FLAGS\\n\\nif TYPE_CHECKING:\\n    from httpx import AsyncClient\\n\\n# We'll use a mocked adapter so we don't need real credentials.\\n# We need to mock the adapter resolution and the telemetry service.\\n\\npytestmark = pytest.mark.skipif(\\n    not FEATURE_FLAGS.wxo_deployments,\\n    reason=\\\"wxo_deployments feature flag is disabled; deployment routes are not mounted.\\\",\\n)\\n\\n\\n@pytest.fixture\\ndef mock_telemetry_service():\\n    with patch(\\\"langflow.api.v1.deployments.get_telemetry_service\\\") as mock_get:\\n        mock_ts = AsyncMock()\\n        mock_get.return_value = mock_ts\\n        yield mock_ts\\n\\n\\n@pytest.fixture\\ndef mock_adapter():\\n    with patch(\\\"langflow.api.v1.deployments.resolve_deployment_adapter\\\") as mock_resolve:\\n        mock_ad = AsyncMock()\\n        mock_resolve.return_value = mock_ad\\n        yield mock_ad\\n\\n\\n@pytest.fixture\\ndef mock_mapper():\\n    with patch(\\\"langflow.api.v1.deployments.get_deployment_mapper\\\") as mock_get:\\n        mock_map = MagicMock()\\n        # Ensure it returns something valid for verify_credentials\\n        mock_map.resolve_verify_credentials_for_create.return_value = {}\\n        mock_map.resolve_verify_credentials_for_update.return_value = {}\\n        mock_map.resolve_provider_account_create.return_value = AsyncMock(\\n            id=uuid4(), provider_key=\\\"watsonx-orchestrate\\\"\\n        )\\n        mock_map.resolve_provider_account_response.return_value = {\\n            \\\"id\\\": str(uuid4()),\\n            \\\"provider_key\\\": \\\"watsonx-orchestrate\\\",\\n            \\\"name\\\": \\\"Test\\\",\\n        }\\n        mock_map.util_existing_deployment_resource_key_for_create.return_value = None\\n        mock_map.resolve_deployment_create = AsyncMock(return_value={})\\n        mock_map.resolve_deployment_update = AsyncMock(return_value={})\\n        mock_map.util_create_flow_version_ids.return_value = []\\n        mock_map.shape_deployment_create_result.return_value = {\\n            \\\"id\\\": str(uuid4()),\\n            \\\"provider_id\\\": str(uuid4()),\\n            \\\"provider_key\\\": \\\"watsonx-orchestrate\\\",\\n            \\\"display_name\\\": \\\"Test\\\",\\n            \\\"type\\\": \\\"agent\\\",\\n            \\\"resource_key\\\": \\\"res-1\\\",\\n        }\\n        mock_map.shape_deployment_update_result.return_value = {\\n            \\\"id\\\": str(uuid4()),\\n            \\\"provider_id\\\": str(uuid4()),\\n            \\\"provider_key\\\": \\\"watsonx-orchestrate\\\",\\n            \\\"display_name\\\": \\\"Test\\\",\\n            \\\"type\\\": \\\"agent\\\",\\n            \\\"resource_key\\\": \\\"res-1\\\",\\n        }\\n        mock_map.resolve_execution_create = AsyncMock(return_value={})\\n        mock_map.shape_execution_create_result.return_value = {\\\"id\\\": \\\"run-1\\\", \\\"deployment_id\\\": str(uuid4())}\\n        mock_map.resolve_snapshot_update_artifact.return_value = {}\\n        mock_get.return_value = mock_map\\n        yield mock_map\\n\\n\\n@pytest.fixture\\ndef mock_db_crud(mock_mapper, active_user):\\n    with ExitStack() as stack:\\n        mock_create = stack.enter_context(patch(\\\"langflow.api.v1.deployments.create_provider_account_row\\\"))\\n        mock_get_owned = stack.enter_context(patch(\\\"langflow.api.v1.deployments.get_owned_provider_account_or_404\\\"))\\n        _mock_del_prov = stack.enter_context(patch(\\\"langflow.api.v1.deployments.delete_provider_account_row\\\"))\\n        _mock_upd_prov = stack.enter_context(patch(\\\"langflow.api.v1.deployments.update_provider_account_row\\\"))\\n        mock_proj_id = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.resolve_project_id_for_deployment_create\\\")\\n        )\\n        mock_create_dep = stack.enter_context(patch(\\\"langflow.api.v1.deployments.create_deployment_db\\\"))\\n        _mock_attach = stack.enter_context(patch(\\\"langflow.api.v1.deployments.attach_flow_versions\\\"))\\n        mock_res_am = stack.enter_context(patch(\\\"langflow.api.v1.deployments.resolve_adapter_mapper_from_deployment\\\"))\\n        mock_res_patch = stack.enter_context(patch(\\\"langflow.api.v1.deployments.resolve_flow_version_patch_for_update\\\"))\\n        _mock_val_proj = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.validate_project_scoped_flow_version_ids\\\")\\n        )\\n        mock_list_att = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.list_deployment_attachments_for_flow_version_ids\\\")\\n        )\\n        _mock_apply_patch = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.apply_flow_version_patch_attachments\\\")\\n        )\\n        mock_upd_dep = stack.enter_context(patch(\\\"langflow.api.v1.deployments.update_deployment_db\\\"))\\n        mock_res_ad = stack.enter_context(patch(\\\"langflow.api.v1.deployments.resolve_adapter_from_deployment\\\"))\\n        _mock_del_dep = stack.enter_context(patch(\\\"langflow.api.v1.deployments._delete_local_deployment_row\\\"))\\n        mock_list_att_by_snapshot = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.list_attachments_by_provider_snapshot_id\\\")\\n        )\\n        mock_get_dep_row = stack.enter_context(\\n            patch(\\\"langflow.services.database.models.deployment.crud.get_deployment\\\")\\n        )\\n        mock_get_fv = stack.enter_context(\\n            patch(\\\"langflow.services.database.models.flow_version.crud.get_flow_version_entry\\\")\\n        )\\n        mock_upd_fv = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments.update_flow_version_by_provider_snapshot_id\\\")\\n        )\\n        mock_count_deps = stack.enter_context(\\n            patch(\\\"langflow.api.v1.deployments._count_provider_deployments_after_reconciliation\\\")\\n        )\\n\\n        mock_create.return_value = AsyncMock(\\n            id=uuid4(), provider_key=\\\"watsonx-orchestrate\\\", provider_tenant_id=\\\"tenant-test\\\"\\n        )\\n        mock_get_owned.return_value = AsyncMock(\\n            id=uuid4(), provider_key=\\\"watsonx-orchestrate\\\", provider_tenant_id=\\\"tenant-test\\\"\\n        )\\n        mock_proj_id.return_value = uuid4()\\n        mock_create_dep.return_value = AsyncMock(id=uuid4())\\n\\n        mock_res_am.return_value = (\\n            AsyncMock(id=uuid4(), resource_key=\\\"res-1\\\", deployment_provider_account_id=uuid4(), project_id=uuid4()),\\n            AsyncMock(),\\n            mock_mapper,\\n            \\\"watsonx-orchestrate\\\",\\n            \\\"tenant-test\\\",\\n        )\\n        mock_res_patch.return_value = ([], [])\\n        mock_list_att.return_value = []\\n        mock_upd_dep.return_value = AsyncMock()\\n        mock_res_ad.return_value = (\\n            AsyncMock(id=uuid4(), resource_key=\\\"res-1\\\", deployment_provider_account_id=uuid4()),\\n            AsyncMock(),\\n            \\\"watsonx-orchestrate\\\",\\n            \\\"tenant-test\\\",\\n        )\\n        # ``update_snapshot`` now enumerates every attachment with the\\n        # given provider_snapshot_id and authorizes each one's deployment.\\n        # The fake deployment row carries a stable user_id so the candidate\\n        # filter keeps it under the OSS pass-through path.\\n        snapshot_deployment_id = uuid4()\\n        snapshot_owner_id = active_user.id\\n        snapshot_project_id = uuid4()\\n        mock_list_att_by_snapshot.return_value = [\\n            SimpleNamespace(\\n                deployment_id=snapshot_deployment_id,\\n                flow_version_id=uuid4(),\\n                user_id=snapshot_owner_id,\\n                provider_snapshot_id=\\\"snap-1\\\",\\n            )\\n        ]\\n        mock_get_dep_row.return_value = SimpleNamespace(\\n            id=snapshot_deployment_id,\\n            user_id=snapshot_owner_id,\\n            deployment_provider_account_id=uuid4(),\\n            workspace_id=None,\\n            project_id=snapshot_project_id,\\n        )\\n        mock_get_fv.return_value = AsyncMock(flow_id=uuid4(), data={})\\n        mock_upd_fv.return_value = 1\\n        mock_count_deps.return_value = 0\\n\\n        yield\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_provider_account_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.post(\\n        \\\"api/v1/deployments/providers\\\",\\n        json={\\\"provider_key\\\": \\\"watsonx-orchestrate\\\", \\\"name\\\": \\\"Test\\\", \\\"provider_data\\\": {\\\"foo\\\": \\\"bar\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    mock_telemetry_service.log_package_deployment_provider.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment_provider.call_args[0][0]\\n    assert payload.deployment_action == \\\"provider.create\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_provider_account_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.patch(\\n        f\\\"api/v1/deployments/providers/{uuid4()}\\\",\\n        json={\\\"name\\\": \\\"Test\\\", \\\"provider_data\\\": {\\\"foo\\\": \\\"bar\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_200_OK\\n    mock_telemetry_service.log_package_deployment_provider.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment_provider.call_args[0][0]\\n    assert payload.deployment_action == \\\"provider.update\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_provider_account_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.delete(f\\\"api/v1/deployments/providers/{uuid4()}\\\", headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_204_NO_CONTENT\\n    mock_telemetry_service.log_package_deployment_provider.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment_provider.call_args[0][0]\\n    assert payload.deployment_action == \\\"provider.delete\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.post(\\n        \\\"api/v1/deployments\\\",\\n        json={\\\"provider_id\\\": str(uuid4()), \\\"type\\\": \\\"agent\\\", \\\"provider_data\\\": {\\\"display_name\\\": \\\"Test\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED, response.json()\\n    mock_telemetry_service.log_package_deployment.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment.call_args[0][0]\\n    assert payload.deployment_action == \\\"deployment.create\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.patch(\\n        f\\\"api/v1/deployments/{uuid4()}\\\",\\n        json={\\\"provider_data\\\": {\\\"display_name\\\": \\\"Test\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_200_OK\\n    mock_telemetry_service.log_package_deployment.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment.call_args[0][0]\\n    assert payload.deployment_action == \\\"deployment.update\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_deployment_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.delete(f\\\"api/v1/deployments/{uuid4()}\\\", headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_204_NO_CONTENT\\n    mock_telemetry_service.log_package_deployment.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment.call_args[0][0]\\n    assert payload.deployment_action == \\\"deployment.delete\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_run_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.post(\\n        f\\\"api/v1/deployments/{uuid4()}/runs\\\", json={\\\"provider_data\\\": {}}, headers=logged_in_headers\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED, response.json()\\n    mock_telemetry_service.log_package_deployment_run.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment_run.call_args[0][0]\\n    assert payload.deployment_action == \\\"deployment.run\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_snapshot_telemetry(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    response = await client.patch(\\n        \\\"api/v1/deployments/snapshots/snap-1\\\", json={\\\"flow_version_id\\\": str(uuid4())}, headers=logged_in_headers\\n    )\\n    assert response.status_code == status.HTTP_200_OK\\n    mock_telemetry_service.log_package_deployment.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment.call_args[0][0]\\n    assert payload.deployment_action == \\\"snapshot.update\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is True\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_provider_account_telemetry_error(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    mock_adapter.verify_credentials.side_effect = ValueError(\\\"Invalid credentials\\\")\\n    response = await client.post(\\n        \\\"api/v1/deployments/providers\\\",\\n        json={\\\"provider_key\\\": \\\"watsonx-orchestrate\\\", \\\"name\\\": \\\"Test\\\", \\\"provider_data\\\": {\\\"foo\\\": \\\"bar\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_400_BAD_REQUEST\\n    mock_telemetry_service.log_package_deployment_provider.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment_provider.call_args[0][0]\\n    assert payload.deployment_action == \\\"provider.create\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"\\n    assert payload.deployment_success is False\\n    assert payload.deployment_error_message == \\\"400: Invalid credentials\\\"\\n    # verify_credentials raises before the row is created, so the tenant_id is not yet set.\\n    assert payload.wxo_tenant_id is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cross_route_smoke_exception_after_provider_set(\\n    client: AsyncClient, mock_telemetry_service, mock_adapter, mock_mapper, mock_db_crud, logged_in_headers\\n):\\n    # Simulate an error during adapter.create after the provider has been set in the route\\n    mock_adapter.create.side_effect = RuntimeError(\\\"Something went wrong\\\")\\n    response = await client.post(\\n        \\\"api/v1/deployments\\\",\\n        json={\\\"provider_id\\\": str(uuid4()), \\\"type\\\": \\\"agent\\\", \\\"provider_data\\\": {\\\"display_name\\\": \\\"Test\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_500_INTERNAL_SERVER_ERROR\\n    mock_telemetry_service.log_package_deployment.assert_awaited_once()\\n    payload = mock_telemetry_service.log_package_deployment.call_args[0][0]\\n    assert payload.deployment_action == \\\"deployment.create\\\"\\n    assert payload.deployment_provider == \\\"watsonx-orchestrate\\\"  # Provider should be captured!\\n    assert payload.deployment_success is False\\n    assert payload.deployment_error_message == (\\n        \\\"500: An unexpected error occurred while communicating with the deployment provider.\\\"\\n    )\\n    # tenant_id is captured before the adapter call that raises.\\n    assert payload.wxo_tenant_id == \\\"tenant-test\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deprecated_vertex_route_authz.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4a9af1042ac279ff49a3ccdc155aa5926b08ae7e8df22094fad7f3dc9fd2a325\",\"content\":\"\\\"\\\"\\\"Authorization regressions for deprecated V1 vertex routes.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Literal\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom langflow.services.deps import get_chat_service\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.services.model_provider_policy import current_model_provider_policy_context\\n\\nif TYPE_CHECKING:\\n    from httpx import AsyncClient, Response\\n\\nRouteName = Literal[\\\"order\\\", \\\"build\\\", \\\"stream\\\"]\\nCacheState = Literal[\\\"empty\\\", \\\"owner_seeded\\\"]\\n\\n\\nasync def _login_second_user(client: AsyncClient, user_two) -> dict[str, str]:\\n    response = await client.post(\\n        \\\"api/v1/login\\\",\\n        data={\\\"username\\\": user_two.username, \\\"password\\\": \\\"hashed_password\\\"},  # pragma: allowlist secret\\n    )\\n    assert response.status_code == 200\\n    return {\\\"Authorization\\\": f\\\"Bearer {response.json()['access_token']}\\\"}\\n\\n\\nasync def _request_route(\\n    client: AsyncClient,\\n    *,\\n    route_name: RouteName,\\n    flow_id: str,\\n    vertex_id: str,\\n    headers: dict[str, str],\\n) -> Response:\\n    if route_name == \\\"order\\\":\\n        return await client.post(f\\\"api/v1/build/{flow_id}/vertices\\\", headers=headers)\\n    if route_name == \\\"build\\\":\\n        return await client.post(f\\\"api/v1/build/{flow_id}/vertices/{vertex_id}\\\", headers=headers)\\n    return await client.get(f\\\"api/v1/build/{flow_id}/{vertex_id}/stream\\\", headers=headers)\\n\\n\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\\"cache_state\\\", [\\\"empty\\\", \\\"owner_seeded\\\"])\\n@pytest.mark.parametrize(\\\"route_name\\\", [\\\"order\\\", \\\"build\\\", \\\"stream\\\"])\\nasync def test_non_owner_public_flow_is_hidden_from_deprecated_vertex_routes(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    user_two,\\n    monkeypatch: pytest.MonkeyPatch,\\n    route_name: RouteName,\\n    cache_state: CacheState,\\n):\\n    \\\"\\\"\\\"A PUBLIC transition must not widen the owner-only legacy vertex surface.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n    other_headers = await _login_second_user(client, user_two)\\n\\n    # Capture the exact same-flow privacy response while it is still PRIVATE.\\n    private_response = await _request_route(\\n        client,\\n        route_name=route_name,\\n        flow_id=flow_id,\\n        vertex_id=vertex_id,\\n        headers=other_headers,\\n    )\\n    assert private_response.status_code == 404\\n\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == 200\\n\\n    chat_service = get_chat_service()\\n    await chat_service.clear_cache(str(flow_id))\\n    if cache_state == \\\"owner_seeded\\\":\\n        seed_response = await client.post(f\\\"api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n        assert seed_response.status_code == 200\\n        vertex_id = seed_response.json()[\\\"ids\\\"][0]\\n\\n    # Owner-only denial must happen before touching the flow-keyed graph cache\\n    # or any MemoryBase owner/backend credential seam.\\n    get_chat_service_spy = MagicMock(wraps=chat_module.get_chat_service)\\n    monkeypatch.setattr(chat_module, \\\"get_chat_service\\\", get_chat_service_spy)\\n\\n    public_response = await _request_route(\\n        client,\\n        route_name=route_name,\\n        flow_id=flow_id,\\n        vertex_id=vertex_id,\\n        headers=other_headers,\\n    )\\n\\n    get_chat_service_spy.assert_not_called()\\n    assert public_response.status_code == private_response.status_code == 404\\n    assert public_response.json() == private_response.json() == {\\\"detail\\\": f\\\"Flow with id {flow_id} not found\\\"}\\n\\n\\n@pytest.mark.security\\nasync def test_owner_keeps_all_deprecated_vertex_routes_after_public_transition(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n):\\n    \\\"\\\"\\\"Making a flow PUBLIC must not break its owner's legacy editor path.\\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    patch_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_id}\\\",\\n        json={\\\"access_type\\\": \\\"PUBLIC\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert patch_response.status_code == 200\\n\\n    order_response = await client.post(f\\\"api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n    assert order_response.status_code == 200\\n    vertex_id = order_response.json()[\\\"ids\\\"][0]\\n\\n    build_response = await client.post(\\n        f\\\"api/v1/build/{flow_id}/vertices/{vertex_id}\\\",\\n        json={\\\"inputs\\\": {\\\"input_value\\\": \\\"owner input\\\", \\\"session\\\": \\\"owner-session\\\"}},\\n        headers=logged_in_headers,\\n    )\\n    assert build_response.status_code == 200\\n\\n    async with client.stream(\\n        \\\"GET\\\",\\n        f\\\"api/v1/build/{flow_id}/{vertex_id}/stream\\\",\\n        headers=logged_in_headers,\\n    ) as stream_response:\\n        assert stream_response.status_code == 200\\n        await stream_response.aread()\\n\\n\\n@pytest.mark.security\\nasync def test_owner_deprecated_vertex_routes_bind_stored_flow_provider_scope(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"Cold builds, warm vertex builds, and SSE iteration reuse the trusted flow scope.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    captured = {}\\n    original_build_graph = chat_module.build_graph_from_db\\n    original_build_vertex = Graph.build_vertex\\n\\n    async def capture_graph_scope(*args, **kwargs):\\n        captured[\\\"order\\\"] = current_model_provider_policy_context()\\n        return await original_build_graph(*args, **kwargs)\\n\\n    async def capture_vertex_scope(self, *args, **kwargs):\\n        captured[\\\"build\\\"] = current_model_provider_policy_context()\\n        return await original_build_vertex(self, *args, **kwargs)\\n\\n    async def capture_stream_scope(*_args, **_kwargs):\\n        captured[\\\"stream\\\"] = current_model_provider_policy_context()\\n        yield 'event: close\\\\ndata: {\\\"message\\\": \\\"Stream closed\\\"}\\\\n\\\\n'\\n\\n    monkeypatch.setattr(chat_module, \\\"build_graph_from_db\\\", capture_graph_scope)\\n    monkeypatch.setattr(Graph, \\\"build_vertex\\\", capture_vertex_scope)\\n    monkeypatch.setattr(chat_module, \\\"_stream_vertex\\\", capture_stream_scope)\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    order_response = await client.post(f\\\"api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n    assert order_response.status_code == 200, order_response.text\\n    vertex_id = order_response.json()[\\\"ids\\\"][0]\\n\\n    build_response = await client.post(\\n        f\\\"api/v1/build/{flow_id}/vertices/{vertex_id}\\\",\\n        headers=logged_in_headers,\\n    )\\n    assert build_response.status_code == 200, build_response.text\\n\\n    async with client.stream(\\n        \\\"GET\\\",\\n        f\\\"api/v1/build/{flow_id}/{vertex_id}/stream\\\",\\n        headers=logged_in_headers,\\n    ) as stream_response:\\n        assert stream_response.status_code == 200\\n        await stream_response.aread()\\n\\n    for route in (\\\"order\\\", \\\"build\\\", \\\"stream\\\"):\\n        attributes = captured[route].attributes\\n        assert attributes[\\\"provider_scope_required\\\"] is True\\n        assert str(attributes[\\\"project_id\\\"]) == added_flow_webhook_test[\\\"folder_id\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deprecated_vertex_route_component_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"176df22a1a7f173d88e7c02130275e491c2d5f7115ca8af9eec6993a6efc0138\",\"content\":\"\\\"\\\"\\\"LE-2356: the single-vertex build seam must run the caller-aware component policy.\\n\\n``POST /api/v1/build/{flow_id}/vertices/{vertex_id}`` compiled the graph persisted on\\nthe flow row and executed one vertex from it. The stored graph is caller-controlled --\\nany user who can write a flow can persist Python through the ordinary flow API -- and\\nthis seam applied only the caller-agnostic global validator. So with\\n``custom_component_admin_only`` on, a non-admin was refused on\\n``/run/{id}``, ``/build/{id}/flow`` and ``/v2/workflows`` yet executed their own source\\nhere.\\n\\nReproduced over real HTTP as two real principals before the fix: ``build/{id}/flow``\\nanswered ``400`` for the non-admin while ``build/{id}/vertices/{vid}`` answered ``200``\\nand returned the marker from their own class.\\n\\nThe policy substitutes the server's trusted source rather than blanket-refusing, so the\\ncontrol that a permissive policy still builds matters as much as the denial: a refusal\\nfor everyone would be a denial of service wearing a security fix's clothes.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import AsyncMock, MagicMock\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from httpx import AsyncClient\\n\\n\\ndef _vertex_route(flow_id: str, vertex_id: str) -> str:\\n    return f\\\"api/v1/build/{flow_id}/vertices/{vertex_id}\\\"\\n\\n\\n@pytest.mark.security\\nasync def test_should_refuse_when_the_caller_aware_policy_rejects_the_stored_graph(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"A policy rejection must surface as 400 and never reach a graph constructor.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from lfx.utils.flow_validation import CustomComponentValidationError\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n    seen: dict = {}\\n\\n    async def reject(data, *, is_superuser):\\n        seen[\\\"data\\\"] = data\\n        seen[\\\"is_superuser\\\"] = is_superuser\\n        message = \\\"custom components are not allowed\\\"\\n        raise CustomComponentValidationError(message)\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", reject)\\n    build_spy = MagicMock(side_effect=AssertionError(\\\"graph must not be built after a policy denial\\\"))\\n    monkeypatch.setattr(chat_module, \\\"build_graph_from_db\\\", build_spy)\\n\\n    response = await client.post(_vertex_route(flow_id, vertex_id), headers=logged_in_headers)\\n\\n    assert response.status_code == 400\\n    assert \\\"custom components are not allowed\\\" in response.json()[\\\"detail\\\"]\\n    assert seen[\\\"data\\\"] == added_flow_webhook_test[\\\"data\\\"], \\\"the policy must see the STORED graph\\\"\\n    build_spy.assert_not_called()\\n\\n\\n@pytest.mark.security\\nasync def test_should_run_the_policy_with_the_callers_own_privilege(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"The gate is caller-aware: it must be told who is asking, not assume a principal.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n    calls: list[dict] = []\\n\\n    async def record(_data, *, is_superuser):\\n        calls.append({\\\"is_superuser\\\": is_superuser})\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", record)\\n\\n    await client.post(_vertex_route(flow_id, vertex_id), headers=logged_in_headers)\\n\\n    assert calls, \\\"the seam never consulted the caller-aware policy\\\"\\n    assert isinstance(calls[0][\\\"is_superuser\\\"], bool)\\n\\n\\n@pytest.mark.security\\nasync def test_should_build_from_the_sanitized_copy_not_the_stored_bytes(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"When the policy substitutes trusted source, that copy is what must be compiled.\\n\\n    Rebuilding is required even on a cache hit: cache keys carry no policy generation,\\n    so a graph compiled while the policy was off still embeds the caller's own source.\\n    \\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n    sanitized = {\\\"nodes\\\": [{\\\"id\\\": vertex_id, \\\"data\\\": {\\\"id\\\": vertex_id, \\\"type\\\": \\\"ChatInput\\\"}}], \\\"edges\\\": []}\\n\\n    async def substitute(_data, *, is_superuser):  # noqa: ARG001\\n        return sanitized\\n\\n    built_from: dict = {}\\n\\n    async def fake_build(*, flow_id, chat_service, graph_data):  # noqa: ARG001\\n        built_from[\\\"graph_data\\\"] = graph_data\\n        graph = MagicMock()\\n        graph.set_run_id = MagicMock()\\n        graph.initialize_run = AsyncMock()\\n        # A real graph exposes a string run_id; the seam reads it back after\\n        # initialize_run and hands it to the telemetry payload, which validates it.\\n        graph.run_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n        # raw_graph_data must not look like the sanitized payload, or the seam would\\n        # (correctly) reuse this compilation instead of rebuilding.\\n        graph.raw_graph_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        return graph\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", substitute)\\n    monkeypatch.setattr(chat_module, \\\"build_and_cache_graph_from_data\\\", fake_build)\\n\\n    await client.post(_vertex_route(flow_id, vertex_id), headers=logged_in_headers)\\n\\n    assert built_from.get(\\\"graph_data\\\") is sanitized, \\\"the seam compiled the stored bytes, not the trusted copy\\\"\\n\\n\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\\"failure\\\", [\\\"identity_unavailable\\\", \\\"settings_unavailable\\\"])\\nasync def test_should_fail_closed_when_the_policy_cannot_be_evaluated(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n    failure: str,\\n):\\n    \\\"\\\"\\\"An undecidable policy must refuse with 503, never fall through to execution.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from lfx.utils.flow_validation import CatalogPolicyIdentityUnavailableError\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n    error = (\\n        CatalogPolicyIdentityUnavailableError(\\\"identity unavailable\\\")\\n        if failure == \\\"identity_unavailable\\\"\\n        else RuntimeError(\\\"settings service required\\\")\\n    )\\n\\n    async def blow_up(_data, *, is_superuser):  # noqa: ARG001\\n        raise error\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", blow_up)\\n    build_spy = MagicMock(side_effect=AssertionError(\\\"graph must not be built when the policy is undecidable\\\"))\\n    monkeypatch.setattr(chat_module, \\\"build_graph_from_db\\\", build_spy)\\n\\n    response = await client.post(_vertex_route(flow_id, vertex_id), headers=logged_in_headers)\\n\\n    assert response.status_code == 503\\n    build_spy.assert_not_called()\\n\\n\\n@pytest.mark.security\\nasync def test_should_keep_building_normally_under_a_permissive_policy(\\n    client: AsyncClient,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n):\\n    \\\"\\\"\\\"The control: with the policy off the seam behaves exactly as before.\\n\\n    A refusal for everyone would be a denial of service, not a fix.\\n    \\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    vertex_id = added_flow_webhook_test[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n\\n    response = await client.post(_vertex_route(flow_id, vertex_id), headers=logged_in_headers)\\n\\n    assert response.status_code == 200\\n    assert response.json()[\\\"id\\\"] == vertex_id\\n\\n\\nCALLER_AUTHORED_SOURCE = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\nfrom lfx.io import Output\\nfrom lfx.schema import Data\\n\\n\\nclass LE2356Probe(Component):\\n    display_name = \\\"LE2356 Probe\\\"\\n    name = \\\"LE2356Probe\\\"\\n    inputs = []\\n    outputs = [Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"run_probe\\\")]\\n\\n    def run_probe(self) -> Data:\\n        return Data(data={\\\"marker\\\": \\\"OWN_CODE_RAN\\\"})\\n\\\"\\\"\\\"\\n\\n\\ndef _flow_with_caller_authored_source() -> dict:\\n    \\\"\\\"\\\"A flow whose component source is the caller's own, matching no registry hash.\\\"\\\"\\\"\\n    node_id = \\\"LE2356Probe-1\\\"\\n    return {\\n        \\\"name\\\": \\\"le2356 caller authored\\\",\\n        \\\"description\\\": \\\"regression fixture\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": node_id,\\n                    \\\"type\\\": \\\"genericNode\\\",\\n                    \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n                    \\\"data\\\": {\\n                        \\\"id\\\": node_id,\\n                        \\\"type\\\": \\\"CustomComponent\\\",\\n                        \\\"node\\\": {\\n                            \\\"base_classes\\\": [\\\"Data\\\"],\\n                            \\\"display_name\\\": \\\"LE2356 Probe\\\",\\n                            \\\"template\\\": {\\n                                \\\"_type\\\": \\\"Component\\\",\\n                                \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"name\\\": \\\"code\\\", \\\"value\\\": CALLER_AUTHORED_SOURCE, \\\"show\\\": True},\\n                            },\\n                            \\\"outputs\\\": [\\n                                {\\n                                    \\\"types\\\": [\\\"Data\\\"],\\n                                    \\\"selected\\\": \\\"Data\\\",\\n                                    \\\"name\\\": \\\"result\\\",\\n                                    \\\"display_name\\\": \\\"Result\\\",\\n                                    \\\"method\\\": \\\"run_probe\\\",\\n                                    \\\"value\\\": \\\"__UNDEFINED__\\\",\\n                                    \\\"cache\\\": True,\\n                                }\\n                            ],\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n            \\\"viewport\\\": {\\\"x\\\": 0, \\\"y\\\": 0, \\\"zoom\\\": 1},\\n        },\\n    }\\n\\n\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\\"route\\\", [\\\"order\\\", \\\"build\\\"])\\nasync def test_real_policy_refuses_caller_authored_source_on_the_deprecated_seams(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n    route: str,\\n):\\n    \\\"\\\"\\\"End-to-end with the REAL policy: no stand-in for prepare_flow_build_for_user.\\n\\n    The mocked tests above prove the seam honours the policy's outcomes; this one runs the\\n    real policy so a regression INSIDE it cannot pass unnoticed.\\n\\n    Discrimination, measured against release-1.12.0 rather than assumed: the ``order``\\n    case fails there (that route had no caller-aware policy at all). The ``build`` case\\n    passes there too, because in this test environment the registry hash lookups are warm\\n    and the global validator already refuses this payload -- so for that route the\\n    discriminating evidence is the mocked tests above, which do fail, plus the live HTTP\\n    probe in the PR description. Keeping it here still pins the end-to-end contract.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n\\n    created = await client.post(\\\"api/v1/flows/\\\", json=_flow_with_caller_authored_source(), headers=logged_in_headers)\\n    assert created.status_code == 201\\n    flow_id = created.json()[\\\"id\\\"]\\n    node_id = created.json()[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n\\n    path = f\\\"api/v1/build/{flow_id}/vertices\\\" if route == \\\"order\\\" else f\\\"api/v1/build/{flow_id}/vertices/{node_id}\\\"\\n    response = await client.post(path, headers=logged_in_headers)\\n\\n    assert response.status_code == 400, f\\\"non-admin executed their own source on {path}: {response.text[:300]}\\\"\\n    assert \\\"OWN_CODE_RAN\\\" not in response.text\\n\\n    await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n\\n\\n@pytest.mark.security\\n@pytest.mark.parametrize(\\\"route\\\", [\\\"order\\\", \\\"build\\\"])\\nasync def test_real_policy_leaves_a_superuser_alone_on_the_deprecated_seams(\\n    client: AsyncClient,\\n    logged_in_headers_super_user,\\n    monkeypatch: pytest.MonkeyPatch,\\n    route: str,\\n):\\n    \\\"\\\"\\\"The contrast that makes the denial meaningful: the gate is caller-aware.\\n\\n    If an admin were refused too, the change would be a blanket outage rather than a\\n    policy, and the test above would pass for the wrong reason.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n\\n    created = await client.post(\\n        \\\"api/v1/flows/\\\", json=_flow_with_caller_authored_source(), headers=logged_in_headers_super_user\\n    )\\n    assert created.status_code == 201\\n    flow_id = created.json()[\\\"id\\\"]\\n    node_id = created.json()[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"]\\n\\n    path = f\\\"api/v1/build/{flow_id}/vertices\\\" if route == \\\"order\\\" else f\\\"api/v1/build/{flow_id}/vertices/{node_id}\\\"\\n    response = await client.post(path, headers=logged_in_headers_super_user)\\n\\n    assert response.status_code != 400, f\\\"the admin-only policy refused an admin on {path}: {response.text[:300]}\\\"\\n\\n    await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers_super_user)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_deprecated_vertex_route_incremental_state.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ad7986b167e9c38deae73f599dd5b9d3cb7282e20203bf877756a92f2c2558e\",\"content\":\"\\\"\\\"\\\"LE-2356 follow-up: the policy must not destroy the seam's incremental state.\\n\\n``POST /build/{flow_id}/vertices/{vertex_id}`` is called once per vertex and carries\\nbuilt state in the flow's graph cache between requests, so a downstream vertex can\\nread what its upstream produced. The admin-only policy fix rebuilt the graph whenever\\n``prepare_flow_build_for_user`` returned a sanitized copy -- which is *every* request\\nfrom a non-superuser while the policy is on, not only the first. Each call therefore\\noverwrote the cache entry holding the previous vertex's result, and the second vertex\\nreported its upstream as unbuilt.\\n\\nReported by QA against the PR head: same flow, same server, admin propagates and\\nnon-admin loses the state; with the policy off the non-admin propagates too. The\\ntrigger is exactly admin-only + non-superuser.\\n\\nThe rebuild is still required once, because a graph compiled while the policy was off\\nembeds the caller's own component source. What was missing is a record of WHICH policy\\ngeneration compiled the cached graph, so the rebuild happens once instead of per call.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from httpx import AsyncClient\\n\\nMARKER = \\\"MARCADOR-123\\\"\\n\\n\\nasync def _trusted_two_node_flow() -> dict:\\n    \\\"\\\"\\\"A ChatInput -> ChatOutput flow whose code is the server's own.\\n\\n    Taking the source from the live registry is what makes the admin-only policy\\n    APPROVE this flow rather than reject it, so the test exercises the allowed path\\n    the report is about.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n    from lfx.interface.components import get_and_cache_all_types_dict\\n\\n    all_types = await get_and_cache_all_types_dict(get_settings_service())\\n\\n    def template_for(component_type: str) -> dict:\\n        for category in all_types.values():\\n            if isinstance(category, dict) and component_type in category:\\n                import json\\n\\n                return json.loads(json.dumps(category[component_type]))\\n        msg = f\\\"{component_type} missing from the component registry\\\"\\n        raise RuntimeError(msg)\\n\\n    chat_input = template_for(\\\"ChatInput\\\")\\n    chat_output = template_for(\\\"ChatOutput\\\")\\n    source_id, target_id = \\\"ChatInput-le2356\\\", \\\"ChatOutput-le2356\\\"\\n\\n    return {\\n        \\\"name\\\": \\\"le2356 incremental\\\",\\n        \\\"description\\\": \\\"regression fixture\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": source_id,\\n                    \\\"type\\\": \\\"genericNode\\\",\\n                    \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n                    \\\"data\\\": {\\\"id\\\": source_id, \\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": chat_input},\\n                },\\n                {\\n                    \\\"id\\\": target_id,\\n                    \\\"type\\\": \\\"genericNode\\\",\\n                    \\\"position\\\": {\\\"x\\\": 400, \\\"y\\\": 0},\\n                    \\\"data\\\": {\\\"id\\\": target_id, \\\"type\\\": \\\"ChatOutput\\\", \\\"node\\\": chat_output},\\n                },\\n            ],\\n            \\\"edges\\\": [\\n                {\\n                    \\\"id\\\": \\\"le2356-edge\\\",\\n                    \\\"source\\\": source_id,\\n                    \\\"target\\\": target_id,\\n                    \\\"sourceHandle\\\": (\\n                        \\\"{\u0153dataType\u0153:\u0153ChatInput\u0153,\u0153id\u0153:\u0153\\\" + source_id + \\\"\u0153,\u0153name\u0153:\u0153message\u0153,\u0153output_types\u0153:[\u0153Message\u0153]}\\\"\\n                    ),\\n                    \\\"targetHandle\\\": (\\n                        \\\"{\u0153fieldName\u0153:\u0153input_value\u0153,\u0153id\u0153:\u0153\\\" + target_id + \\\"\u0153,\u0153inputTypes\u0153:[\u0153Message\u0153],\u0153type\u0153:\u0153str\u0153}\\\"\\n                    ),\\n                    \\\"data\\\": {\\n                        \\\"sourceHandle\\\": {\\n                            \\\"dataType\\\": \\\"ChatInput\\\",\\n                            \\\"id\\\": source_id,\\n                            \\\"name\\\": \\\"message\\\",\\n                            \\\"output_types\\\": [\\\"Message\\\"],\\n                        },\\n                        \\\"targetHandle\\\": {\\n                            \\\"fieldName\\\": \\\"input_value\\\",\\n                            \\\"id\\\": target_id,\\n                            \\\"inputTypes\\\": [\\\"Message\\\"],\\n                            \\\"type\\\": \\\"str\\\",\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"viewport\\\": {\\\"x\\\": 0, \\\"y\\\": 0, \\\"zoom\\\": 1},\\n        },\\n    }\\n\\n\\nasync def _build_chain(client: AsyncClient, headers: dict[str, str]) -> dict:\\n    \\\"\\\"\\\"Build the upstream vertex, then the downstream one, as the editor would.\\\"\\\"\\\"\\n    created = await client.post(\\\"api/v1/flows/\\\", json=await _trusted_two_node_flow(), headers=headers)\\n    assert created.status_code == 201\\n    flow_id = created.json()[\\\"id\\\"]\\n\\n    upstream = await client.post(\\n        f\\\"api/v1/build/{flow_id}/vertices/ChatInput-le2356\\\",\\n        json={\\\"inputs\\\": {\\\"input_value\\\": MARKER}},\\n        headers=headers,\\n    )\\n    downstream = await client.post(f\\\"api/v1/build/{flow_id}/vertices/ChatOutput-le2356\\\", headers=headers)\\n\\n    await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=headers)\\n    return {\\\"upstream\\\": upstream, \\\"downstream\\\": downstream}\\n\\n\\n@pytest.mark.security\\nasync def test_a_permitted_non_admin_keeps_state_between_vertex_builds(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"The policy approves this flow, so the seam must behave as it does without it.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n\\n    result = await _build_chain(client, logged_in_headers)\\n\\n    assert result[\\\"upstream\\\"].status_code == 200\\n    assert MARKER in result[\\\"upstream\\\"].text, \\\"the upstream vertex never ran\\\"\\n\\n    downstream = result[\\\"downstream\\\"]\\n    assert downstream.status_code == 200\\n    body = downstream.json()\\n    assert body[\\\"valid\\\"] is True, f\\\"downstream lost its upstream state: {str(body.get('params'))[:160]}\\\"\\n    assert \\\"has not been built yet\\\" not in str(body.get(\\\"params\\\", \\\"\\\"))\\n\\n\\n@pytest.mark.security\\nasync def test_a_superuser_keeps_state_between_vertex_builds(\\n    client: AsyncClient,\\n    logged_in_headers_super_user,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"The control: an admin is exempt from the policy, so this path never regressed.\\n\\n    Its value is telling a real regression apart from a broken fixture -- if BOTH\\n    principals fail, the flow itself is wrong, not the policy branch.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", True)\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n\\n    result = await _build_chain(client, logged_in_headers_super_user)\\n\\n    assert result[\\\"downstream\\\"].status_code == 200\\n    assert result[\\\"downstream\\\"].json()[\\\"valid\\\"] is True\\n\\n\\n@pytest.mark.security\\nasync def test_a_non_admin_keeps_state_with_the_policy_off(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch: pytest.MonkeyPatch,\\n):\\n    \\\"\\\"\\\"The counter-proof: with the policy off the same caller propagates.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"custom_component_admin_only\\\", False)\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", True)\\n\\n    result = await _build_chain(client, logged_in_headers)\\n\\n    assert result[\\\"downstream\\\"].status_code == 200\\n    assert result[\\\"downstream\\\"].json()[\\\"valid\\\"] is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_detect_env_vars.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"138400103e6531663737b296fb665341cb5892f8e0fb9bb0df74edad9c0ca182\",\"content\":\"\\\"\\\"\\\"Unit tests for the detect_env_vars endpoint (POST /variables/detections).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.v1.schemas.deployments import DetectVarsRequest\\nfrom langflow.api.v1.variable import detect_env_vars\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\nfrom pydantic import ValidationError\\n\\nMODULE = \\\"langflow.api.v1.variable\\\"\\n\\n\\ndef _flow_version_with_data(data: object) -> SimpleNamespace:\\n    return SimpleNamespace(data=data)\\n\\n\\ndef _node(template: dict) -> dict:\\n    return {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": template}}}\\n\\n\\ndef _variable_service_with_names(names: list[str] | None = None) -> SimpleNamespace:\\n    return SimpleNamespace(list_variables=AsyncMock(return_value=names or []))\\n\\n\\n# ---------------------------------------------------------------------------\\n# detect_env_vars endpoint\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestDetectEnvVars:\\n    @pytest.mark.asyncio\\n    async def test_returns_global_variable_refs(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"api_key\\\": {\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"MY_OPENAI_KEY\\\",\\n                            }\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"MY_OPENAI_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == [\\\"MY_OPENAI_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_filters_hidden_provider_variable_names(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"hidden_provider_key\\\": {\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"ANTHROPIC_API_KEY\\\",\\n                            },\\n                            \\\"generic_key\\\": {\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"MY_GENERIC_KEY\\\",\\n                            },\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n\\n        async def _openai_only_policy(_current_user, purpose, attributes):\\n            from lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\n\\n            assert purpose is ModelProviderPolicyPurpose.CONFIGURE\\n            assert attributes == {}\\n            return SimpleNamespace(allows=lambda provider: provider == \\\"OpenAI\\\")\\n\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"ANTHROPIC_API_KEY\\\", \\\"MY_GENERIC_KEY\\\"]),\\n            ),\\n            patch(f\\\"{MODULE}._aresolve_policy\\\", side_effect=_openai_only_policy),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n        assert result.variables == [\\\"MY_GENERIC_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_ignores_password_only_fields(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data({\\\"nodes\\\": [_node({\\\"api_key\\\": {\\\"password\\\": True}})]})\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"API_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == []\\n\\n    @pytest.mark.asyncio\\n    async def test_load_from_db_is_used_even_when_password_fields_exist(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"api_key\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"API_KEY\\\"},\\n                            \\\"other_key\\\": {\\\"password\\\": True},\\n                        }\\n                    ),\\n                    _node({\\\"api_key\\\": {\\\"password\\\": True}}),\\n                ]\\n            }\\n        )\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"API_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == [\\\"API_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_deduplicates_across_versions(self):\\n        fv1, fv2 = uuid4(), uuid4()\\n        version1 = _flow_version_with_data({\\\"nodes\\\": [_node({\\\"api_key\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"MY_KEY\\\"}})]})\\n        version2 = _flow_version_with_data({\\\"nodes\\\": [_node({\\\"api_key\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"MY_KEY\\\"}})]})\\n\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv1: version1, fv2: version2},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"MY_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv1, fv2]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == [\\\"MY_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_fails_fast_for_missing_flow_versions(self):\\n        fv_id = uuid4()\\n\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"ANY_KEY\\\"]),\\n            ),\\n            pytest.raises(HTTPException, match=f\\\"Flow version {fv_id} not found\\\"),\\n        ):\\n            await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_fails_fast_for_non_dict_data(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(None)\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"ANY_KEY\\\"]),\\n            ),\\n            pytest.raises(\\n                HTTPException,\\n                match=(\\n                    f\\\"Flow version {fv_id} data must be a JSON object with a 'nodes' list containing node templates.\\\"\\n                ),\\n            ),\\n        ):\\n            await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_fails_fast_for_missing_nodes_list(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data({})\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"ANY_KEY\\\"]),\\n            ),\\n            pytest.raises(\\n                HTTPException,\\n                match=(\\n                    f\\\"Flow version {fv_id} data must be a JSON object with a 'nodes' list containing node templates.\\\"\\n                ),\\n            ),\\n        ):\\n            await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_fails_fast_for_non_list_nodes(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data({\\\"nodes\\\": {\\\"template\\\": {}}})\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"ANY_KEY\\\"]),\\n            ),\\n            pytest.raises(\\n                HTTPException,\\n                match=(\\n                    f\\\"Flow version {fv_id} data must be a JSON object with a 'nodes' list containing node templates.\\\"\\n                ),\\n            ),\\n        ):\\n            await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_rejects_empty_flow_version_ids(self):\\n        with pytest.raises(ValidationError):\\n            DetectVarsRequest(flow_version_ids=[])\\n\\n    @pytest.mark.asyncio\\n    async def test_deduplicates_flow_version_ids_in_request(self):\\n        flow_version_id = uuid4()\\n        request = DetectVarsRequest(flow_version_ids=[flow_version_id, flow_version_id])\\n        assert request.flow_version_ids == [flow_version_id]\\n\\n    @pytest.mark.asyncio\\n    async def test_rejects_more_than_50_flow_version_ids(self):\\n        with pytest.raises(ValidationError):\\n            DetectVarsRequest(flow_version_ids=[uuid4() for _ in range(51)])\\n\\n    @pytest.mark.asyncio\\n    async def test_strips_whitespace_from_detected_variable_name(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"api_key\\\": {\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"  MY_OPENAI_KEY  \\\",\\n                            }\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"MY_OPENAI_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == [\\\"MY_OPENAI_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_ignores_non_string_and_blank_variable_values(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"null_value\\\": {\\\"load_from_db\\\": True, \\\"value\\\": None},\\n                            \\\"int_value\\\": {\\\"load_from_db\\\": True, \\\"value\\\": 123},\\n                            \\\"blank_value\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"   \\\"},\\n                            \\\"valid_value\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"VALID_KEY\\\"},\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"VALID_KEY\\\"]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n        assert result.variables == [\\\"VALID_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_filters_out_non_existing_variable_names(self):\\n        fv_id = uuid4()\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"api_key\\\": {\\\"load_from_db\\\": True, \\\"value\\\": \\\"sk-live-secret\\\"},\\n                            \\\"other_key\\\": {\\\"password\\\": True},\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([]),\\n            ),\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=SimpleNamespace(id=uuid4()),\\n                provider_policy_attributes={},\\n            )\\n\\n        assert result.variables == []\\n\\n    @pytest.mark.asyncio\\n    async def test_passes_server_resolved_scope_to_provider_policy(self):\\n        fv_id = uuid4()\\n        current_user = SimpleNamespace(id=uuid4())\\n        provider_policy_attributes = {\\n            \\\"project_id\\\": uuid4(),\\n            \\\"workspace_id\\\": uuid4(),\\n        }\\n        version = _flow_version_with_data(\\n            {\\n                \\\"nodes\\\": [\\n                    _node(\\n                        {\\n                            \\\"api_key\\\": {\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"OPENAI_API_KEY\\\",\\n                            }\\n                        }\\n                    )\\n                ]\\n            }\\n        )\\n        policy = SimpleNamespace(allows=lambda _provider: True)\\n        with (\\n            patch(\\n                f\\\"{MODULE}.get_flow_version_entries_by_ids\\\",\\n                new_callable=AsyncMock,\\n                return_value={fv_id: version},\\n            ),\\n            patch(\\n                f\\\"{MODULE}.get_variable_service\\\",\\n                return_value=_variable_service_with_names([\\\"OPENAI_API_KEY\\\"]),\\n            ),\\n            patch(f\\\"{MODULE}._aresolve_policy\\\", new_callable=AsyncMock, return_value=policy) as resolve_policy,\\n        ):\\n            result = await detect_env_vars(\\n                payload=DetectVarsRequest(flow_version_ids=[fv_id]),\\n                session=AsyncMock(),\\n                current_user=current_user,\\n                provider_policy_attributes=provider_policy_attributes,\\n            )\\n\\n        assert result.variables == [\\\"OPENAI_API_KEY\\\"]\\n        resolve_policy.assert_awaited_once_with(\\n            current_user,\\n            ModelProviderPolicyPurpose.CONFIGURE,\\n            provider_policy_attributes,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_end_user_scoping_http.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa290c2a6895ee6099c930fd680e4dc7f63bc5bec90c04b52d88b164af594d74\",\"content\":\"\\\"\\\"\\\"HTTP integration: the v1 ``/run`` endpoint scopes the session to the end-user.\\n\\nDrives the real FastAPI stack (api-key auth -> ``simple_run_flow`` -> ``run_graph_internal``)\\nwith the serving feature enabled, asserting the returned ``session_id`` reflects the\\nend-user scoping threaded through ``simple_run_flow``'s ``http_request``. This proves the\\ntrusted header actually reaches the run over HTTP, complementing the lfx unit tests for\\n``resolve_serving_scope`` (which cover the decision in isolation).\\n\\\"\\\"\\\"\\n\\nfrom uuid import uuid4\\n\\nfrom fastapi import status\\n\\nHEADER = \\\"X-End-User-Id\\\"\\n\\n\\ndef _enable_serving(monkeypatch, *, required: bool = False) -> None:\\n    \\\"\\\"\\\"Turn the serving end-user feature on for one test by mutating live settings.\\n\\n    ``resolve_serving_scope`` reads these off ``get_settings_service().settings`` at call\\n    time, so patching that singleton's attributes (restored by monkeypatch) enables the\\n    feature for the request without rebuilding the app.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"serving_end_user_header\\\", HEADER)\\n    monkeypatch.setattr(settings, \\\"serving_trust_proxy_headers\\\", True)\\n    monkeypatch.setattr(settings, \\\"serving_end_user_required\\\", required)\\n\\n\\nasync def _run(client, flow_id, api_key, *, session_id=None, end_user=None):\\n    headers = {\\\"x-api-key\\\": api_key}\\n    if end_user is not None:\\n        headers[HEADER] = end_user\\n    payload: dict = {\\\"input_value\\\": \\\"hi\\\"}\\n    if session_id is not None:\\n        payload[\\\"session_id\\\"] = session_id\\n    return await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n\\n\\nasync def test_identified_run_scopes_returned_session(client, simple_api_test, created_api_key, monkeypatch):\\n    _enable_serving(monkeypatch)\\n    resp = await _run(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, session_id=\\\"chat-1\\\", end_user=\\\"alice\\\")\\n    assert resp.status_code == status.HTTP_200_OK, resp.text\\n    # The run executed under the merged key, so the echoed session_id proves the header\\n    # reached run_graph_internal through simple_run_flow.\\n    assert resp.json()[\\\"session_id\\\"] == \\\"alice::chat-1\\\"\\n\\n\\nasync def test_two_end_users_same_session_are_isolated(client, simple_api_test, created_api_key, monkeypatch):\\n    _enable_serving(monkeypatch)\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    a = await _run(client, flow_id, created_api_key.api_key, session_id=\\\"shared\\\", end_user=\\\"alice\\\")\\n    b = await _run(client, flow_id, created_api_key.api_key, session_id=\\\"shared\\\", end_user=\\\"bob\\\")\\n    assert a.status_code == status.HTTP_200_OK, a.text\\n    assert b.status_code == status.HTTP_200_OK, b.text\\n    # Same client-supplied session id, different end users => distinct scopes.\\n    assert a.json()[\\\"session_id\\\"] == \\\"alice::shared\\\"\\n    assert b.json()[\\\"session_id\\\"] == \\\"bob::shared\\\"\\n\\n\\nasync def test_anonymous_run_gets_reserved_scope(client, simple_api_test, created_api_key, monkeypatch):\\n    _enable_serving(monkeypatch)\\n    # Feature on but no identity header: the run is moved into the reserved anon::\\n    # namespace and must not land under the client-supplied session id.\\n    resp = await _run(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, session_id=\\\"chat-1\\\")\\n    assert resp.status_code == status.HTTP_200_OK, resp.text\\n    session_id = resp.json()[\\\"session_id\\\"]\\n    assert session_id.startswith(\\\"anon::\\\")\\n    assert \\\"chat-1\\\" not in session_id\\n\\n\\nasync def test_feature_off_leaves_session_unchanged(client, simple_api_test, created_api_key):\\n    # Default settings (no header configured): even a present header is ignored, so v1\\n    # /run is byte-for-byte its pre-feature self.\\n    resp = await _run(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, session_id=\\\"chat-1\\\", end_user=\\\"alice\\\")\\n    assert resp.status_code == status.HTTP_200_OK, resp.text\\n    assert resp.json()[\\\"session_id\\\"] == \\\"chat-1\\\"\\n\\n\\nasync def test_required_but_absent_is_rejected(client, simple_api_test, created_api_key, monkeypatch):\\n    _enable_serving(monkeypatch, required=True)\\n    resp = await _run(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, session_id=\\\"chat-1\\\")  # no header\\n    assert resp.status_code == status.HTTP_401_UNAUTHORIZED, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"END_USER_IDENTITY_REQUIRED\\\"\\n\\n\\nasync def _run_stream(client, flow_id, api_key, *, end_user=None):\\n    headers = {\\\"x-api-key\\\": api_key}\\n    if end_user is not None:\\n        headers[HEADER] = end_user\\n    return await client.post(f\\\"/api/v1/run/{flow_id}?stream=true\\\", headers=headers, json={\\\"input_value\\\": \\\"hi\\\"})\\n\\n\\nasync def _responses(client, flow_id, api_key, *, stream=False, end_user=None):\\n    headers = {\\\"x-api-key\\\": api_key}\\n    if end_user is not None:\\n        headers[HEADER] = end_user\\n    body = {\\\"model\\\": flow_id, \\\"input\\\": \\\"hi\\\", \\\"stream\\\": stream}\\n    return await client.post(\\\"/api/v1/responses\\\", headers=headers, json=body)\\n\\n\\nasync def test_required_but_absent_rejected_on_streaming_run(client, simple_api_test, created_api_key, monkeypatch):\\n    # BUG-01: the stream branch returns a StreamingResponse (200 headers) before simple_run_flow\\n    # runs, so the 401 must come from a synchronous pre-check, not leak as an in-stream event.\\n    _enable_serving(monkeypatch, required=True)\\n    resp = await _run_stream(client, simple_api_test[\\\"id\\\"], created_api_key.api_key)  # no header\\n    assert resp.status_code == status.HTTP_401_UNAUTHORIZED, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"END_USER_IDENTITY_REQUIRED\\\"\\n\\n\\nasync def test_required_but_absent_rejected_on_responses(client, simple_api_test, created_api_key, monkeypatch):\\n    # BUG-01: create_response's blanket ``except Exception`` must not convert the 401 into an\\n    # OpenAIErrorResponse returned at the route's default 200.\\n    _enable_serving(monkeypatch, required=True)\\n    resp = await _responses(client, simple_api_test[\\\"id\\\"], created_api_key.api_key)  # no header, sync\\n    assert resp.status_code == status.HTTP_401_UNAUTHORIZED, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"END_USER_IDENTITY_REQUIRED\\\"\\n\\n\\nasync def test_required_but_absent_rejected_on_streaming_responses(\\n    client, simple_api_test, created_api_key, monkeypatch\\n):\\n    _enable_serving(monkeypatch, required=True)\\n    resp = await _responses(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, stream=True)  # no header\\n    assert resp.status_code == status.HTTP_401_UNAUTHORIZED, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"END_USER_IDENTITY_REQUIRED\\\"\\n\\n\\nasync def test_streaming_run_with_identity_is_not_rejected(client, simple_api_test, created_api_key, monkeypatch):\\n    # Feature on + identity present: the pre-check is a no-op and the stream proceeds (BC).\\n    _enable_serving(monkeypatch, required=True)\\n    resp = await _run_stream(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, end_user=\\\"alice\\\")\\n    assert resp.status_code == status.HTTP_200_OK, resp.text\\n\\n\\nasync def test_identified_run_stamps_message_user_id_over_http(\\n    client, simple_api_test, created_api_key, active_user, monkeypatch\\n):\\n    \\\"\\\"\\\"Full v1 chain: the header lands on message.user_id as the end user, not the SID.\\n\\n    Proves header -> simple_run_flow -> graph.end_user_id -> _store_message -> the\\n    UUID-typed message.user_id column, and that the read predicate agrees (P2's\\n    write==read contract) over the real /run stack.\\n    \\\"\\\"\\\"\\n    from langflow.memory import aget_messages\\n\\n    _enable_serving(monkeypatch)\\n    uid = uuid4()  # a UUID-shaped end-user id is stamped directly\\n    resp = await _run(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, session_id=\\\"chat-1\\\", end_user=str(uid))\\n    assert resp.status_code == status.HTTP_200_OK, resp.text\\n    scoped_session = resp.json()[\\\"session_id\\\"]\\n    assert scoped_session == f\\\"{uid}::chat-1\\\"\\n\\n    # Stored under the end user...\\n    assert len(await aget_messages(session_id=scoped_session, user_id=uid)) >= 1\\n    # ...and NOT under the service account (the api-key owner = SID).\\n    assert await aget_messages(session_id=scoped_session, user_id=active_user.id) == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_endpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c69ff566f2c6e11229cb2877b793e1e881667afd507488cc99810f3a0748f8c9\",\"content\":\"import asyncio\\nimport hashlib\\nimport inspect\\nfrom types import SimpleNamespace\\nfrom typing import Any\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom anyio import Path\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.api.v1.schemas import CustomComponentRequest, SimplifiedAPIRequest, UpdateCustomComponentRequest\\nfrom lfx.components.models_and_agents.agent import AgentComponent\\nfrom lfx.custom.utils import build_custom_component_template\\nfrom lfx.services.catalog_policy.base import CatalogPolicySnapshot\\n\\n\\nasync def test_get_version(client: AsyncClient):\\n    response = await client.get(\\\"api/v1/version\\\")\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert isinstance(result, dict), \\\"The result must be a dictionary\\\"\\n    assert \\\"version\\\" in result, \\\"The dictionary must contain a key called 'version'\\\"\\n    assert \\\"main_version\\\" in result, \\\"The dictionary must contain a key called 'main_version'\\\"\\n    assert \\\"package\\\" in result, \\\"The dictionary must contain a key called 'package'\\\"\\n\\n\\nasync def test_get_config_basic(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test basic authenticated /config endpoint returns expected structure.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert isinstance(result, dict), \\\"The result must be a dictionary\\\"\\n    assert \\\"frontend_timeout\\\" in result, \\\"The dictionary must contain a key called 'frontend_timeout'\\\"\\n    assert \\\"auto_saving\\\" in result, \\\"The dictionary must contain a key called 'auto_saving'\\\"\\n    assert \\\"health_check_max_retries\\\" in result, \\\"The dictionary must contain a 'health_check_max_retries' key\\\"\\n    assert \\\"max_file_size_upload\\\" in result, \\\"The dictionary must contain a key called 'max_file_size_upload'\\\"\\n\\n\\nasync def test_get_config_mirrors_assistant_message_length(client: AsyncClient, logged_in_headers: dict, monkeypatch):\\n    \\\"\\\"\\\"The Assistant composer reads its cap from /config, so the setting must be mirrored there.\\n\\n    Without this the UI falls back to a local constant, which is how a 500-character UI cap\\n    ended up silently truncating prompts the 2000-character API would have accepted.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"assistant_max_message_length\\\", 6000)\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert response.json()[\\\"assistant_max_message_length\\\"] == 6000\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"project_id\\\", \\\"workspace_id\\\"),\\n    [(uuid4(), uuid4()), (None, None)],\\n)\\nasync def test_simple_run_flow_binds_trusted_required_provider_scope(\\n    monkeypatch,\\n    project_id,\\n    workspace_id,\\n):\\n    from langflow.api.v1 import endpoints\\n\\n    captured = []\\n    token = object()\\n\\n    def _capture_context(*, user_id, attributes=None):\\n        captured.append((user_id, attributes))\\n        return token\\n\\n    monkeypatch.setattr(endpoints, \\\"set_current_model_provider_policy_context\\\", _capture_context)\\n    monkeypatch.setattr(endpoints, \\\"reset_current_model_provider_policy_context\\\", lambda _token: None)\\n    user = SimpleNamespace(id=uuid4(), is_superuser=False)\\n    flow = SimpleNamespace(\\n        id=uuid4(),\\n        folder_id=project_id,\\n        workspace_id=workspace_id,\\n        data=None,\\n    )\\n\\n    with pytest.raises(ValueError, match=\\\"has no data\\\"):\\n        await endpoints.simple_run_flow(flow, SimplifiedAPIRequest(), api_key_user=user)\\n\\n    expected_attributes = {\\n        \\\"is_superuser\\\": False,\\n        \\\"provider_scope_required\\\": True,\\n    }\\n    if project_id is not None:\\n        expected_attributes[\\\"project_id\\\"] = project_id\\n    if workspace_id is not None:\\n        expected_attributes[\\\"workspace_id\\\"] = workspace_id\\n    assert captured == [(user.id, expected_attributes)]\\n\\n\\nasync def test_build_driver_rebinds_scope_for_reused_graph_execution(monkeypatch):\\n    \\\"\\\"\\\"A warm/session graph never inherits the provider scope from an earlier run.\\\"\\\"\\\"\\n    from langflow.api import build\\n    from lfx.services.model_provider_policy import current_model_provider_policy_context\\n\\n    observed = []\\n\\n    async def _reuse_graph(**_kwargs):\\n        observed.append(current_model_provider_policy_context())\\n\\n    monkeypatch.setattr(build, \\\"_generate_flow_events\\\", _reuse_graph)\\n    user = SimpleNamespace(id=uuid4(), is_superuser=False)\\n    first_flow = SimpleNamespace(folder_id=uuid4(), workspace_id=uuid4())\\n    second_flow = SimpleNamespace(folder_id=uuid4(), workspace_id=uuid4())\\n\\n    await build.generate_flow_events(provider_policy_flow=first_flow, current_user=user)\\n    await build.generate_flow_events(provider_policy_flow=second_flow, current_user=user)\\n\\n    assert [context.user_id for context in observed] == [user.id, user.id]\\n    assert [context.attributes for context in observed] == [\\n        {\\n            \\\"is_superuser\\\": False,\\n            \\\"project_id\\\": first_flow.folder_id,\\n            \\\"workspace_id\\\": first_flow.workspace_id,\\n            \\\"provider_scope_required\\\": True,\\n        },\\n        {\\n            \\\"is_superuser\\\": False,\\n            \\\"project_id\\\": second_flow.folder_id,\\n            \\\"workspace_id\\\": second_flow.workspace_id,\\n            \\\"provider_scope_required\\\": True,\\n        },\\n    ]\\n\\n\\nasync def test_build_driver_marks_missing_provider_scope_as_required(monkeypatch):\\n    \\\"\\\"\\\"An internal caller that omits its stored flow cannot fall back to global policy.\\\"\\\"\\\"\\n    from langflow.api import build\\n    from lfx.services.model_provider_policy import current_model_provider_policy_context\\n\\n    observed = []\\n\\n    async def _capture_context(**_kwargs):\\n        observed.append(current_model_provider_policy_context())\\n\\n    monkeypatch.setattr(build, \\\"_generate_flow_events\\\", _capture_context)\\n    user = SimpleNamespace(id=uuid4(), is_superuser=True)\\n\\n    await build.generate_flow_events(current_user=user)\\n\\n    assert len(observed) == 1\\n    assert observed[0].user_id == user.id\\n    assert observed[0].attributes == {\\n        \\\"is_superuser\\\": True,\\n        \\\"provider_scope_required\\\": True,\\n    }\\n\\n\\n@pytest.mark.parametrize(\\\"path\\\", [\\\"api/v1/custom_component\\\", \\\"api/v1/custom_component/update\\\"])\\nasync def test_catalog_blocks_known_template_before_custom_component_build(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n    path: str,\\n):\\n    \\\"\\\"\\\"A blocked built-in cannot be reintroduced through either custom-component path.\\\"\\\"\\\"\\n    agent_component_file = await asyncio.to_thread(inspect.getsourcefile, AgentComponent)\\n    code = await Path(agent_component_file).read_text(encoding=\\\"utf-8\\\")\\n    code_hash = hashlib.sha256(code.encode()).hexdigest()[:12]\\n    snapshot = CatalogPolicySnapshot(blocked_component_keys={\\\"Agent\\\"})\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=snapshot),\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.utils.flow_validation.get_component_hash_lookups_for_validation\\\",\\n        lambda: {\\\"Agent\\\": {code_hash}},\\n    )\\n\\n    def fail_if_built(*_args, **_kwargs):\\n        msg = \\\"catalog policy must deny known blocked source before component build\\\"\\n        raise AssertionError(msg)\\n\\n    monkeypatch.setattr(\\\"langflow.api.v1.endpoints.build_custom_component_template\\\", fail_if_built)\\n    if path.endswith(\\\"/update\\\"):\\n        request = UpdateCustomComponentRequest(\\n            code=code,\\n            frontend_node={\\\"outputs\\\": []},\\n            field=\\\"\\\",\\n            field_value=\\\"\\\",\\n            template={},\\n        )\\n    else:\\n        request = CustomComponentRequest(code=code)\\n\\n    response = await client.post(path, json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN\\n    assert \\\"Agent\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.parametrize(\\\"path\\\", [\\\"api/v1/custom_component\\\", \\\"api/v1/custom_component/update\\\"])\\nasync def test_catalog_blocks_resolved_custom_component_type(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n    path: str,\\n):\\n    \\\"\\\"\\\"A modified custom component cannot assume an exact blocked runtime type.\\\"\\\"\\\"\\n    code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\nfrom lfx.template.field.base import Output\\n\\nclass CatalogLookalikeComponent(Component):\\n    name = \\\"Agent\\\"\\n    display_name = \\\"Catalog Lookalike\\\"\\n    outputs = [Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_result\\\")]\\n\\n    def get_result(self) -> str:\\n        return \\\"blocked\\\"\\n\\\"\\\"\\\"\\n    snapshot = CatalogPolicySnapshot(blocked_component_keys={\\\"Agent\\\"})\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=snapshot),\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.utils.flow_validation.get_component_hash_lookups_for_validation\\\",\\n        lambda: {\\\"Agent\\\": {\\\"different-template-hash\\\"}},\\n    )\\n\\n    if path.endswith(\\\"/update\\\"):\\n        request = UpdateCustomComponentRequest(\\n            code=code,\\n            frontend_node={\\\"outputs\\\": []},\\n            field=\\\"\\\",\\n            field_value=\\\"\\\",\\n            template={},\\n        )\\n    else:\\n        request = CustomComponentRequest(code=code)\\n\\n    response = await client.post(path, json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN\\n    assert \\\"Agent\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nasync def test_update_component_outputs(client: AsyncClient, logged_in_headers: dict):\\n    path = Path(__file__).parent.parent.parent.parent / \\\"data\\\" / \\\"dynamic_output_component.py\\\"\\n\\n    code = await path.read_text(encoding=\\\"utf-8\\\")\\n    frontend_node: dict[str, Any] = {\\\"outputs\\\": []}\\n    request = UpdateCustomComponentRequest(\\n        code=code,\\n        frontend_node=frontend_node,\\n        field=\\\"show_output\\\",\\n        field_value=True,\\n        template={},\\n    )\\n    response = await client.post(\\\"api/v1/custom_component/update\\\", json=request.model_dump(), headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    output_names = [output[\\\"name\\\"] for output in result[\\\"outputs\\\"]]\\n    assert \\\"tool_output\\\" in output_names\\n\\n\\nasync def test_update_component_model_name_options(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that model options are updated when the model field changes.\\\"\\\"\\\"\\n    component = AgentComponent()\\n    component_node, _cc_instance = build_custom_component_template(\\n        component,\\n    )\\n\\n    # Initial template - check that model field exists and has options\\n    template = component_node[\\\"template\\\"]\\n    assert \\\"model\\\" in template, f\\\"model field not found. Available fields: {list(template.keys())}\\\"\\n\\n    # load the code from the file at lfx.components.models_and_agents.agent.py asynchronously\\n    # we are at str/backend/tests/unit/api/v1/test_endpoints.py\\n    # find the file by using the class AgentComponent\\n    agent_component_file = await asyncio.to_thread(inspect.getsourcefile, AgentComponent)\\n    code = await Path(agent_component_file).read_text(encoding=\\\"utf-8\\\")\\n\\n    # Create the request to update the component - change to a different provider's model\\n    # Select a model from a different provider to test that options update\\n    request = UpdateCustomComponentRequest(\\n        code=code,\\n        frontend_node=component_node,\\n        field=\\\"model\\\",\\n        field_value=[{\\\"provider\\\": \\\"Anthropic\\\", \\\"name\\\": \\\"claude-3-opus-20240229\\\"}],  # Change provider\\n        template=template,\\n    )\\n\\n    # Make the request to update the component\\n    response = await client.post(\\\"api/v1/custom_component/update\\\", json=request.model_dump(), headers=logged_in_headers)\\n    result = response.json()\\n\\n    # Verify the response\\n    assert response.status_code == status.HTTP_200_OK, f\\\"Response: {response.json()}\\\"\\n    assert \\\"template\\\" in result\\n    assert \\\"model\\\" in result[\\\"template\\\"], (\\n        f\\\"model field not in result. Available fields: {list(result['template'].keys())}\\\"\\n    )\\n    assert isinstance(result[\\\"template\\\"][\\\"model\\\"].get(\\\"options\\\", []), list)\\n    # Model options should be present (may be same or different depending on implementation)\\n    updated_model_options = result[\\\"template\\\"][\\\"model\\\"].get(\\\"options\\\", [])\\n    # Just verify that options exist after update\\n    assert isinstance(updated_model_options, list), (\\n        f\\\"Model options should be a list, got: {type(updated_model_options)}\\\"\\n    )\\n\\n\\nasync def test_custom_component_update_admin_only_allows_known_template_refresh(\\n    client: AsyncClient, logged_in_headers: dict, monkeypatch\\n):\\n    \\\"\\\"\\\"Non-admin users can refresh known server templates in admin-only mode.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    component = AgentComponent()\\n    component_node, _cc_instance = build_custom_component_template(component)\\n    template = component_node[\\\"template\\\"]\\n\\n    agent_component_file = await asyncio.to_thread(inspect.getsourcefile, AgentComponent)\\n    code = await Path(agent_component_file).read_text(encoding=\\\"utf-8\\\")\\n\\n    request = UpdateCustomComponentRequest(\\n        code=code,\\n        frontend_node=component_node,\\n        field=\\\"model\\\",\\n        field_value=[{\\\"provider\\\": \\\"Anthropic\\\", \\\"name\\\": \\\"claude-3-opus-20240229\\\"}],\\n        template=template,\\n    )\\n    response = await client.post(\\\"api/v1/custom_component/update\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n\\n\\nasync def test_custom_component_update_admin_only_blocks_unknown_custom_code(\\n    client: AsyncClient, logged_in_headers: dict, monkeypatch\\n):\\n    \\\"\\\"\\\"Non-admin users cannot edit truly custom code in admin-only mode.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    component_code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\n\\nclass TestMetadataComponent(Component):\\n    display_name = \\\"Test Metadata Component\\\"\\n    description = \\\"Test component for metadata\\\"\\n\\n    def run(self) -> str:\\n        return \\\"ok\\\"\\n\\\"\\\"\\\"\\n\\n    request = UpdateCustomComponentRequest(\\n        code=component_code,\\n        frontend_node={\\\"outputs\\\": []},\\n        field=\\\"tool_mode\\\",\\n        field_value=False,\\n        template={},\\n    )\\n    response = await client.post(\\\"api/v1/custom_component/update\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN\\n    assert \\\"restricted to administrators\\\" in response.json().get(\\\"detail\\\", \\\"\\\")\\n\\n\\nasync def test_custom_component_create_admin_only_allows_known_template_refresh(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"Non-admin users can create/refresh known server templates in admin-only mode.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    agent_component_file = await asyncio.to_thread(inspect.getsourcefile, AgentComponent)\\n    code = await Path(agent_component_file).read_text(encoding=\\\"utf-8\\\")\\n\\n    request = CustomComponentRequest(code=code)\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n\\n\\nasync def test_custom_component_create_admin_only_blocks_unknown_custom_code(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"Non-admin users cannot create truly custom code in admin-only mode.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    component_code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\n\\nclass TestMetadataComponent(Component):\\n    display_name = \\\"Test Metadata Component\\\"\\n    description = \\\"Test component for metadata\\\"\\n\\n    def run(self) -> str:\\n        return \\\"ok\\\"\\n\\\"\\\"\\\"\\n\\n    request = CustomComponentRequest(code=component_code)\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN\\n    assert \\\"restricted to administrators\\\" in response.json().get(\\\"detail\\\", \\\"\\\")\\n\\n\\nasync def test_custom_component_create_admin_only_allows_superuser(\\n    client: AsyncClient,\\n    logged_in_headers_super_user: dict,\\n    monkeypatch,\\n):\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\n\\nclass SuperUserMetadataComponent(Component):\\n    display_name = \\\"SuperUser Metadata Component\\\"\\n    description = \\\"Test component for superuser bypass\\\"\\n\\n    def run(self) -> str:\\n        return \\\"ok\\\"\\n\\\"\\\"\\\"\\n\\n    request = CustomComponentRequest(code=code)\\n    response = await client.post(\\n        \\\"api/v1/custom_component\\\",\\n        json=request.model_dump(),\\n        headers=logged_in_headers_super_user,\\n    )\\n\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n    assert \\\"data\\\" in response.json()\\n\\n\\nasync def test_custom_component_update_admin_only_allows_superuser(\\n    client: AsyncClient,\\n    logged_in_headers_super_user: dict,\\n    active_super_user,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n    from langflow.services.deps import get_settings_service\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.services.model_provider_policy import current_model_provider_policy_context\\n\\n    settings_service = get_settings_service()\\n    admin_only_enabled = True\\n    monkeypatch.setitem(settings_service.settings.__dict__, \\\"custom_component_admin_only\\\", admin_only_enabled)\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", True)\\n\\n    bound_contexts = []\\n    reset_tokens = []\\n    policy_contexts = []\\n    original_set_context = endpoints.set_current_model_provider_policy_context\\n    original_reset_context = endpoints.reset_current_model_provider_policy_context\\n    original_require_policy = Component.arequire_model_provider_policy\\n\\n    def capture_set_context(*, user_id, attributes=None):\\n        bound_contexts.append((user_id, attributes))\\n        return original_set_context(user_id=user_id, attributes=attributes)\\n\\n    def capture_reset_context(token):\\n        reset_tokens.append(token)\\n        original_reset_context(token)\\n\\n    async def capture_require_policy(self, purpose, **kwargs):\\n        policy_contexts.append(current_model_provider_policy_context())\\n        return await original_require_policy(self, purpose, **kwargs)\\n\\n    monkeypatch.setattr(endpoints, \\\"set_current_model_provider_policy_context\\\", capture_set_context)\\n    monkeypatch.setattr(endpoints, \\\"reset_current_model_provider_policy_context\\\", capture_reset_context)\\n    monkeypatch.setattr(Component, \\\"arequire_model_provider_policy\\\", capture_require_policy)\\n\\n    component_code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\n\\nclass SuperUserUpdateMetadataComponent(Component):\\n    display_name = \\\"SuperUser Update Metadata Component\\\"\\n    description = \\\"Test component update for superuser bypass\\\"\\n\\n    def run(self) -> str:\\n        return \\\"ok\\\"\\n\\\"\\\"\\\"\\n\\n    request = UpdateCustomComponentRequest(\\n        code=component_code,\\n        frontend_node={\\\"outputs\\\": []},\\n        field=\\\"tool_mode\\\",\\n        field_value=False,\\n        template={},\\n    )\\n    response = await client.post(\\n        \\\"api/v1/custom_component/update\\\",\\n        json=request.model_dump(),\\n        headers=logged_in_headers_super_user,\\n    )\\n\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n    assert bound_contexts == [(active_super_user.id, {\\\"is_superuser\\\": True})]\\n    assert len(reset_tokens) == 1\\n    assert policy_contexts\\n    assert policy_contexts[0] is not None\\n    assert policy_contexts[0].user_id == active_super_user.id\\n    assert policy_contexts[0].attributes[\\\"is_superuser\\\"] is True\\n\\n\\nasync def test_custom_component_create_denies_provider_before_dynamic_update_hooks(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    provider_denial = ModelProviderPolicyError(\\\"openai\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n    component_instance = Component(_code=\\\"\\\")\\n    require_policy = AsyncMock(side_effect=provider_denial)\\n    update_frontend_node = AsyncMock(return_value={\\\"tool_mode\\\": False})\\n    run_update_outputs = AsyncMock()\\n    monkeypatch.setattr(component_instance, \\\"arequire_model_provider_policy\\\", require_policy)\\n    monkeypatch.setattr(component_instance, \\\"update_frontend_node\\\", update_frontend_node)\\n    monkeypatch.setattr(component_instance, \\\"run_and_validate_update_outputs\\\", run_update_outputs)\\n    monkeypatch.setattr(endpoints, \\\"get_current_external_access_context\\\", lambda: None)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace()),\\n    )\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=object()),\\n    )\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"resolve_component_code_for_action\\\",\\n        lambda code, **_kwargs: code,\\n    )\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"build_custom_component_template\\\",\\n        lambda *_args, **_kwargs: ({\\\"tool_mode\\\": False}, component_instance),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"get_instance_name\\\", lambda _component: \\\"DeniedModel\\\")\\n    monkeypatch.setattr(endpoints, \\\"enforce_catalog_policy_for_component_type\\\", lambda *_args, **_kwargs: None)\\n\\n    request = CustomComponentRequest(\\n        code=\\\"class DeniedModel: pass\\\",\\n        frontend_node={\\n            \\\"template\\\": {\\n                \\\"model\\\": {\\n                    \\\"value\\\": [{\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"gpt-test\\\"}],\\n                    \\\"_input_type\\\": \\\"ModelInput\\\",\\n                }\\n            }\\n        },\\n    )\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND\\n    assert response.json() == {\\\"detail\\\": \\\"Model provider not found\\\"}\\n    assert require_policy.await_args.args == (ModelProviderPolicyPurpose.CONFIGURE,)\\n    assert require_policy.await_args.kwargs[\\\"parameters\\\"][\\\"model\\\"][0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n    update_frontend_node.assert_not_awaited()\\n    run_update_outputs.assert_not_awaited()\\n\\n\\nasync def test_custom_component_update_denies_selected_provider_before_secret_hydration(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n    component_instance = Component(_code=\\\"\\\")\\n    denial = ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n    require_policy = AsyncMock(side_effect=denial)\\n    hydrate = AsyncMock(side_effect=AssertionError(\\\"secret hydration reached after provider denial\\\"))\\n    monkeypatch.setattr(component_instance, \\\"arequire_model_provider_policy\\\", require_policy)\\n    monkeypatch.setattr(endpoints, \\\"update_params_with_load_from_db_fields\\\", hydrate)\\n    monkeypatch.setattr(endpoints, \\\"get_current_external_access_context\\\", lambda: None)\\n    monkeypatch.setattr(endpoints, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(endpoints, \\\"get_catalog_policy_service\\\", lambda: SimpleNamespace(snapshot=object()))\\n    monkeypatch.setattr(endpoints, \\\"resolve_component_code_for_action\\\", lambda code, **_kwargs: code)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"build_custom_component_template\\\",\\n        lambda *_args, **_kwargs: ({\\\"template\\\": {}, \\\"outputs\\\": []}, component_instance),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"get_instance_name\\\", lambda _component: \\\"SelectedModel\\\")\\n    monkeypatch.setattr(endpoints, \\\"enforce_catalog_policy_for_component_type\\\", lambda *_args, **_kwargs: None)\\n\\n    request = UpdateCustomComponentRequest(\\n        code=\\\"class SelectedModel: pass\\\",\\n        frontend_node={\\\"outputs\\\": []},\\n        field=\\\"model\\\",\\n        field_value=[{\\\"provider\\\": \\\"Anthropic\\\", \\\"model_name\\\": \\\"claude-test\\\"}],\\n        template={\\n            \\\"model\\\": {\\n                \\\"value\\\": [{\\\"provider\\\": \\\"Anthropic\\\", \\\"model_name\\\": \\\"claude-test\\\"}],\\n                \\\"_input_type\\\": \\\"ModelInput\\\",\\n            },\\n            \\\"api_key\\\": {\\n                \\\"value\\\": \\\"ANTHROPIC_API_KEY\\\",\\n                \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n                \\\"load_from_db\\\": True,\\n            },\\n        },\\n    )\\n    response = await client.post(\\n        \\\"api/v1/custom_component/update\\\",\\n        json=request.model_dump(),\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND\\n    assert response.json() == {\\\"detail\\\": \\\"Model provider not found\\\"}\\n    assert require_policy.await_args.args == (ModelProviderPolicyPurpose.CONFIGURE,)\\n    assert require_policy.await_args.kwargs[\\\"parameters\\\"][\\\"model\\\"][0][\\\"provider\\\"] == \\\"Anthropic\\\"\\n    hydrate.assert_not_awaited()\\n\\n\\nasync def test_custom_component_update_keeps_realtime_value_out_of_component_attributes(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    from unittest.mock import MagicMock\\n\\n    from langflow.api.v1 import endpoints\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\n\\n    component_instance = Component(_code=\\\"\\\")\\n    require_policy = AsyncMock()\\n    set_attributes = MagicMock()\\n    run_update_outputs = AsyncMock()\\n    monkeypatch.setattr(component_instance, \\\"arequire_model_provider_policy\\\", require_policy)\\n    monkeypatch.setattr(component_instance, \\\"set_attributes\\\", set_attributes)\\n    monkeypatch.setattr(component_instance, \\\"run_and_validate_update_outputs\\\", run_update_outputs)\\n    monkeypatch.setattr(endpoints, \\\"get_current_external_access_context\\\", lambda: None)\\n    monkeypatch.setattr(endpoints, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(endpoints, \\\"get_catalog_policy_service\\\", lambda: SimpleNamespace(snapshot=object()))\\n    monkeypatch.setattr(endpoints, \\\"resolve_component_code_for_action\\\", lambda code, **_kwargs: code)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"build_custom_component_template\\\",\\n        lambda *_args, **_kwargs: ({\\\"template\\\": {}, \\\"outputs\\\": []}, component_instance),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"get_instance_name\\\", lambda _component: \\\"SelectedModel\\\")\\n    monkeypatch.setattr(endpoints, \\\"enforce_catalog_policy_for_component_type\\\", lambda *_args, **_kwargs: None)\\n    monkeypatch.setattr(endpoints, \\\"update_component_build_config\\\", AsyncMock())\\n\\n    template_value = [{\\\"provider\\\": \\\"OpenAI\\\", \\\"model_name\\\": \\\"gpt-test\\\"}]\\n    realtime_value = [{\\\"provider\\\": \\\"Anthropic\\\", \\\"model_name\\\": \\\"claude-test\\\"}]\\n    request = UpdateCustomComponentRequest(\\n        code=\\\"class SelectedModel: pass\\\",\\n        frontend_node={\\\"outputs\\\": []},\\n        field=\\\"model\\\",\\n        field_value=realtime_value,\\n        template={\\n            \\\"model\\\": {\\n                \\\"value\\\": template_value,\\n                \\\"_input_type\\\": \\\"ModelInput\\\",\\n            }\\n        },\\n    )\\n\\n    response = await client.post(\\n        \\\"api/v1/custom_component/update\\\",\\n        json=request.model_dump(),\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert require_policy.await_args.args == (ModelProviderPolicyPurpose.CONFIGURE,)\\n    assert require_policy.await_args.kwargs[\\\"parameters\\\"][\\\"model\\\"] == realtime_value\\n    assert set_attributes.call_args.args[0][\\\"model\\\"] == template_value\\n\\n\\nasync def test_custom_component_endpoint_returns_metadata(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that the /custom_component endpoint returns metadata with module and code_hash.\\\"\\\"\\\"\\n    component_code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\nfrom lfx.inputs import MessageTextInput\\nfrom lfx.template.field.base import Output\\n\\nclass TestMetadataComponent(Component):\\n    display_name = \\\"Test Metadata Component\\\"\\n    description = \\\"Test component for metadata\\\"\\n\\n    inputs = [\\n        MessageTextInput(display_name=\\\"Input\\\", name=\\\"input_value\\\"),\\n    ]\\n    outputs = [\\n        Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"process_input\\\"),\\n    ]\\n\\n    def process_input(self) -> str:\\n        return f\\\"Processed: {self.input_value}\\\"\\n\\\"\\\"\\\"\\n\\n    request = CustomComponentRequest(code=component_code)\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert \\\"data\\\" in result\\n    assert \\\"type\\\" in result\\n\\n    # Verify metadata is present in the response\\n    frontend_node = result[\\\"data\\\"]\\n    assert \\\"metadata\\\" in frontend_node, \\\"Frontend node should contain metadata\\\"\\n\\n    # TODO: Temporarily skip metadata checks\\n    # metadata = frontend_node[\\\"metadata\\\"]\\n    # assert \\\"module\\\" in metadata, \\\"Metadata should contain module field\\\"\\n    # assert \\\"code_hash\\\" in metadata, \\\"Metadata should contain code_hash field\\\"\\n\\n    # Verify metadata values\\n    # assert isinstance(metadata[\\\"module\\\"], str), \\\"Module should be a string\\\"\\n    # expected_module = \\\"custom_components.test_metadata_component\\\"\\n    # assert metadata[\\\"module\\\"] == expected_module, \\\"Module should be auto-generated from display_name\\\"\\n\\n    # assert isinstance(metadata[\\\"code_hash\\\"], str), \\\"Code hash should be a string\\\"\\n    # assert len(metadata[\\\"code_hash\\\"]) == 12, \\\"Code hash should be 12 characters long\\\"\\n    # assert all(c in \\\"0123456789abcdef\\\" for c in metadata[\\\"code_hash\\\"]), \\\"Code hash should be hexadecimal\\\"\\n\\n\\nasync def test_custom_component_endpoint_metadata_consistency(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that the same component code produces consistent metadata.\\\"\\\"\\\"\\n    component_code = \\\"\\\"\\\"\\nfrom lfx.custom import Component\\nfrom lfx.template.field.base import Output\\n\\nclass ConsistencyTestComponent(Component):\\n    display_name = \\\"Consistency Test\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"get_result\\\"),\\n    ]\\n\\n    def get_result(self) -> str:\\n        return \\\"consistent result\\\"\\n\\\"\\\"\\\"\\n\\n    # Make two identical requests\\n    request = CustomComponentRequest(code=component_code)\\n\\n    response1 = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n    # result1 = response1.json()\\n\\n    response2 = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n    # result2 = response2.json()\\n\\n    # Both requests should succeed\\n    assert response1.status_code == status.HTTP_200_OK\\n    assert response2.status_code == status.HTTP_200_OK\\n    # TODO: Temporarily skip metadata checks\\n\\n    # Metadata should be identical\\n    # metadata1 = result1[\\\"data\\\"][\\\"metadata\\\"]\\n    # metadata2 = result2[\\\"data\\\"][\\\"metadata\\\"]\\n\\n    # assert metadata1[\\\"module\\\"] == metadata2[\\\"module\\\"], \\\"Module names should be consistent\\\"\\n    # assert metadata1[\\\"code_hash\\\"] == metadata2[\\\"code_hash\\\"], \\\"Code hashes should be consistent for identical code\\\"\\n\\n\\nasync def test_get_config_without_authentication_returns_public_config(client: AsyncClient):\\n    \\\"\\\"\\\"Test that /config returns public config when accessed without authentication.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\")\\n    assert response.status_code == status.HTTP_200_OK\\n\\n\\nasync def test_get_config_reports_catalog_governance_without_exposing_policy_contents(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"The public variant exposes only the derived governance indicator.\\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(enabled=True),\\n    )\\n\\n    public_response = await client.get(\\\"api/v1/config\\\")\\n    authenticated_response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n\\n    assert public_response.status_code == status.HTTP_200_OK\\n    assert authenticated_response.status_code == status.HTTP_200_OK\\n    for result in (public_response.json(), authenticated_response.json()):\\n        assert result[\\\"catalog_governance_enabled\\\"] is True\\n        assert \\\"blocked_component_keys\\\" not in result\\n        assert \\\"blocked_template_keys\\\" not in result\\n    # A policy service exposing no snapshot names nothing rather than guessing.\\n    assert authenticated_response.json()[\\\"blocked_component_types\\\"] == []\\n\\n\\ndef test_public_config_never_carries_blocked_component_identities():\\n    \\\"\\\"\\\"The anonymous response withholds the policy contents by construction.\\n\\n    Asserted on the schema rather than a response: the test client's\\n    unauthenticated request resolves a user under auto-login, so it cannot\\n    exercise the anonymous branch.\\n    \\\"\\\"\\\"\\n    from langflow.api.v1.schemas import ConfigResponse, PublicConfigResponse\\n\\n    assert \\\"blocked_component_types\\\" not in PublicConfigResponse.model_fields\\n    assert \\\"blocked_component_types\\\" in ConfigResponse.model_fields\\n\\n\\nasync def test_get_config_names_blocked_components_to_authenticated_callers(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"The editor cannot attribute a missing template without the identities.\\n\\n    ``catalog_governance_enabled`` says a policy exists somewhere; a node whose\\n    template is missing may instead be an uninstalled bundle, an imported flow\\n    or the caller's own component, so the editor needs the blocked identities\\n    to name a cause truthfully.\\n    \\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(\\n            enabled=True,\\n            snapshot=SimpleNamespace(\\n                blocked_component_keys=frozenset({\\\"ChatOutput\\\", \\\"Agent\\\"}),\\n                blocked_template_keys=frozenset({\\\"Simple Agent\\\"}),\\n            ),\\n        ),\\n    )\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    reported = response.json()[\\\"blocked_component_types\\\"]\\n    # The keys themselves, plus every alias a saved node could carry for them.\\n    assert {\\\"Agent\\\", \\\"ChatOutput\\\"} <= set(reported)\\n    # Template identities stay withheld: nothing in the editor consumes them.\\n    assert \\\"Simple Agent\\\" not in reported\\n    # An unrelated component contributes nothing.\\n    assert \\\"Prompt Template\\\" not in reported\\n\\n\\nasync def test_get_config_names_every_alias_of_a_blocked_component(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"A node saved under an alias must match the administrator's canonical key.\\n\\n    Alias resolution runs alias -> canonical only, so reporting just the\\n    blocked key and its canonical candidates leaves a node saved as ``Prompt``\\n    unmatched when ``Prompt Template`` is blocked -- and the palette exposes\\n    only ``Prompt Template``, so that is the key an administrator can find.\\n    Nine shipped starter flows save that component as ``Prompt``.\\n    \\\"\\\"\\\"\\n    identity_index = SimpleNamespace(\\n        canonical_keys=frozenset({\\\"Prompt Template\\\", \\\"ParserComponent\\\"}),\\n        aliases={\\n            \\\"Prompt\\\": frozenset({\\\"Prompt Template\\\"}),\\n            \\\"PromptComponent\\\": frozenset({\\\"Prompt Template\\\"}),\\n            \\\"parser\\\": frozenset({\\\"ParserComponent\\\"}),\\n        },\\n        resolve_many=lambda keys: frozenset(\\n            candidate\\n            for key in keys\\n            for candidate in (\\n                frozenset({key})\\n                if key in {\\\"Prompt Template\\\", \\\"ParserComponent\\\"}\\n                else {\\n                    \\\"Prompt\\\": frozenset({\\\"Prompt Template\\\"}),\\n                    \\\"PromptComponent\\\": frozenset({\\\"Prompt Template\\\"}),\\n                    \\\"parser\\\": frozenset({\\\"ParserComponent\\\"}),\\n                }.get(key, frozenset({key}))\\n            )\\n        ),\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.utils.flow_validation.get_component_identity_index_for_validation\\\",\\n        lambda: identity_index,\\n    )\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(\\n            enabled=True,\\n            snapshot=SimpleNamespace(\\n                blocked_component_keys=frozenset({\\\"Prompt Template\\\"}),\\n                blocked_template_keys=frozenset(),\\n            ),\\n        ),\\n    )\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    reported = response.json()[\\\"blocked_component_types\\\"]\\n    # The alias a saved node actually carries.\\n    assert \\\"Prompt\\\" in reported\\n    assert \\\"PromptComponent\\\" in reported\\n    assert \\\"Prompt Template\\\" in reported\\n    # An unrelated component's alias stays out of it.\\n    assert \\\"parser\\\" not in reported\\n\\n\\nasync def test_get_config_names_no_components_when_only_a_template_is_blocked(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"Governance is on, yet no component is blocked (LE-2226).\\n\\n    ``enabled`` is true when *either* blocklist is non-empty, so blocking one\\n    starter template used to be enough for the editor to brand every\\n    code-bearing node without a template \\\"disabled by an administrator\\\".\\n    \\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(\\n            enabled=True,\\n            snapshot=SimpleNamespace(\\n                blocked_component_keys=frozenset(),\\n                blocked_template_keys=frozenset({\\\"Simple Agent\\\"}),\\n            ),\\n        ),\\n    )\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert response.json()[\\\"catalog_governance_enabled\\\"] is True\\n    assert response.json()[\\\"blocked_component_types\\\"] == []\\n\\n\\nasync def test_get_config_fails_open_without_exposing_catalog_policy_errors(client: AsyncClient, monkeypatch):\\n    \\\"\\\"\\\"A broken custom policy accessor does not leak through public config.\\\"\\\"\\\"\\n\\n    class BrokenCatalogPolicy:\\n        @property\\n        def enabled(self) -> bool:\\n            msg = \\\"sensitive catalog backend detail\\\"\\n            raise RuntimeError(msg)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.endpoints.get_catalog_policy_service\\\",\\n        BrokenCatalogPolicy,\\n    )\\n\\n    response = await client.get(\\\"api/v1/config\\\")\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert response.json()[\\\"catalog_governance_enabled\\\"] is False\\n    assert \\\"sensitive catalog backend detail\\\" not in response.text\\n\\n\\nasync def test_get_config_unauthenticated_returns_expected_fields(client: AsyncClient):\\n    \\\"\\\"\\\"Test that unauthenticated /config response contains only public-safe fields.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\")\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert isinstance(result, dict), \\\"The result must be a dictionary\\\"\\n\\n    # Verify expected public fields are present\\n    assert \\\"max_file_size_upload\\\" in result, \\\"Response must contain 'max_file_size_upload'\\\"\\n    assert \\\"event_delivery\\\" in result, \\\"Response must contain 'event_delivery'\\\"\\n    assert \\\"feature_flags\\\" in result, \\\"Response must contain 'feature_flags'\\\"\\n    assert \\\"voice_mode_available\\\" in result, \\\"Response must contain 'voice_mode_available'\\\"\\n    assert \\\"frontend_timeout\\\" in result, \\\"Response must contain 'frontend_timeout'\\\"\\n\\n    # Verify type discriminator for public config\\n    assert \\\"type\\\" in result, \\\"Response must contain 'type' discriminator field\\\"\\n    assert result[\\\"type\\\"] == \\\"public\\\", \\\"Unauthenticated response must have type='public'\\\"\\n\\n\\nasync def test_get_config_unauthenticated_does_not_expose_sensitive_fields(client: AsyncClient):\\n    \\\"\\\"\\\"Test that unauthenticated /config response does not contain sensitive configuration fields.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\")\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n\\n    # Verify sensitive fields are NOT present\\n    sensitive_fields = [\\n        \\\"database_url\\\",\\n        \\\"secret_key\\\",\\n        \\\"auto_saving\\\",\\n        \\\"auto_saving_interval\\\",\\n        \\\"health_check_max_retries\\\",\\n        \\\"webhook_polling_interval\\\",\\n        \\\"serialization_max_items_length\\\",\\n        \\\"webhook_auth_enable\\\",\\n        \\\"default_folder_name\\\",\\n        \\\"hide_getting_started_progress\\\",\\n    ]\\n\\n    for field in sensitive_fields:\\n        assert field not in result, f\\\"Sensitive field '{field}' should not be exposed in unauthenticated config\\\"\\n\\n\\nasync def test_get_config_unauthenticated_returns_correct_field_types(client: AsyncClient):\\n    \\\"\\\"\\\"Test that unauthenticated /config response fields have correct types.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\")\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n\\n    # Verify field types\\n    assert isinstance(result[\\\"max_file_size_upload\\\"], int), \\\"max_file_size_upload must be an integer\\\"\\n    assert isinstance(result[\\\"frontend_timeout\\\"], int), \\\"frontend_timeout must be an integer\\\"\\n    assert isinstance(result[\\\"voice_mode_available\\\"], bool), \\\"voice_mode_available must be a boolean\\\"\\n    assert isinstance(result[\\\"feature_flags\\\"], dict), \\\"feature_flags must be an object\\\"\\n    assert result[\\\"feature_flags\\\"].get(\\\"wxo_deployments\\\") is False, \\\"wxo_deployments flag should default to false\\\"\\n    assert result[\\\"event_delivery\\\"] in [\\\"polling\\\", \\\"streaming\\\", \\\"direct\\\"], (\\n        \\\"event_delivery must be one of: polling, streaming, direct\\\"\\n    )\\n\\n\\nasync def test_get_config_returns_500_on_settings_error(client: AsyncClient, monkeypatch):\\n    \\\"\\\"\\\"Test that /config endpoint returns 500 when settings retrieval fails.\\\"\\\"\\\"\\n    error_message = \\\"Settings retrieval failed\\\"\\n\\n    def raise_settings_error():\\n        raise RuntimeError(error_message)\\n\\n    # Patch get_settings_service at the module level\\n    monkeypatch.setattr(\\\"langflow.api.v1.endpoints.get_settings_service\\\", raise_settings_error)\\n\\n    response = await client.get(\\\"api/v1/config\\\")\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_500_INTERNAL_SERVER_ERROR\\n    assert error_message in result[\\\"detail\\\"]\\n\\n\\nasync def test_get_config_authenticated_returns_full_config(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that authenticated /config returns full ConfigResponse with all settings.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert isinstance(result, dict), \\\"The result must be a dictionary\\\"\\n\\n    # Verify type discriminator for full config\\n    assert \\\"type\\\" in result, \\\"Response must contain 'type' discriminator field\\\"\\n    assert result[\\\"type\\\"] == \\\"full\\\", \\\"Authenticated response must have type='full'\\\"\\n\\n    # Verify full config fields are present (not just public fields)\\n    assert \\\"auto_saving\\\" in result, \\\"Authenticated response must contain 'auto_saving'\\\"\\n    assert \\\"auto_saving_interval\\\" in result, \\\"Authenticated response must contain 'auto_saving_interval'\\\"\\n    assert \\\"health_check_max_retries\\\" in result, \\\"Authenticated response must contain 'health_check_max_retries'\\\"\\n    assert \\\"feature_flags\\\" in result, \\\"Authenticated response must contain 'feature_flags'\\\"\\n    # The publish-as-agent UI reads this to explain, rather than 404, when A2A is off server-side.\\n    assert \\\"a2a_enabled\\\" in result, \\\"Authenticated response must expose the a2a server flag\\\"\\n    # The Assistant panel reads this to explain, rather than 404, when the experience is off.\\n    assert \\\"agentic_experience\\\" in result, \\\"Authenticated response must expose the agentic experience flag\\\"\\n\\n\\nasync def test_get_config_exposes_outdated_component_substitution_policy(\\n    client: AsyncClient, logged_in_headers: dict, monkeypatch\\n):\\n    \\\"\\\"\\\"Both editor modes need the server policy to decide whether drift blocks a run.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"substitute_outdated_component_code\\\", False)\\n\\n    for headers in ({}, logged_in_headers):\\n        response = await client.get(\\\"api/v1/config\\\", headers=headers)\\n\\n        assert response.status_code == status.HTTP_200_OK\\n        assert response.json()[\\\"substitute_outdated_component_code\\\"] is False\\n\\n\\nasync def test_get_config_embedded_mode_cascades_hide_flags(client: AsyncClient, logged_in_headers: dict, monkeypatch):\\n    \\\"\\\"\\\"Embedded mode should only force UI hide flags, not security lock flags.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"embedded_mode\\\", True)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_logout_button\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_new_project_button\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_new_flow_button\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_starter_projects\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_getting_started_progress\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"mcp_servers_locked\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"custom_component_admin_only\\\", False)\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert result[\\\"embedded_mode\\\"] is True\\n    assert result[\\\"hide_logout_button\\\"] is True\\n    assert result[\\\"hide_new_project_button\\\"] is True\\n    assert result[\\\"hide_new_flow_button\\\"] is True\\n    assert result[\\\"hide_starter_projects\\\"] is True\\n    # This flag is currently a direct passthrough (not part of embedded_mode cascade).\\n    assert result[\\\"hide_getting_started_progress\\\"] is False\\n    # Security lock flags are explicit opt-ins and do not cascade from embedded_mode.\\n    assert result[\\\"mcp_servers_locked\\\"] is False\\n    assert result[\\\"custom_component_admin_only\\\"] is False\\n\\n\\nasync def test_get_config_embedded_mode_false_keeps_individual_hide_flags(\\n    client: AsyncClient, logged_in_headers: dict, monkeypatch\\n):\\n    \\\"\\\"\\\"When embedded mode is disabled, individual hide flags should retain explicit values.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"embedded_mode\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_logout_button\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_new_project_button\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_new_flow_button\\\", True)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_starter_projects\\\", False)\\n    monkeypatch.setattr(settings_service.settings, \\\"hide_getting_started_progress\\\", True)\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert result[\\\"embedded_mode\\\"] is False\\n    assert result[\\\"hide_logout_button\\\"] is False\\n    assert result[\\\"hide_new_project_button\\\"] is False\\n    assert result[\\\"hide_new_flow_button\\\"] is True\\n    assert result[\\\"hide_starter_projects\\\"] is False\\n    assert result[\\\"hide_getting_started_progress\\\"] is True\\n\\n\\nasync def test_get_config_returns_mcp_and_admin_only_flags(client: AsyncClient, logged_in_headers: dict, monkeypatch):\\n    \\\"\\\"\\\"Config response should expose lock/admin feature flags from settings.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"mcp_servers_locked\\\", True)\\n    monkeypatch.setattr(settings_service.settings, \\\"custom_component_admin_only\\\", True)\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert result[\\\"mcp_servers_locked\\\"] is True\\n    assert result[\\\"custom_component_admin_only\\\"] is True\\n\\n\\nasync def test_get_config_returns_mcp_base_url(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that /config includes mcp_base_url for both authenticated and unauthenticated responses.\\\"\\\"\\\"\\n    # Authenticated\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n    assert response.status_code == status.HTTP_200_OK\\n    assert \\\"mcp_base_url\\\" in result, \\\"Authenticated response must contain 'mcp_base_url'\\\"\\n    assert isinstance(result[\\\"mcp_base_url\\\"], str), \\\"mcp_base_url must be a string\\\"\\n\\n    # Unauthenticated\\n    response = await client.get(\\\"api/v1/config\\\")\\n    result = response.json()\\n    assert response.status_code == status.HTTP_200_OK\\n    assert \\\"mcp_base_url\\\" in result, \\\"Public response must contain 'mcp_base_url'\\\"\\n    assert isinstance(result[\\\"mcp_base_url\\\"], str), \\\"mcp_base_url must be a string\\\"\\n\\n\\nasync def test_get_config_mcp_base_url_defaults_to_empty(client: AsyncClient, logged_in_headers: dict):\\n    \\\"\\\"\\\"Test that mcp_base_url defaults to empty string when LANGFLOW_MCP_BASE_URL is not set.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n    assert response.status_code == status.HTTP_200_OK\\n    assert result[\\\"mcp_base_url\\\"] == \\\"\\\"\\n\\n\\nasync def test_get_config_mcp_base_url_from_settings(client: AsyncClient, logged_in_headers: dict, monkeypatch):\\n    \\\"\\\"\\\"Test that mcp_base_url reflects the value from settings.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"mcp_base_url\\\", \\\"https://langflow.example.com\\\")\\n\\n    response = await client.get(\\\"api/v1/config\\\", headers=logged_in_headers)\\n    result = response.json()\\n    assert response.status_code == status.HTTP_200_OK\\n    assert result[\\\"mcp_base_url\\\"] == \\\"https://langflow.example.com\\\"\\n\\n\\nasync def test_deprecated_upload_rejects_unauthenticated(client: AsyncClient, flow):\\n    \\\"\\\"\\\"Regression: the deprecated /api/v1/upload/{flow_id} must require auth.\\n\\n    Previously this endpoint accepted uploads without any credentials, letting\\n    anonymous callers write arbitrary files into a flow's cache folder.\\n    \\\"\\\"\\\"\\n    response = await client.post(\\n        f\\\"api/v1/upload/{flow.id}\\\",\\n        files={\\\"file\\\": (\\\"test.txt\\\", b\\\"test content\\\")},\\n    )\\n    assert response.status_code != status.HTTP_201_CREATED, (\\n        \\\"Deprecated upload endpoint must reject unauthenticated requests\\\"\\n    )\\n    assert response.status_code in {\\n        status.HTTP_401_UNAUTHORIZED,\\n        status.HTTP_403_FORBIDDEN,\\n    }, f\\\"Expected 401/403, got {response.status_code}: {response.text}\\\"\\n\\n\\nasync def test_deprecated_upload_authenticated_succeeds(client: AsyncClient, logged_in_headers: dict, flow):\\n    \\\"\\\"\\\"The deprecated endpoint still works for the flow's owner.\\\"\\\"\\\"\\n    response = await client.post(\\n        f\\\"api/v1/upload/{flow.id}\\\",\\n        files={\\\"file\\\": (\\\"test.txt\\\", b\\\"test content\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED, (\\n        f\\\"Expected 201 for authenticated owner, got {response.status_code}: {response.text}\\\"\\n    )\\n    body = response.json()\\n    assert body[\\\"flowId\\\"] == str(flow.id)\\n\\n\\nasync def test_deprecated_upload_enforces_max_file_size(\\n    client: AsyncClient, logged_in_headers: dict, flow, monkeypatch\\n):\\n    \\\"\\\"\\\"Regression: the deprecated upload route must honor ``max_file_size_upload``.\\n\\n    Without this guard, an authenticated user could still fill disk through\\n    this route by uploading arbitrarily large files, bypassing the limit the\\n    non-deprecated twin at /api/v1/files/upload/{flow_id} already enforces.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"max_file_size_upload\\\", 1)  # 1 MB\\n    oversized = b\\\"x\\\" * (2 * 1024 * 1024)  # 2 MB, exceeds the limit\\n\\n    response = await client.post(\\n        f\\\"api/v1/upload/{flow.id}\\\",\\n        files={\\\"file\\\": (\\\"big.bin\\\", oversized)},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_413_CONTENT_TOO_LARGE, (\\n        f\\\"Expected 413 for oversized upload, got {response.status_code}: {response.text}\\\"\\n    )\\n\\n\\nasync def test_custom_component_runs_trusted_copy_on_hash_collision(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n    tmp_path,\\n):\\n    \\\"\\\"\\\"Restricted mode must run the trusted copy, not colliding attacker bytes.\\n\\n    Security (#13496): the truncated code-hash is the only gate in front of\\n    exec(). A second-preimage collision must NOT run attacker code \u2014 the server\\n    substitutes its own trusted copy keyed by the same hash. Proven end-to-end\\n    with a forced collision and a module-level side-effect sentinel: the attacker\\n    payload writes a file at import time, so if it ever executed the sentinel\\n    would exist. It must not.\\n    \\\"\\\"\\\"\\n    import lfx.utils.flow_validation as fv\\n    from langflow.services.deps import get_settings_service\\n    from lfx.interface.components import component_cache\\n\\n    # The server's trusted copy for the (collided) hash: a benign, buildable component.\\n    trusted_path = Path(__file__).parent.parent.parent.parent / \\\"data\\\" / \\\"dynamic_output_component.py\\\"\\n    trusted_code = await trusted_path.read_text(encoding=\\\"utf-8\\\")\\n\\n    # Attacker payload: valid component whose MODULE-LEVEL code drops a sentinel.\\n    # prepare_global_scope() exec's module-level assignments, so this WOULD fire\\n    # at build time if the client bytes were executed.\\n    sentinel = tmp_path / \\\"pwned.txt\\\"\\n    malicious_code = (\\n        \\\"from lfx.custom import Component\\\\n\\\"\\n        \\\"from lfx.inputs import MessageTextInput\\\\n\\\"\\n        \\\"from lfx.template.field.base import Output\\\\n\\\"\\n        f\\\"_pwn = open({str(sentinel)!r}, 'w').write('pwned')\\\\n\\\"\\n        \\\"class EvilComponent(Component):\\\\n\\\"\\n        '    display_name = \\\"Evil Component\\\"\\\\n'\\n        \\\"    inputs = [MessageTextInput(display_name='Input', name='input_value')]\\\\n\\\"\\n        \\\"    outputs = [Output(display_name='Output', name='output', method='process_input')]\\\\n\\\"\\n        \\\"    def process_input(self) -> str:\\\\n\\\"\\n        \\\"        return 'evil'\\\\n\\\"\\n    )\\n\\n    settings_service = get_settings_service()\\n    # Restricted mode \u2014 the hash gate is the only thing in front of exec().\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", False)\\n\\n    # Force a 48-bit collision: every blob maps to the same known hash.\\n    collision_hash = \\\"c0ffeec0ffee\\\"  # pragma: allowlist secret\\n    monkeypatch.setattr(fv, \\\"_compute_code_hash\\\", lambda _code: collision_hash)\\n\\n    # Seed the cache so the collided hash resolves to the trusted copy. A non-None\\n    # type_to_current_hash stops the endpoint's lazy builder from rebuilding over the seed.\\n    monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", {\\\"EvilComponent\\\": {collision_hash}})\\n    monkeypatch.setattr(component_cache, \\\"all_known_hashes\\\", {collision_hash})\\n    monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {collision_hash: trusted_code})\\n\\n    request = CustomComponentRequest(code=malicious_code)\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    # The trusted copy built successfully (gate passed via the collided hash)...\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n    # ...and the attacker's module-level code NEVER executed.\\n    assert not sentinel.exists(), \\\"Attacker module-level code executed \u2014 trusted-copy substitution failed\\\"\\n\\n\\nasync def test_custom_component_update_runs_trusted_copy_on_hash_collision(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n    tmp_path,\\n):\\n    \\\"\\\"\\\"The /update endpoint must also run the trusted copy on a hash collision.\\n\\n    Mirror of ``test_custom_component_runs_trusted_copy_on_hash_collision`` for\\n    the update path (#13496). In addition to proving the attacker payload never\\n    executes, this asserts the returned node template carries the trusted code \u2014\\n    not the colliding client bytes \u2014 so the substitution can't be undone by\\n    persisting the response into a saved flow and re-building it.\\n    \\\"\\\"\\\"\\n    import lfx.utils.flow_validation as fv\\n    from langflow.services.deps import get_settings_service\\n    from lfx.interface.components import component_cache\\n\\n    trusted_path = Path(__file__).parent.parent.parent.parent / \\\"data\\\" / \\\"dynamic_output_component.py\\\"\\n    trusted_code = await trusted_path.read_text(encoding=\\\"utf-8\\\")\\n\\n    sentinel = tmp_path / \\\"pwned_update.txt\\\"\\n    malicious_code = (\\n        \\\"from lfx.custom import Component\\\\n\\\"\\n        \\\"from lfx.inputs import MessageTextInput\\\\n\\\"\\n        \\\"from lfx.template.field.base import Output\\\\n\\\"\\n        f\\\"_pwn = open({str(sentinel)!r}, 'w').write('pwned')\\\\n\\\"\\n        \\\"class EvilComponent(Component):\\\\n\\\"\\n        '    display_name = \\\"Evil Component\\\"\\\\n'\\n        \\\"    inputs = [MessageTextInput(display_name='Input', name='input_value')]\\\\n\\\"\\n        \\\"    outputs = [Output(display_name='Output', name='output', method='process_input')]\\\\n\\\"\\n        \\\"    def process_input(self) -> str:\\\\n\\\"\\n        \\\"        return 'evil'\\\\n\\\"\\n    )\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", False)\\n\\n    collision_hash = \\\"c0ffeec0ffee\\\"  # pragma: allowlist secret\\n    monkeypatch.setattr(fv, \\\"_compute_code_hash\\\", lambda _code: collision_hash)\\n    monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", {\\\"EvilComponent\\\": {collision_hash}})\\n    monkeypatch.setattr(component_cache, \\\"all_known_hashes\\\", {collision_hash})\\n    monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {collision_hash: trusted_code})\\n\\n    request = UpdateCustomComponentRequest(\\n        code=malicious_code,\\n        frontend_node={\\\"outputs\\\": []},\\n        field=\\\"\\\",\\n        field_value=\\\"\\\",\\n        template={},\\n    )\\n    response = await client.post(\\\"api/v1/custom_component/update\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK, response.json()\\n    # The attacker's module-level code NEVER executed...\\n    assert not sentinel.exists(), \\\"Attacker module-level code executed \u2014 trusted-copy substitution failed\\\"\\n    # ...and the returned node carries the trusted code, not the colliding bytes.\\n    returned_code = response.json().get(\\\"template\\\", {}).get(\\\"code\\\", {}).get(\\\"value\\\")\\n    assert returned_code != malicious_code\\n    assert returned_code == trusted_code\\n\\n\\nasync def test_custom_component_fails_closed_when_no_trusted_copy(\\n    client: AsyncClient,\\n    logged_in_headers: dict,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"Restricted mode must 403 when the hash gate passes but no trusted copy exists.\\n\\n    Security (#13496): if a submitted blob clears the truncated-hash gate but\\n    ``code_by_hash`` has no entry for that hash (e.g. a poisoned/incomplete\\n    index, or a collision against a hash whose source failed the integrity\\n    check), the endpoint must fail closed rather than fall back to client bytes.\\n    \\\"\\\"\\\"\\n    import lfx.utils.flow_validation as fv\\n    from langflow.services.deps import get_settings_service\\n    from lfx.interface.components import component_cache\\n\\n    code = 'from lfx.custom import Component\\\\nclass Anything(Component):\\\\n    display_name = \\\"Anything\\\"\\\\n'\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"allow_custom_components\\\", False)\\n\\n    collision_hash = \\\"c0ffeec0ffee\\\"  # pragma: allowlist secret\\n    monkeypatch.setattr(fv, \\\"_compute_code_hash\\\", lambda _code: collision_hash)\\n    # Gate passes (hash is \\\"known\\\"), but there is no trusted source for it.\\n    monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", {\\\"Anything\\\": {collision_hash}})\\n    monkeypatch.setattr(component_cache, \\\"all_known_hashes\\\", {collision_hash})\\n    monkeypatch.setattr(component_cache, \\\"code_by_hash\\\", {})\\n\\n    request = CustomComponentRequest(code=code)\\n    response = await client.post(\\\"api/v1/custom_component\\\", json=request.model_dump(), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN, response.json()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_execution_principal_contract.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aba10b3fb6afb5cb7a421448d67b148f0bbde29a4bcecb34c3cd6ce8d03bab78\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport copy\\nimport json\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import BackgroundTasks, HTTPException, Request\\nfrom langflow.api.v1.schemas import SimplifiedAPIRequest\\nfrom langflow.events.event_manager import create_stream_tokens_event_manager\\n\\n\\ndef _request() -> Request:\\n    return Request({\\\"type\\\": \\\"http\\\", \\\"headers\\\": []})\\n\\n\\ndef _flow(*, owner_id, data: dict | None = None):\\n    return SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        workspace_id=None,\\n        folder_id=None,\\n        name=\\\"shared-flow\\\",\\n        data=data or {\\\"nodes\\\": [], \\\"edges\\\": []},\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"stream\\\", [False, True])\\nasync def test_v1_run_non_owner_tweaks_are_hidden_as_not_found(\\n    monkeypatch: pytest.MonkeyPatch,\\n    stream: bool,  # noqa: FBT001\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    owner_id = uuid4()\\n    caller = SimpleNamespace(id=uuid4(), is_superuser=False)\\n\\n    async def execution_must_not_start(**_kwargs):\\n        message = \\\"delegated tweaks must be rejected before execution\\\"\\n        raise AssertionError(message)\\n\\n    async def stream_execution_must_not_start(**kwargs):\\n        await kwargs[\\\"event_manager\\\"].queue.put((None, None, 0.0))\\n\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_telemetry_service\\\",\\n        lambda: SimpleNamespace(log_package_run=AsyncMock()),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"simple_run_flow\\\", execution_must_not_start)\\n    monkeypatch.setattr(endpoints, \\\"run_flow_generator\\\", stream_execution_must_not_start)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints._run_flow_internal(\\n            background_tasks=BackgroundTasks(),\\n            flow=_flow(owner_id=owner_id),\\n            input_request=SimplifiedAPIRequest(\\n                input_value=\\\"hello\\\",\\n                input_type=\\\"chat\\\",\\n                output_type=\\\"chat\\\",\\n                tweaks={\\\"ChatInput-1\\\": {\\\"input_value\\\": \\\"owner-only override\\\"}},\\n            ),\\n            stream=stream,\\n            api_key_user=caller,\\n            context=None,\\n            http_request=_request(),\\n        )\\n\\n    assert exc_info.value.status_code == 404\\n    assert exc_info.value.detail == \\\"Flow not found\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"expose_error_details\\\", [False, True])\\nasync def test_run_flow_generator_error_depends_on_explicit_policy(\\n    monkeypatch: pytest.MonkeyPatch,\\n    expose_error_details: bool,  # noqa: FBT001\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    sensitive_detail = \\\"owner-provider-secret\\\"\\n\\n    async def fail_run(**_kwargs):\\n        raise RuntimeError(sensitive_detail)\\n\\n    monkeypatch.setattr(endpoints, \\\"simple_run_flow\\\", fail_run)\\n    queue: asyncio.Queue = asyncio.Queue()\\n    consumed: asyncio.Queue = asyncio.Queue()\\n    event_manager = create_stream_tokens_event_manager(queue)\\n\\n    await endpoints.run_flow_generator(\\n        flow=_flow(owner_id=uuid4()),\\n        input_request=SimplifiedAPIRequest(input_value=\\\"hello\\\"),\\n        api_key_user=SimpleNamespace(id=uuid4()),\\n        event_manager=event_manager,\\n        client_consumed_queue=consumed,\\n        expose_error_details=expose_error_details,\\n    )\\n\\n    events: list[dict] = []\\n    while not queue.empty():\\n        _event_id, payload, _timestamp = queue.get_nowait()\\n        if payload is not None:\\n            events.append(json.loads(payload))\\n    [error_event] = [event for event in events if event[\\\"event\\\"] == \\\"error\\\"]\\n    wire_error = error_event[\\\"data\\\"][\\\"error\\\"]\\n    if expose_error_details:\\n        assert sensitive_detail in wire_error\\n    else:\\n        assert wire_error == \\\"Workflow execution failed.\\\"\\n        assert sensitive_detail not in json.dumps(events)\\n\\n\\n@pytest.mark.parametrize(\\\"caller_kind\\\", [\\\"delegate\\\", \\\"owner\\\"])\\nasync def test_v1_run_stream_route_derives_error_policy_from_flow_ownership(\\n    monkeypatch: pytest.MonkeyPatch,\\n    caller_kind: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    owner_id = uuid4()\\n    caller_id = owner_id if caller_kind == \\\"owner\\\" else uuid4()\\n    captured: dict = {}\\n\\n    async def capture_run(**kwargs):\\n        captured.update(kwargs)\\n        await kwargs[\\\"event_manager\\\"].queue.put((None, None, 0.0))\\n\\n    monkeypatch.setattr(endpoints, \\\"run_flow_generator\\\", capture_run)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_telemetry_service\\\",\\n        lambda: SimpleNamespace(log_package_run=AsyncMock()),\\n    )\\n\\n    response = await endpoints._run_flow_internal(\\n        background_tasks=BackgroundTasks(),\\n        flow=_flow(owner_id=owner_id),\\n        input_request=SimplifiedAPIRequest(input_value=\\\"hello\\\"),\\n        stream=True,\\n        api_key_user=SimpleNamespace(id=caller_id),\\n        context=None,\\n        http_request=_request(),\\n    )\\n    _ = [chunk async for chunk in response.body_iterator]\\n    if response.background is not None:\\n        await response.background()\\n\\n    assert captured[\\\"expose_error_details\\\"] is (caller_kind == \\\"owner\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"caller_kind\\\", [\\\"delegate\\\", \\\"owner\\\"])\\nasync def test_v1_run_sync_error_depends_on_flow_ownership(\\n    monkeypatch: pytest.MonkeyPatch,\\n    caller_kind: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    sensitive_detail = \\\"owner-sync-provider-secret\\\"\\n    sensitive_component_id = \\\"PrivateProviderNode-secret-id\\\"\\n    owner_id = uuid4()\\n    caller_id = owner_id if caller_kind == \\\"owner\\\" else uuid4()\\n    flow = _flow(\\n        owner_id=owner_id,\\n        data={\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": sensitive_component_id,\\n                    \\\"data\\\": {\\\"node\\\": {\\\"lf_version\\\": \\\"0.0.0\\\"}},\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    )\\n\\n    async def fail_run(**_kwargs):\\n        raise RuntimeError(sensitive_detail)\\n\\n    monkeypatch.setattr(endpoints, \\\"simple_run_flow\\\", fail_run)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_telemetry_service\\\",\\n        lambda: SimpleNamespace(log_package_run=AsyncMock()),\\n    )\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints._run_flow_internal(\\n            background_tasks=BackgroundTasks(),\\n            flow=flow,\\n            input_request=SimplifiedAPIRequest(input_value=\\\"hello\\\"),\\n            stream=False,\\n            api_key_user=SimpleNamespace(id=caller_id),\\n            context=None,\\n            http_request=_request(),\\n        )\\n\\n    if caller_kind == \\\"owner\\\":\\n        assert sensitive_detail in str(exc_info.value.detail)\\n        assert sensitive_component_id in str(exc_info.value.detail)\\n    else:\\n        assert \\\"Workflow execution failed.\\\" in str(exc_info.value.detail)\\n        assert sensitive_detail not in str(exc_info.value.detail)\\n        assert sensitive_component_id not in str(exc_info.value.detail)\\n\\n\\nasync def test_v1_advanced_shared_flow_executes_as_caller_without_owner_requery(\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    flow = _flow(owner_id=owner_id)\\n    graph = SimpleNamespace(run_id=None)\\n    captured: dict = {}\\n\\n    def fake_from_payload(data, **kwargs):\\n        captured.update({\\\"data\\\": data, **kwargs})\\n        return graph\\n\\n    async def fake_run_graph_internal(**kwargs):\\n        captured[\\\"runtime_graph\\\"] = kwargs[\\\"graph\\\"]\\n        return [], \\\"delegate-session\\\"\\n\\n    session = SimpleNamespace(\\n        exec=AsyncMock(side_effect=AssertionError(\\\"advanced run must not re-query by owner\\\")),\\n        in_transaction=lambda: False,\\n        commit=AsyncMock(),\\n    )\\n    task_service = SimpleNamespace(fire_and_forget_task=AsyncMock())\\n    monkeypatch.setattr(endpoints.Graph, \\\"from_payload\\\", fake_from_payload)\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(endpoints, \\\"get_session_service\\\", lambda: SimpleNamespace())\\n    monkeypatch.setattr(endpoints, \\\"run_graph_internal\\\", fake_run_graph_internal)\\n    monkeypatch.setattr(endpoints, \\\"get_task_service\\\", lambda: task_service)\\n    monkeypatch.setattr(endpoints, \\\"get_memory_base_service\\\", lambda: SimpleNamespace(on_flow_output=MagicMock()))\\n\\n    response = await endpoints.experimental_run_flow(\\n        session=session,\\n        flow=flow,\\n        inputs=None,\\n        outputs=None,\\n        tweaks=None,\\n        stream=False,\\n        session_id=None,\\n        api_key_user=SimpleNamespace(id=caller_id),\\n    )\\n\\n    assert response.status_code == 200\\n    assert captured[\\\"flow_id\\\"] == str(flow.id)\\n    assert captured[\\\"user_id\\\"] == str(caller_id)\\n    assert captured[\\\"runtime_graph\\\"] is graph\\n    session.exec.assert_not_awaited()\\n    task_service.fire_and_forget_task.assert_not_awaited()\\n\\n\\n@pytest.mark.parametrize(\\\"cache_mismatch\\\", [\\\"component_principal\\\", \\\"flow_identity\\\"])\\nasync def test_v1_advanced_shared_session_rebuilds_mismatched_real_graph_for_caller(\\n    monkeypatch: pytest.MonkeyPatch,\\n    cache_mismatch: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n    from lfx.components.input_output.chat import ChatInput\\n\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    flow_data = {\\n        \\\"nodes\\\": [ChatInput(_id=\\\"ChatInput-execution-principal\\\").to_frontend_node()],\\n        \\\"edges\\\": [],\\n    }\\n    flow = _flow(owner_id=owner_id, data=copy.deepcopy(flow_data))\\n    cached_component_user_id = owner_id if cache_mismatch == \\\"component_principal\\\" else caller_id\\n    cached_flow_id = flow.id if cache_mismatch == \\\"component_principal\\\" else uuid4()\\n    cached_graph = endpoints.Graph.from_payload(\\n        copy.deepcopy(flow_data),\\n        flow_id=str(cached_flow_id),\\n        user_id=str(cached_component_user_id),\\n        flow_name=flow.name,\\n    )\\n    cached_components = [vertex.custom_component for vertex in cached_graph.vertices if vertex.custom_component]\\n    assert cached_components\\n    assert all(str(component.user_id) == str(cached_component_user_id) for component in cached_components)\\n\\n    if cache_mismatch == \\\"component_principal\\\":\\n        # Reproduce the old unsafe \\\"fix\\\": the graph principal changes while its\\n        # already-instantiated components retain the owner's credential principal.\\n        cached_graph.user_id = str(caller_id)\\n        assert all(str(component.user_id) == str(owner_id) for component in cached_components)\\n    captured: dict = {}\\n\\n    async def fake_run_graph_internal(**kwargs):\\n        captured.update(kwargs)\\n        return [], \\\"delegate-session\\\"\\n\\n    session = SimpleNamespace(in_transaction=lambda: False, commit=AsyncMock())\\n    session_service = SimpleNamespace(load_session=AsyncMock(return_value=(cached_graph, None)))\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(endpoints, \\\"get_session_service\\\", lambda: session_service)\\n    monkeypatch.setattr(endpoints, \\\"run_graph_internal\\\", fake_run_graph_internal)\\n    monkeypatch.setattr(endpoints, \\\"get_task_service\\\", lambda: SimpleNamespace(fire_and_forget_task=AsyncMock()))\\n    monkeypatch.setattr(endpoints, \\\"get_memory_base_service\\\", lambda: SimpleNamespace(on_flow_output=MagicMock()))\\n\\n    response = await endpoints.experimental_run_flow(\\n        session=session,\\n        flow=flow,\\n        inputs=None,\\n        outputs=None,\\n        tweaks=None,\\n        stream=False,\\n        session_id=str(flow.id),\\n        api_key_user=SimpleNamespace(id=caller_id),\\n    )\\n\\n    assert response.status_code == 200\\n    caller_graph = captured[\\\"graph\\\"]\\n    assert caller_graph is not cached_graph\\n    assert caller_graph.flow_id == str(flow.id)\\n    assert caller_graph.user_id == str(caller_id)\\n    caller_components = [vertex.custom_component for vertex in caller_graph.vertices if vertex.custom_component]\\n    assert caller_components\\n    assert all(str(component.user_id) == str(caller_id) for component in caller_components)\\n\\n\\nasync def test_v1_advanced_non_owner_tweaks_are_hidden_as_not_found(monkeypatch: pytest.MonkeyPatch) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    session = SimpleNamespace(\\n        exec=AsyncMock(return_value=SimpleNamespace(first=lambda: None)),\\n        in_transaction=lambda: False,\\n    )\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(endpoints, \\\"get_session_service\\\", lambda: SimpleNamespace())\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints.experimental_run_flow(\\n            session=session,\\n            flow=_flow(owner_id=uuid4()),\\n            inputs=None,\\n            outputs=None,\\n            tweaks={\\\"ChatInput-1\\\": {\\\"input_value\\\": \\\"owner-only override\\\"}},\\n            stream=False,\\n            session_id=None,\\n            api_key_user=SimpleNamespace(id=uuid4()),\\n        )\\n\\n    assert exc_info.value.status_code == 404\\n    assert exc_info.value.detail == \\\"Flow not found\\\"\\n    session.exec.assert_not_awaited()\\n\\n\\nasync def test_v1_advanced_owner_tweaks_do_not_mutate_loaded_flow_data(monkeypatch: pytest.MonkeyPatch) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    owner_id = uuid4()\\n    flow = _flow(\\n        owner_id=owner_id,\\n        data={\\\"nodes\\\": [{\\\"id\\\": \\\"Component-1\\\", \\\"data\\\": {\\\"value\\\": \\\"stored\\\"}}], \\\"edges\\\": []},\\n    )\\n    original_data = copy.deepcopy(flow.data)\\n    captured: dict = {}\\n\\n    def mutating_process_tweaks(graph_data, _tweaks):\\n        graph_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"value\\\"] = \\\"request override\\\"\\n        return graph_data\\n\\n    def fake_from_payload(graph_data, **_kwargs):\\n        captured[\\\"graph_data\\\"] = graph_data\\n        return SimpleNamespace(run_id=None)\\n\\n    monkeypatch.setattr(endpoints, \\\"process_tweaks\\\", mutating_process_tweaks)\\n    monkeypatch.setattr(endpoints.Graph, \\\"from_payload\\\", fake_from_payload)\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(endpoints, \\\"run_graph_internal\\\", AsyncMock(return_value=([], \\\"owner-session\\\")))\\n    monkeypatch.setattr(endpoints, \\\"get_task_service\\\", lambda: SimpleNamespace(fire_and_forget_task=AsyncMock()))\\n    monkeypatch.setattr(endpoints, \\\"get_memory_base_service\\\", lambda: SimpleNamespace(on_flow_output=MagicMock()))\\n\\n    response = await endpoints.experimental_run_flow(\\n        session=SimpleNamespace(in_transaction=lambda: False, commit=AsyncMock()),\\n        flow=flow,\\n        inputs=None,\\n        outputs=None,\\n        tweaks={\\\"Component-1\\\": {\\\"value\\\": \\\"request override\\\"}},\\n        stream=False,\\n        session_id=None,\\n        api_key_user=SimpleNamespace(id=owner_id),\\n    )\\n\\n    assert response.status_code == 200\\n    assert flow.data == original_data\\n    assert captured[\\\"graph_data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"value\\\"] == \\\"request override\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"caller_kind\\\", [\\\"delegate\\\", \\\"owner\\\"])\\nasync def test_v1_advanced_http_validation_error_depends_on_flow_ownership(\\n    monkeypatch: pytest.MonkeyPatch,\\n    caller_kind: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    sensitive_detail = \\\"owner-HITL-validation-detail\\\"\\n    owner_id = uuid4()\\n    caller_id = owner_id if caller_kind == \\\"owner\\\" else uuid4()\\n    session = SimpleNamespace(in_transaction=lambda: False)\\n\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"raise_if_hitl_unsupported\\\",\\n        MagicMock(side_effect=HTTPException(status_code=400, detail=sensitive_detail)),\\n    )\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints.experimental_run_flow(\\n            session=session,\\n            flow=_flow(owner_id=owner_id),\\n            inputs=None,\\n            outputs=None,\\n            tweaks=None,\\n            stream=False,\\n            session_id=None,\\n            api_key_user=SimpleNamespace(id=caller_id),\\n        )\\n\\n    if caller_kind == \\\"owner\\\":\\n        assert exc_info.value.status_code == 400\\n        assert sensitive_detail in str(exc_info.value.detail)\\n    else:\\n        assert exc_info.value.status_code == 400\\n        assert exc_info.value.detail == \\\"Workflow execution failed.\\\"\\n        assert sensitive_detail not in str(exc_info.value.detail)\\n\\n\\n@pytest.mark.parametrize(\\\"caller_kind\\\", [\\\"delegate\\\", \\\"owner\\\"])\\nasync def test_v1_advanced_missing_data_error_depends_on_flow_ownership(\\n    monkeypatch: pytest.MonkeyPatch,\\n    caller_kind: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    owner_id = uuid4()\\n    caller_id = owner_id if caller_kind == \\\"owner\\\" else uuid4()\\n    flow = _flow(owner_id=owner_id)\\n    flow.data = None\\n    session = SimpleNamespace(in_transaction=lambda: False)\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints.experimental_run_flow(\\n            session=session,\\n            flow=flow,\\n            inputs=None,\\n            outputs=None,\\n            tweaks=None,\\n            stream=False,\\n            session_id=None,\\n            api_key_user=SimpleNamespace(id=caller_id),\\n        )\\n\\n    if caller_kind == \\\"owner\\\":\\n        assert exc_info.value.status_code == 404\\n        assert str(flow.id) in str(exc_info.value.detail)\\n    else:\\n        assert exc_info.value.status_code == 500\\n        assert exc_info.value.detail == \\\"Workflow execution failed.\\\"\\n        assert str(flow.id) not in str(exc_info.value.detail)\\n\\n\\n@pytest.mark.parametrize(\\\"caller_kind\\\", [\\\"delegate\\\", \\\"owner\\\"])\\nasync def test_v1_advanced_error_depends_on_flow_ownership(\\n    monkeypatch: pytest.MonkeyPatch,\\n    caller_kind: str,\\n) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    sensitive_detail = \\\"owner-advanced-provider-secret\\\"\\n    owner_id = uuid4()\\n    caller_id = owner_id if caller_kind == \\\"owner\\\" else uuid4()\\n    graph = SimpleNamespace(run_id=None)\\n    session = SimpleNamespace(in_transaction=lambda: False, commit=AsyncMock())\\n\\n    monkeypatch.setattr(endpoints, \\\"ensure_flow_permission\\\", AsyncMock())\\n    monkeypatch.setattr(endpoints.Graph, \\\"from_payload\\\", lambda *_args, **_kwargs: graph)\\n    monkeypatch.setattr(endpoints, \\\"run_graph_internal\\\", AsyncMock(side_effect=RuntimeError(sensitive_detail)))\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await endpoints.experimental_run_flow(\\n            session=session,\\n            flow=_flow(owner_id=owner_id),\\n            inputs=None,\\n            outputs=None,\\n            tweaks=None,\\n            stream=False,\\n            session_id=None,\\n            api_key_user=SimpleNamespace(id=caller_id),\\n        )\\n\\n    if caller_kind == \\\"owner\\\":\\n        assert sensitive_detail in str(exc_info.value.detail)\\n    else:\\n        assert exc_info.value.detail == \\\"Workflow execution failed.\\\"\\n        assert sensitive_detail not in str(exc_info.value.detail)\\n\\n\\nasync def test_webhook_server_generated_tweaks_remain_trusted(monkeypatch: pytest.MonkeyPatch) -> None:\\n    from langflow.api.v1 import endpoints\\n\\n    generated_tweaks = {\\\"Webhook-1\\\": {\\\"data\\\": '{\\\"trusted\\\":\\\"server mapping\\\"}'}}\\n    captured: dict = {}\\n\\n    async def fake_run(**kwargs):\\n        captured.update(kwargs)\\n        return SimpleNamespace()\\n\\n    monkeypatch.setattr(endpoints, \\\"simple_run_flow\\\", fake_run)\\n    flow = _flow(owner_id=uuid4())\\n    await endpoints.simple_run_flow_task(\\n        flow=flow,\\n        input_request=SimplifiedAPIRequest(input_value=\\\"\\\", tweaks=generated_tweaks),\\n        api_key_user=SimpleNamespace(id=flow.user_id),\\n        emit_events=False,\\n    )\\n\\n    assert captured[\\\"input_request\\\"].tweaks.root == generated_tweaks\\n    assert captured[\\\"expose_error_details\\\"] is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_export_secret_sanitization.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b74d8b0292b330be7bfc272f209bab88009054d1e02e46743847e61dfd790e50\",\"content\":\"\\\"\\\"\\\"Regression tests for LE-2240.\\n\\nFlow and project export paths must not emit cleartext secrets. The legacy\\n``remove_api_keys`` scrubber only nulled fields that were *both* marked\\n``password`` and named like an API key, so a ``password``-marked field under an\\nordinary name (``plain_password``, ``service_token``) and a credential-bearing\\nconnection string were exported verbatim.\\n\\nCovered export boundaries:\\n\\n* ``POST /api/v1/flows/download/``            (``flows_helpers._build_flows_download_response``)\\n* ``GET  /api/v1/projects/download/{id}``     (``projects_files.download_project_flows``)\\n* flow-version reads with ``strip_keys=True`` (``flow_version.strip_version_data``)\\n\\\"\\\"\\\"\\n\\nimport io\\nimport json\\nimport zipfile\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.api.v1.flow_version import strip_version_data\\nfrom langflow.services.database.models.flow.model import Flow, FlowCreate\\nfrom langflow.utils.flow_secrets import strip_flow_secrets, strip_secret_field_values\\nfrom lfx.services.deps import session_scope\\n\\n# Values that must never survive an export.\\n_SECRET_PASSWORD = \\\"secret-pass\\\"  # noqa: S105  # pragma: allowlist secret\\n_SECRET_TOKEN = \\\"tok-DEADBEEF\\\"  # noqa: S105  # pragma: allowlist secret\\n_SECRET_API_KEY = \\\"sk-SUPERSECRET\\\"  # noqa: S105  # pragma: allowlist secret\\n_SECRET_DSN = \\\"postgresql://user:pass@db/app\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n_LEAKED_VALUES = (_SECRET_PASSWORD, _SECRET_TOKEN, _SECRET_API_KEY, _SECRET_DSN)\\n\\n\\ndef _secret_flow_data() -> dict:\\n    \\\"\\\"\\\"Flow data whose node carries secrets the legacy scrubber missed.\\\"\\\"\\\"\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"node-1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"position\\\": {\\\"x\\\": 0, \\\"y\\\": 0},\\n                \\\"data\\\": {\\n                    \\\"id\\\": \\\"node-1\\\",\\n                    \\\"type\\\": \\\"SomeComponent\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            # password-marked, name does NOT match api/key/token\\n                            \\\"plain_password\\\": {\\n                                \\\"name\\\": \\\"password\\\",\\n                                \\\"password\\\": True,\\n                                \\\"value\\\": _SECRET_PASSWORD,\\n                                \\\"type\\\": \\\"str\\\",\\n                            },\\n                            # password-marked, secret-shaped name the legacy\\n                            # has_api_terms() check still rejects (\\\"token\\\"\\n                            # alone does not contain \\\"api\\\")\\n                            \\\"service_token\\\": {\\n                                \\\"name\\\": \\\"service_token\\\",\\n                                \\\"password\\\": True,\\n                                \\\"value\\\": _SECRET_TOKEN,\\n                                \\\"type\\\": \\\"str\\\",\\n                            },\\n                            # credential-bearing connection string, not marked password\\n                            \\\"database_url\\\": {\\n                                \\\"name\\\": \\\"database_url\\\",\\n                                \\\"password\\\": False,\\n                                \\\"value\\\": _SECRET_DSN,\\n                                \\\"type\\\": \\\"str\\\",\\n                            },\\n                            # the one case the legacy scrubber did handle\\n                            \\\"api_key\\\": {\\n                                \\\"name\\\": \\\"api_key\\\",\\n                                \\\"password\\\": True,\\n                                \\\"value\\\": _SECRET_API_KEY,\\n                                \\\"type\\\": \\\"str\\\",\\n                            },\\n                            # non-secret field must survive untouched\\n                            \\\"base_url\\\": {\\n                                \\\"name\\\": \\\"base_url\\\",\\n                                \\\"password\\\": False,\\n                                \\\"value\\\": \\\"https://api.openai.com/v1\\\",\\n                                \\\"type\\\": \\\"str\\\",\\n                            },\\n                        }\\n                    },\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\ndef _assert_scrubbed(flow_dict: dict) -> None:\\n    \\\"\\\"\\\"Every secret value is nulled and the public field is preserved.\\\"\\\"\\\"\\n    template = flow_dict[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n    assert template[\\\"plain_password\\\"][\\\"value\\\"] is None\\n    assert template[\\\"service_token\\\"][\\\"value\\\"] is None\\n    assert template[\\\"database_url\\\"][\\\"value\\\"] is None\\n    assert template[\\\"api_key\\\"][\\\"value\\\"] is None\\n    assert template[\\\"base_url\\\"][\\\"value\\\"] == \\\"https://api.openai.com/v1\\\"\\n\\n    # Belt-and-braces: no secret literal anywhere in the serialized payload.\\n    serialized = json.dumps(flow_dict)\\n    for secret in _LEAKED_VALUES:\\n        assert secret not in serialized\\n\\n\\nasync def _create_flow(active_user, *, folder_id=None) -> str:\\n    async with session_scope() as session:\\n        flow_create = FlowCreate(\\n            name=\\\"le2240-export-secret-flow\\\",\\n            description=\\\"regression flow for export secret sanitization\\\",\\n            data=_secret_flow_data(),\\n            folder_id=folder_id,\\n            user_id=active_user.id,\\n        )\\n        flow = Flow.model_validate(flow_create.model_dump(exclude={\\\"id\\\"}))\\n        session.add(flow)\\n        await session.flush()\\n        await session.refresh(flow)\\n        flow_id = str(flow.id)\\n        await session.commit()\\n    return flow_id\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_flows_download_strips_non_api_password_fields(client: AsyncClient, logged_in_headers, active_user):\\n    \\\"\\\"\\\"POST /api/v1/flows/download/ must not emit cleartext secrets.\\\"\\\"\\\"\\n    flow_id = await _create_flow(active_user)\\n\\n    response = await client.post(\\\"api/v1/flows/download/\\\", json=[flow_id], headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_200_OK\\n\\n    _assert_scrubbed(response.json())\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_project_download_strips_non_api_password_fields(client: AsyncClient, logged_in_headers, active_user):\\n    \\\"\\\"\\\"GET /api/v1/projects/download/{project_id} must not emit cleartext secrets.\\\"\\\"\\\"\\n    create_response = await client.post(\\n        \\\"api/v1/projects/\\\",\\n        json={\\\"name\\\": \\\"le2240-project\\\", \\\"description\\\": \\\"\\\", \\\"components_list\\\": [], \\\"flows_list\\\": []},\\n        headers=logged_in_headers,\\n    )\\n    assert create_response.status_code == status.HTTP_201_CREATED\\n    project_id = create_response.json()[\\\"id\\\"]\\n\\n    await _create_flow(active_user, folder_id=project_id)\\n\\n    response = await client.get(f\\\"api/v1/projects/download/{project_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_200_OK\\n\\n    with zipfile.ZipFile(io.BytesIO(response.content), \\\"r\\\") as zip_file:\\n        names = zip_file.namelist()\\n        assert len(names) == 1\\n        _assert_scrubbed(json.loads(zip_file.read(names[0])))\\n\\n\\ndef test_strip_version_data_strips_non_api_password_fields():\\n    \\\"\\\"\\\"Flow-version reads with strip_keys=True must not emit cleartext secrets.\\\"\\\"\\\"\\n    stripped = strip_version_data(_secret_flow_data())\\n\\n    assert stripped is not None\\n    _assert_scrubbed({\\\"data\\\": stripped})\\n\\n\\ndef test_strip_version_data_does_not_mutate_input():\\n    \\\"\\\"\\\"The scrubber returns a detached copy rather than clearing stored data.\\\"\\\"\\\"\\n    original = _secret_flow_data()\\n    strip_version_data(original)\\n\\n    template = original[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert template[\\\"plain_password\\\"][\\\"value\\\"] == _SECRET_PASSWORD\\n    assert template[\\\"database_url\\\"][\\\"value\\\"] == _SECRET_DSN\\n\\n\\ndef test_strip_secret_field_values_detaches_empty_mapping():\\n    \\\"\\\"\\\"An empty ``data`` mapping must still be copied, not aliased.\\n\\n    ``strip_flow_secrets`` documents that the returned envelope's ``data`` is detached so\\n    the caller never mutates the ORM-backed payload it serialized from. A falsy-but-present\\n    mapping previously short-circuited and returned the caller's own object.\\n    \\\"\\\"\\\"\\n    original: dict = {}\\n\\n    result = strip_secret_field_values(original)\\n\\n    assert result == {}\\n    assert result is not original\\n    result[\\\"injected\\\"] = True\\n    assert original == {}\\n\\n\\ndef test_strip_flow_secrets_detaches_empty_data():\\n    \\\"\\\"\\\"The envelope wrapper must not alias an empty ``data`` mapping either.\\\"\\\"\\\"\\n    flow = {\\\"name\\\": \\\"empty\\\", \\\"data\\\": {}}\\n\\n    scrubbed = strip_flow_secrets(flow)\\n\\n    assert scrubbed[\\\"data\\\"] == {}\\n    assert scrubbed[\\\"data\\\"] is not flow[\\\"data\\\"]\\n    scrubbed[\\\"data\\\"][\\\"injected\\\"] = True\\n    assert flow[\\\"data\\\"] == {}\\n\\n\\ndef test_strip_secret_field_values_still_passes_none_through():\\n    \\\"\\\"\\\"``None`` remains a pass-through so callers can distinguish absent data.\\\"\\\"\\\"\\n    assert strip_secret_field_values(None) is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_extension_events_endpoint.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"54b3dc8621f397b12137a19a632913d71fd24957140a22748aff33f179dad9e1\",\"content\":\"\\\"\\\"\\\"Tests for the GET /extensions/events controller.\\n\\nThe keyspace is server-derived from the authenticated user; a client-supplied\\n``keyspace`` query parameter is rejected with 422 so the contract is explicit.\\nPreviously the parameter was silently dropped, which masked client bugs that\\nassumed it had effect.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom fastapi import HTTPException, status\\nfrom langflow.api.v1.extensions import get_extension_events\\n\\n\\ndef _user(user_id: str = \\\"alice-id\\\") -> SimpleNamespace:\\n    return SimpleNamespace(id=user_id)\\n\\n\\nasync def test_keyspace_query_param_is_rejected_with_typed_422(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"Passing ``?keyspace=...`` must surface a typed 422 envelope.\\n\\n    The body shape must match every other typed-error response in the\\n    extensions router so clients render the same fix-hint envelope.\\n    \\\"\\\"\\\"\\n    # The service must not be touched on the rejection path.\\n    sentinel_svc = MagicMock()\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.extensions.get_extension_events_service\\\",\\n        lambda: sentinel_svc,\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await get_extension_events(\\n            current_user=_user(),\\n            since=0.0,\\n            keyspace=\\\"user:bob-id\\\",\\n        )\\n\\n    assert exc.value.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n    detail = exc.value.detail\\n    assert isinstance(detail, dict)\\n    assert detail[\\\"code\\\"] == \\\"extension-events-keyspace-forbidden\\\"\\n    assert detail[\\\"location\\\"] == \\\"query.keyspace\\\"\\n    assert detail[\\\"content\\\"] == \\\"user:bob-id\\\"\\n    assert detail[\\\"hint\\\"]\\n    assert detail[\\\"ref_url\\\"] == \\\"https://docs.langflow.org/extensions/errors\\\"\\n    sentinel_svc.since.assert_not_called()\\n\\n\\nasync def test_empty_string_keyspace_is_also_rejected(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"``?keyspace=`` (empty string) still indicates client intent and is rejected.\\n\\n    Only the unset/absent case (None) is permitted -- otherwise a buggy\\n    client could pass an empty value and silently get the user-scoped\\n    response, defeating the explicit-contract goal of this 422.\\n    \\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.extensions.get_extension_events_service\\\",\\n        lambda: MagicMock(),\\n    )\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await get_extension_events(current_user=_user(), since=0.0, keyspace=\\\"\\\")\\n\\n    assert exc.value.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n    assert exc.value.detail[\\\"code\\\"] == \\\"extension-events-keyspace-forbidden\\\"\\n\\n\\nasync def test_request_without_keyspace_returns_events(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The normal path (no keyspace param) is unaffected.\\n\\n    Regression guard against accidentally tightening the contract for\\n    callers that already follow it (the frontend hook and any future CLI\\n    pollers send only ``since``).\\n    \\\"\\\"\\\"\\n    svc = MagicMock()\\n    svc.since.return_value = ([], True)\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.extensions.get_extension_events_service\\\",\\n        lambda: svc,\\n    )\\n\\n    response = await get_extension_events(current_user=_user(\\\"alice-id\\\"), since=1.5)\\n\\n    assert response.events == []\\n    assert response.settled is True\\n    # The server-derived keyspace must still be ``user:{id}``; the\\n    # endpoint must not have started accepting client-supplied values.\\n    svc.since.assert_called_once_with(1.5, \\\"user:alice-id\\\")\\n\\n\\nasync def test_service_unavailable_short_circuits_without_touching_keyspace_check(\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"When the service is None the endpoint returns an empty settled response.\\n\\n    The keyspace rejection must run BEFORE this short-circuit so a client\\n    that passes ``?keyspace=...`` still sees a typed 422 rather than an\\n    empty 200 (which would be a silent success for an explicitly invalid\\n    request).\\n    \\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.extensions.get_extension_events_service\\\",\\n        lambda: None,\\n    )\\n\\n    # Without keyspace: empty settled response.\\n    response = await get_extension_events(current_user=_user(), since=0.0)\\n    assert response.events == []\\n    assert response.settled is True\\n\\n    # With keyspace: still 422, even though the service is unavailable.\\n    with pytest.raises(HTTPException) as exc:\\n        await get_extension_events(current_user=_user(), since=0.0, keyspace=\\\"global\\\")\\n    assert exc.value.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n    assert exc.value.detail[\\\"code\\\"] == \\\"extension-events-keyspace-forbidden\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_extensions_route_guard.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only";
